"""Accounting-only transport for JavaScript subagents."""

from __future__ import annotations

import asyncio
import dataclasses
import hashlib
import itertools
import json
import logging
import math
from collections.abc import Mapping
from typing import TYPE_CHECKING, override

from langchain_core.tools import StructuredTool
from langchain_quickjs import CodeInterpreterMiddleware
from langgraph.checkpoint.base import (
    BaseCheckpointSaver,
    CheckpointMetadata,
    empty_checkpoint,
)
from langgraph.config import get_config
from langgraph.errors import GraphBubbleUp, NodeCancelledError
from langgraph.types import Command

from deepagents_code.cost_tracking import (
    _empty_cost_breakdown,
    _merge_cost_breakdowns,
    _parent_checkpoint_scope,
)
from deepagents_code.thread_ownership import OWNER_KEY

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable

    from langchain.agents.middleware.types import ModelRequest
    from langchain_core.messages import ToolMessage
    from langchain_core.runnables import RunnableConfig
    from langgraph.prebuilt.tool_node import ToolCallRequest, ToolRuntime

    from deepagents_code.cost_tracking import CostBreakdown

logger = logging.getLogger(__name__)

_ACCOUNTING_KEY = "__deepagents_js_cost_owner"
_RESPONSE_FORMAT_KEY = "__deepagents_subagent_response_format"


class _ReceiptMetadata(CheckpointMetadata):
    js_cost_owner: str


def _digest(value: str) -> str:
    """Return a hashed identity without storing prompts in checkpoint names."""
    return hashlib.sha256(value.encode()).hexdigest()


class CostAwareCodeInterpreterMiddleware(CodeInterpreterMiddleware):
    """Transport cost receipts without caching JavaScript or forwarding state."""

    @override
    def _prepare_for_call(self, request: ModelRequest) -> str:
        """Return a compact reference while retaining all PTC bindings."""
        from langchain_core.tools import BaseTool
        from langchain_quickjs.middleware import render_ptc_prompt

        tools = [tool for tool in request.tools if isinstance(tool, BaseTool)]
        prompt = super()._prepare_for_call(request.override(tools=list(tools)))
        slot = self._slot_id(request.state)
        cached = self._ptc_prompt_by_slot.get(slot)
        if cached is None:
            return prompt
        exposed, reference = cached
        visible = [
            tool for tool in exposed if not (tool.extras or {}).get("defer_loading")
        ]
        if len(visible) == len(exposed):
            return prompt
        replacement = render_ptc_prompt(visible, tool_name=self._tool_name)
        return prompt.removesuffix(reference) + replacement

    @override
    def wrap_tool_call(
        self,
        request: ToolCallRequest,
        handler: Callable[[ToolCallRequest], ToolMessage | Command],
    ) -> ToolMessage | Command:
        """Preserve synchronous execution; receipt transport is async-only.

        Args:
            request: Tool call and its runtime context.
            handler: Synchronous tool executor.

        Returns:
            The tool result without modification.
        """
        return handler(request)

    async def awrap_tool_call(
        self,
        request: ToolCallRequest,
        handler: Callable[[ToolCallRequest], Awaitable[ToolMessage | Command]],
    ) -> ToolMessage | Command:
        """Return owned receipts after settling all dispatched children."""
        if request.tool not in self.tools:
            return await handler(request)
        configurable = request.runtime.config.get("configurable", {})
        scope = configurable.get("checkpoint_ns", "")
        owner = configurable.get(_ACCOUNTING_KEY)
        accounting = (
            owner or f"{scope}|js_cost:{_digest(request.runtime.tool_call_id or '')}"
        )
        active: set[asyncio.Task] = set()
        tools = [
            _cost_task(tool, request.runtime, accounting, active)
            if isinstance(tool, StructuredTool) and tool.name == "task"
            else tool
            for tool in request.runtime.tools
        ]
        runtime = dataclasses.replace(request.runtime, tools=tools)
        try:
            result = await handler(request.override(runtime=runtime))
        finally:
            for invocation in list(active):
                if not invocation.cancelling():
                    invocation.cancel()
            await asyncio.gather(*active, return_exceptions=True)
        if owner:
            return result
        receipt = await _receipt_total(runtime.config, accounting)
        if receipt is None:
            return result
        total, breakdown = receipt
        transfers = {
            accounting: {
                "owner_scope": _parent_checkpoint_scope(scope),
                "cost_usd": total,
                "breakdown": breakdown,
            }
        }
        if isinstance(result, Command):
            update = dict(result.update) if isinstance(result.update, Mapping) else {}
            update["_session_cost_transfers"] = transfers
            return dataclasses.replace(result, update=update)
        return Command(
            update={"messages": [result], "_session_cost_transfers": transfers}
        )


def _cost_task(
    tool: StructuredTool,
    outer_runtime: ToolRuntime,
    owner: str,
    active: set[asyncio.Task],
) -> StructuredTool:
    """Return a task proxy with request-isolated child graph checkpoints."""
    occurrences: dict[str, int] = {}

    async def invoke(
        description: str, subagent_type: str, runtime: ToolRuntime
    ) -> object:
        configurable = dict(runtime.config.get("configurable", {}))
        response_format = configurable.get(_RESPONSE_FORMAT_KEY)
        fingerprint = _digest(
            json.dumps(
                [description, subagent_type, getattr(response_format, "schema", None)],
                sort_keys=True,
            )
        )
        occurrence = occurrences.get(fingerprint, 0)
        occurrences[fingerprint] = occurrence + 1
        scope = outer_runtime.config.get("configurable", {}).get("checkpoint_ns", "")
        configurable["checkpoint_ns"] = (
            f"{scope}|js_dispatch:{fingerprint}_{occurrence}"
        )
        configurable[_ACCOUNTING_KEY] = owner
        # The SDK's task closure owns the actual child ainvoke, including
        # dynamic response schemas. Public durability="sync" belongs there;
        # until that boundary exposes it, inherit LangGraph 1.2's config key.
        configurable["__pregel_durability"] = "sync"
        configurable["__deepagents_js_cost_loop"] = asyncio.get_running_loop()
        scratchpad = configurable.get("__pregel_scratchpad")
        if scratchpad is not None:
            configurable["__pregel_scratchpad"] = dataclasses.replace(
                scratchpad, subgraph_counter=itertools.count().__next__
            )
        config: RunnableConfig = {**runtime.config, "configurable": configurable}
        invocation = asyncio.current_task()
        if invocation is not None:
            active.add(invocation)
        try:
            return await tool.arun(
                {
                    "description": description,
                    "subagent_type": subagent_type,
                    "runtime": dataclasses.replace(runtime, config=config),
                },
                config=config,
                tool_call_id=runtime.tool_call_id,
            )
        except asyncio.CancelledError, GraphBubbleUp, NodeCancelledError:
            raise
        except Exception as exc:
            logger.debug("Subagent %r failed", subagent_type, exc_info=exc)
            return {
                "error": (
                    f"Subagent {subagent_type!r} failed: "
                    f"{type(exc).__name__}: {str(exc)[:300]}. You may retry this task."
                ),
                "failed": True,
            }
        finally:
            if invocation is not None:
                active.discard(invocation)

    return tool.model_copy(update={"coroutine": invoke})


def record_cost_receipt(
    amount: float, *, breakdown: CostBreakdown | None = None
) -> None:
    """Persist one local node delta before its graph update returns.

    Args:
        amount: Dollars priced here, excluding claimed descendant transfers.
        breakdown: Local requests, including free and unpriceable usage.
            Omitted detail is preserved as incomplete legacy accounting.
    """
    configurable = get_config().get("configurable", {})
    owner = configurable.get(_ACCOUNTING_KEY)
    saver = configurable.get("__pregel_checkpointer")
    if not owner or not isinstance(saver, BaseCheckpointSaver):
        return
    if amount <= 0 and (breakdown is None or breakdown["request_count"] == 0):
        return
    namespace = configurable.get("checkpoint_ns", "")
    config: RunnableConfig = {
        "configurable": {
            "thread_id": configurable["thread_id"],
            "checkpoint_ns": f"{owner}|receipt:{_digest(namespace)}",
        }
    }
    if OWNER_KEY in configurable:
        config["configurable"][OWNER_KEY] = configurable[OWNER_KEY]
    loop = configurable["__deepagents_js_cost_loop"]
    asyncio.run_coroutine_threadsafe(
        _put_receipt(saver, config, owner, amount, breakdown), loop
    ).result()


async def _put_receipt(
    saver: BaseCheckpointSaver,
    config: RunnableConfig,
    owner: str,
    amount: float,
    breakdown: CostBreakdown | None,
) -> None:
    """Persist a node's first usage delta without replacing it on replay."""
    if await saver.aget_tuple(config) is not None:
        return
    checkpoint = empty_checkpoint()
    checkpoint["channel_values"] = {"cost_usd": amount}
    if breakdown is not None:
        checkpoint["channel_values"]["breakdown"] = breakdown
    checkpoint["channel_versions"] = dict.fromkeys(
        checkpoint["channel_values"], checkpoint["id"]
    )
    metadata: _ReceiptMetadata = {"js_cost_owner": owner}
    await saver.aput(config, checkpoint, metadata, checkpoint["channel_versions"])


async def _receipt_total(
    config: RunnableConfig, owner: str
) -> tuple[float, CostBreakdown] | None:
    """Return the sum of the latest local receipts owned by this eval."""
    configurable = config.get("configurable", {})
    saver = configurable.get("__pregel_checkpointer")
    if not isinstance(saver, BaseCheckpointSaver):
        return None
    seen: set[str] = set()
    total = 0.0
    breakdown = _empty_cost_breakdown()
    async for receipt in saver.alist(
        {"configurable": {"thread_id": configurable["thread_id"]}},
        filter={"js_cost_owner": owner},
    ):
        namespace = receipt.config["configurable"]["checkpoint_ns"]
        if namespace in seen:
            continue
        seen.add(namespace)
        values = receipt.checkpoint["channel_values"]
        amount = values.get("cost_usd")
        if (
            isinstance(amount, int | float)
            and not isinstance(amount, bool)
            and math.isfinite(amount)
            and amount >= 0
        ):
            total += amount
            detail = values.get("breakdown")
            if not isinstance(detail, Mapping):
                # Keep legacy dollars without inventing requests or attribution.
                detail = _empty_cost_breakdown(historical_complete=False)
                detail["total_cost_usd"] = amount
            breakdown = _merge_cost_breakdowns(breakdown, detail)
        else:
            breakdown["historical_complete"] = False
    return (total, breakdown) if seen else None

libs/code/deepagents_code/_tool_free.py:
"""Remove executable tool configuration from isolated model requests."""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from langchain_core.language_models import BaseChatModel

_TOOL_OPTIONS = frozenset(
    {
        "tools",
        "tool_choice",
        "functions",
        "function_call",
        "parallel_tool_calls",
        "mcp_servers",
    }
)
_OPTION_CONTAINERS = ("model_kwargs", "extra_body")


def _tool_free_options[K](options: Mapping[K, object]) -> dict[K, object]:
    """Copy request defaults, including nested provider payload overrides.

    Returns:
        Options with tool configuration removed.
    """
    return {
        key: (
            _tool_free_options(value)
            if key in _OPTION_CONTAINERS and isinstance(value, Mapping)
            else deepcopy(value)
        )
        for key, value in options.items()
        if key not in _TOOL_OPTIONS
    }


def tool_free_model(model: BaseChatModel) -> BaseChatModel:
    """Isolate request defaults while sharing the provider's HTTP clients.

    Args:
        model: Unbound chat model whose defaults should be isolated.

    Returns:
        A model copy with tool-free provider defaults.
    """
    updates: dict[str, object] = {
        key: _tool_free_options(value)
        for key in _OPTION_CONTAINERS
        if isinstance(value := getattr(model, key, None), Mapping)
    }
    if hasattr(model, "mcp_servers"):
        updates["mcp_servers"] = None
    return model.model_copy(update=updates)


def tool_free_settings(
    model: object, settings: Mapping[str, object]
) -> dict[str, object]:
    """Flatten bound defaults with request overrides taking precedence.

    Args:
        model: Chat model, optionally wrapped in request bindings.
        settings: Request overrides to apply after bound defaults.

    Returns:
        Isolated generation settings without tool configuration.
    """
    from langchain_core.runnables import RunnableBinding

    merged = dict(settings)
    while isinstance(model, RunnableBinding):
        merged = {**model.kwargs, **merged}
        model = model.bound
    return _tool_free_options(merged)

libs/code/deepagents_code/btw_api.py:
"""Side-question generation and durable usage without conversation writes."""

from __future__ import annotations

import asyncio
import json
import logging
import sqlite3
from contextlib import closing
from functools import cache
from typing import TYPE_CHECKING, cast, override

from starlette.requests import ClientDisconnect
from starlette.responses import JSONResponse, Response

from deepagents_code.btw import BTW_OPERATION_ATTR, BtwOperation
from deepagents_code.btw_cost import answer_with_cost, load_cost
from deepagents_code.workspace import (
    WorkspaceConflictError,
    _database_path,
    require_thread_workspace,
)

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable, Coroutine

    from langgraph.checkpoint.serde.jsonplus import JsonPlusSerializer
    from starlette.requests import Request
    from starlette.types import Receive, Scope, Send

    from deepagents_code.cost_tracking import CostBreakdown, CostState

logger = logging.getLogger(__name__)
_MAX_QUESTION_LENGTH = 16_000
_MAX_HISTORY_LENGTH = 128_000


def _parse_history(raw: object) -> list[tuple[str, str]]:
    """Validate completed text exchanges without accepting message roles.

    Returns:
        Question/answer pairs for the side conversation.

    Raises:
        TypeError: If history is not a list.
        ValueError: If an exchange is malformed or history exceeds the limit.
    """
    history: list[tuple[str, str]] = []
    if not isinstance(raw, list):
        msg = "History must be a list of question/answer pairs."
        raise TypeError(msg)
    for pair in raw:
        match pair:
            case [str(question), str(answer)] if question.strip() and answer.strip():
                history.append((question, answer))
            case _:
                msg = "History must contain nonempty question/answer text pairs."
                raise ValueError(msg)
    if (
        sum(len(question) + len(answer) for question, answer in history)
        > _MAX_HISTORY_LENGTH
    ):
        msg = "Side conversation is too long. Press Ctrl+X in /btw to clear it."
        raise ValueError(msg)
    return history


async def _wait_for_disconnect(request: Request) -> None:
    """Listen after the request body has been fully consumed."""
    while (await request.receive())["type"] != "http.disconnect":
        pass


async def _answer_while_connected[T](
    request: Request, answer: Coroutine[object, object, T]
) -> T | None:
    """Keep generation scoped to this HTTP connection.

    Returns:
        The answer, or `None` if the client disconnected.
    """
    generation = asyncio.create_task(answer)
    disconnect = asyncio.create_task(_wait_for_disconnect(request))
    try:
        done, _ = await asyncio.wait(
            (generation, disconnect), return_when=asyncio.FIRST_COMPLETED
        )
        if disconnect in done:
            disconnect.result()
            return None
        return generation.result()
    finally:
        generation.cancel()
        disconnect.cancel()
        await asyncio.gather(generation, disconnect, return_exceptions=True)


class _BtwStreamingResponse(Response):
    """Send fragments directly, keeping generation scoped to the connection."""

    def __init__(
        self,
        request: Request,
        answer: Callable[
            [Callable[[str], Awaitable[None]]],
            Coroutine[object, object, tuple[str, CostBreakdown | None]],
        ],
    ) -> None:
        super().__init__(
            media_type="text/event-stream", headers={"Cache-Control": "no-store"}
        )
        del self.headers["content-length"]
        self._request = request
        self._answer = answer

    @override
    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        await send(
            {"type": "http.response.start", "status": 200, "headers": self.raw_headers}
        )
        await _answer_while_connected(self._request, self._send_answer(send))
        await send({"type": "http.response.body", "body": b"", "more_body": False})

    async def _send_answer(self, send: Send) -> bool:
        async def emit(event: str, data: object) -> None:
            body = f"event: {event}\ndata: {json.dumps(data)}\n\n".encode()
            try:
                await send(
                    {"type": "http.response.body", "body": body, "more_body": True}
                )
            except OSError as exc:
                raise ClientDisconnect from exc

        async def on_text(text: str) -> None:
            await emit("text", text)

        try:
            async with asyncio.timeout(120):
                text, cost = await self._answer(on_text)
        except TimeoutError:
            await emit("error", {"detail": "Side question timed out. Try again."})
        except ClientDisconnect:
            raise  # A closed transport cannot receive an error event.
        except Exception, SystemExit:
            logger.exception("Side question failed")
            await emit(
                "error",
                {"detail": "Side question failed on the server; see the server log."},
            )
        else:
            await emit("complete", {"text": text, "cost": cost})
        return True


async def btw(request: Request) -> Response:
    """Answer without starting or updating a graph run.

    Returns:
        Answer text or a safe error response.
    """
    from langchain_core.messages import convert_to_messages

    from deepagents_code.offload_api import _thread_client, get_server_runtime

    try:
        payload = await request.json()
        if (
            not isinstance(payload, dict)
            or not {"question", "workspace"} <= payload.keys()
            or payload.keys() - {"question", "workspace", "history"}
        ):
            return JSONResponse(
                {"detail": "Expected question and workspace."}, status_code=422
            )
        question = payload["question"]
        if (
            not isinstance(question, str)
            or not 0 < len(question.strip()) <= _MAX_QUESTION_LENGTH
        ):
            return JSONResponse(
                {"detail": "Question must contain 1 to 16000 characters."},
                status_code=422,
            )
        history = _parse_history(payload.get("history", []))
        thread_id = request.path_params["thread_id"]
        binding = await require_thread_workspace(thread_id, payload["workspace"])
    except (TypeError, ValueError) as exc:
        return JSONResponse({"detail": str(exc)}, status_code=422)
    except WorkspaceConflictError as exc:
        return JSONResponse({"detail": str(exc)}, status_code=409)
    try:
        async with asyncio.timeout(120):
            server = await get_server_runtime(binding)
            operation = getattr(server.backend, BTW_OPERATION_ATTR, None)
            if not isinstance(operation, BtwOperation):
                return JSONResponse(
                    {"detail": "This server does not support /btw."}, status_code=503
                )
            client = _thread_client()
            snapshot = await client.threads.get_state(thread_id)
            # Accounting must recognize prior AI messages, including legacy
            # responses without saved costs. Keep the checkpoint untouched.
            state = dict(snapshot.get("values") or {})
            state["messages"] = convert_to_messages(state.get("messages", []))
            if "text/event-stream" in request.headers.get("accept", ""):
                return _BtwStreamingResponse(
                    request,
                    lambda on_text: answer_with_cost(
                        operation.answer(
                            thread_id,
                            state,
                            question.strip(),
                            history=history,
                            on_text=on_text,
                        ),
                        thread_id=thread_id,
                        state=cast("CostState", state),
                    ),
                )
            result = await _answer_while_connected(
                request,
                answer_with_cost(
                    operation.answer(
                        thread_id, state, question.strip(), history=history
                    ),
                    thread_id=thread_id,
                    state=cast("CostState", state),
                ),
            )
        if result is None:
            return JSONResponse({"detail": "Client disconnected."}, status_code=499)
        text, cost = result
        response: dict[str, str | CostBreakdown] = {"text": text}
        if cost is not None:
            response["cost"] = cost
        return JSONResponse(response)
    except TimeoutError:
        return JSONResponse(
            {"detail": "Side question timed out. Try again."}, status_code=504
        )
    except Exception, SystemExit:
        logger.exception("Side question failed")
        return JSONResponse(
            {"detail": "Side question failed on the server; see the server log."},
            status_code=500,
        )


async def btw_cost(request: Request) -> JSONResponse:
    """Read persisted side-question usage independently of main-task state.

    Returns:
        The cumulative side-question breakdown, or `None` before any usage.
    """
    cost = await asyncio.to_thread(load_cost, request.path_params["thread_id"])
    return JSONResponse({"cost": cost})


_USAGE_CHANNELS = (
    "_session_cost_usd",
    "_session_cost_breakdown",
    "_last_model_request_at",
    "_last_cache_write",
    "_last_cache_use",
    "_last_cache_model_spec",
    "_last_cache_params",
    "_last_cache_endpoint",
    "_model_spec",
)
"""Checkpoint channels the client reads to settle cost and prompt-cache state."""


def _read_usage_channels(thread_id: str) -> dict[str, object]:
    """Read usage channels from the latest root checkpoint row.

    The row stores these channels inline. Delta channels such as `messages`
    are not replayed, so the cost does not grow with the thread.

    Returns:
        The usage channels present in the checkpoint; empty without one.
    """
    path = _database_path()
    if not path.exists():
        return {}
    with closing(
        sqlite3.connect(f"{path.as_uri()}?mode=ro", uri=True, timeout=0.05)
    ) as conn:
        if not conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'checkpoints'"
        ).fetchone():
            return {}
        row = conn.execute(
            "SELECT type, checkpoint FROM checkpoints "
            "WHERE thread_id = ? AND checkpoint_ns = '' "
            "ORDER BY checkpoint_id DESC LIMIT 1",
            (thread_id,),
        ).fetchone()
    if row is None or not row[0] or not row[1]:
        return {}
    values = _serializer().loads_typed((row[0], row[1])).get("channel_values", {})
    return {key: values[key] for key in _USAGE_CHANNELS if key in values}


@cache
def _serializer() -> JsonPlusSerializer:
    from langgraph.checkpoint.serde.jsonplus import JsonPlusSerializer

    return JsonPlusSerializer()


def _load_usage(thread_id: str) -> dict[str, object]:
    return {"cost": load_cost(thread_id), "checkpoint": _read_usage_channels(thread_id)}


async def thread_usage(request: Request) -> JSONResponse:
    """Read cost and prompt-cache state without the message history.

    The client settles its display after every turn. Full thread state
    rebuilds and sends every message, which is megabytes on a long thread.
    This route sends only the channels the client reads, plus side spend.

    Returns:
        Side-question spend under `cost` and checkpoint usage channels under
            `checkpoint`.
    """
    usage = await asyncio.to_thread(_load_usage, request.path_params["thread_id"])
    return JSONResponse(usage)

