"""Resolve authorized Python extension sources into entry files."""

from __future__ import annotations

import importlib.metadata
import importlib.util
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING

from deepagents_code._env_vars import EXPERIMENTAL, is_env_truthy
from deepagents_code.extensions.registry import SourceInfo, SourceScope

if TYPE_CHECKING:
    from collections.abc import Iterable, Sequence

    from deepagents_code.plugins.models import PluginInstance

ENTRY_POINT_GROUP = "dcode.extensions"


@dataclass(frozen=True, slots=True)
class DiscoveryResult:
    """Authorized sources and non-fatal resolution errors."""

    sources: tuple[SourceInfo, ...] = ()
    errors: tuple[str, ...] = ()


def user_extensions_dir() -> Path:
    """Return the user-wide loose-file extension directory."""
    from deepagents_code.model_config import DEFAULT_CONFIG_PATH

    return DEFAULT_CONFIG_PATH.parent / "extensions"


def project_extensions_dir(project_root: Path) -> Path:
    """Return the extension directory beneath `project_root`."""
    return project_root / ".deepagents" / "extensions"


def _canonical(path: Path) -> Path:
    return path.expanduser().resolve()


def _source(path: Path, scope: SourceScope, *, package: bool = False) -> SourceInfo:
    return SourceInfo(_canonical(path), is_package=package, scope=scope)


def _scan(directory: Path, scope: SourceScope) -> tuple[list[SourceInfo], list[str]]:
    try:
        entries = sorted(directory.expanduser().iterdir())
    except FileNotFoundError:
        return [], []
    except OSError as exc:
        return [], [f"Could not scan extension directory {directory}: {exc}"]

    sources: list[SourceInfo] = []
    errors: list[str] = []
    for entry in entries:
        try:
            source = _entry_source(entry, scope)
        except (OSError, RuntimeError) as exc:
            errors.append(f"Could not inspect extension entry {entry}: {exc}")
            continue
        if source is not None:
            sources.append(source)
    return sources, errors


def _entry_source(entry: Path, scope: SourceScope) -> SourceInfo | None:
    if entry.is_file() and entry.suffix == ".py":
        return _source(entry, scope)
    for filename in ("__init__.py", "extension.py"):
        candidate = entry / filename
        if candidate.is_file():
            return _source(candidate, scope, package=True)
    return None


def _resolve_explicit(path: Path, scope: SourceScope) -> DiscoveryResult:
    expanded = path.expanduser()
    try:
        if expanded.is_dir():
            sources, errors = _scan(expanded, scope)
            return DiscoveryResult(tuple(sources), tuple(errors))
        if expanded.is_file() and expanded.suffix == ".py":
            return DiscoveryResult((_source(expanded, scope),))
    except OSError, RuntimeError:
        return DiscoveryResult(errors=("Could not inspect an extension path",))
    msg = f"Extension path must be an existing Python file or directory: {path}"
    return DiscoveryResult(errors=(msg,))


def _resolve_paths(paths: Iterable[Path], scope: SourceScope) -> DiscoveryResult:
    sources: list[SourceInfo] = []
    errors: list[str] = []
    for path in paths:
        result = _resolve_explicit(path, scope)
        sources.extend(result.sources)
        errors.extend(result.errors)
    return DiscoveryResult(tuple(sources), tuple(errors))


def _plugin_sources(plugins: Sequence[PluginInstance]) -> list[SourceInfo]:
    return [
        SourceInfo(
            _canonical(path),
            is_package=path.name == "__init__.py",
            source_id=plugin.plugin_id,
            version=plugin.version,
            installed_root=_canonical(plugin.root),
        )
        for plugin in plugins
        if plugin.manifest is not None
        for path in plugin.manifest.python_extensions
    ]


def _entry_point_source(entry: importlib.metadata.EntryPoint) -> SourceInfo:
    module = entry.value.partition(":")[0]
    spec = importlib.util.find_spec(module)
    if spec is None or spec.origin is None:
        msg = f"Entry point {entry.name!r} does not resolve to a Python module"
        raise ValueError(msg)
    version = entry.dist.version if entry.dist is not None else None
    return SourceInfo(
        _canonical(Path(spec.origin)),
        is_package=spec.submodule_search_locations is not None,
        source_id=f"{entry.name}@entry-point",
        version=version,
        installed_root=_canonical(Path(spec.origin).parent),
    )


def _entry_point_sources() -> DiscoveryResult:
    sources: list[SourceInfo] = []
    errors: list[str] = []
    try:
        entries = sorted(
            importlib.metadata.entry_points(group=ENTRY_POINT_GROUP),
            key=lambda entry: (entry.name, entry.value),
        )
    except (ImportError, OSError, ValueError) as exc:
        msg = f"Could not enumerate extension entry points: {exc}"
        return DiscoveryResult(errors=(msg,))
    for entry in entries:
        try:
            sources.append(_entry_point_source(entry))
        except (ImportError, OSError, ValueError) as exc:
            errors.append(
                f"Could not resolve extension entry point {entry.name}: {exc}"
            )
    return DiscoveryResult(tuple(sources), tuple(errors))


def _deduplicate(sources: Iterable[SourceInfo]) -> tuple[SourceInfo, ...]:
    unique: dict[Path, SourceInfo] = {}
    for source in sources:
        unique.setdefault(source.path, source)
    return tuple(unique.values())


def discover_extensions(
    *,
    plugins: Sequence[PluginInstance] = (),
    config_paths: Sequence[Path] = (),
    cli_paths: Sequence[Path] = (),
    project_dir: Path | None = None,
) -> DiscoveryResult:
    """Resolve all authorized sources in deterministic load order.

    Returns:
        Canonically deduplicated sources and isolated errors.
    """
    if not is_env_truthy(EXPERIMENTAL):
        return DiscoveryResult()
    user_sources, user_errors = _scan(user_extensions_dir(), SourceScope.USER)
    config = _resolve_paths(config_paths, SourceScope.USER)
    cli = _resolve_paths(cli_paths, SourceScope.TEMPORARY)
    entries = _entry_point_sources()
    project = (
        _resolve_explicit(project_dir, SourceScope.PROJECT)
        if project_dir is not None
        else DiscoveryResult()
    )
    sources = _deduplicate(
        (
            *user_sources,
            *config.sources,
            *cli.sources,
            *_plugin_sources(plugins),
            *entries.sources,
            *project.sources,
        )
    )
    errors = (
        *user_errors,
        *config.errors,
        *cli.errors,
        *entries.errors,
        *project.errors,
    )
    return DiscoveryResult(sources, errors)

libs/code/deepagents_code/git_evidence.p:
"""Bounded, read-only Git evidence collected in the tool execution environment."""

from __future__ import annotations

import asyncio
import hashlib
import inspect
import json
import os
import shlex
import subprocess  # noqa: S404  # Bounded read-only Git subprocesses.
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING
from urllib.parse import urlparse

from deepagents_code._git import (
    RepositoryMetadata,
    find_git_root,
    parse_repository_metadata,
    resolve_git_branch,
    resolve_git_commit_sha,
    resolve_git_remote_url,
)

if TYPE_CHECKING:
    from collections.abc import Mapping, Sequence

    from deepagents.backends.protocol import BackendProtocol

_LIMIT = 256_000
_MAX_REPOSITORIES = 16
_MAX_PATHS = 4096
_MAX_DIRECTORIES = 64
_ROW_FIELDS = 5


@dataclass(frozen=True)
class GitSnapshot:
    """Repository identity and opaque non-content evidence of checkout work."""

    root: str
    repository: RepositoryMetadata | None
    branch: str
    commit: str
    fingerprint: str


def _git(path: str, *args: str) -> bytes:
    env = {
        key: value for key, value in os.environ.items() if not key.startswith("GIT_")
    }
    env.update(GIT_OPTIONAL_LOCKS="0", GIT_TERMINAL_PROMPT="0")
    command = [
        "git",
        "-c",
        "core.fsmonitor=false",
        "-c",
        "core.untrackedCache=false",
        "-C",
        path,
        *args,
    ]
    with tempfile.TemporaryFile() as output:
        result = subprocess.run(  # noqa: S603  # Literal Git arguments; never a shell.
            command,
            stdout=output,
            stderr=subprocess.DEVNULL,
            env=env,
            timeout=2,
            check=False,
        )
        output.seek(0)
        data = output.read(_LIMIT + 1)
    if result.returncode or len(data) > _LIMIT:
        msg = "Git evidence is unavailable or exceeds the inspection limit."
        raise ValueError(msg)
    return data


def _fingerprint(root: str) -> str:
    status = _git(root, "status", "--porcelain=v2", "-z", "--untracked-files=all")
    paths = _git(root, "ls-files", "-m", "-o", "--exclude-standard", "-z").split(b"\0")
    digest = hashlib.sha256(status)
    if len(paths) > _MAX_PATHS:
        msg = "Git evidence exceeds the dirty-file limit."
        raise ValueError(msg)
    for raw in paths:
        if raw:
            path = Path(root) / os.fsdecode(raw)
            try:
                stat = path.lstat()
                digest.update(
                    repr(
                        (
                            raw,
                            stat.st_mode,
                            stat.st_size,
                            stat.st_mtime_ns,
                            stat.st_ctime_ns,
                        )
                    ).encode()
                )
            except FileNotFoundError:
                digest.update(raw + b"\0missing")
    return digest.hexdigest()


def _discover(paths: list[str]) -> list[str]:
    candidates = list(paths)
    pending = [(Path(paths[0]), 0)] if paths else []
    visited = 0
    while pending and visited < _MAX_DIRECTORIES:
        directory, depth = pending.pop(0)
        visited += 1
        try:
            with os.scandir(directory) as entries:
                for index, entry in enumerate(entries):
                    if index >= _MAX_DIRECTORIES:
                        break
                    if entry.name.startswith(".") or entry.name in {
                        "node_modules",
                        "vendor",
                        "__pycache__",
                    }:
                        continue
                    if entry.is_dir(follow_symlinks=False):
                        candidates.append(entry.path)
                        if depth < 1:
                            pending.append((Path(entry.path), depth + 1))
        except OSError:
            continue
    roots: list[str] = []
    for candidate in candidates:
        path = Path(candidate)
        while not path.is_dir() and path != path.parent:
            path = path.parent
        for parent in (path, *path.parents):
            if (parent / ".git").exists():
                root = str(parent.resolve())
                if root not in roots:
                    roots.append(root)
                break
        if len(roots) >= _MAX_REPOSITORIES:
            break
    return roots


def _remote_rows(paths: list[str]) -> list[list[str]]:
    rows = []
    for root in _discover(paths):
        try:
            branch = _git(root, "symbolic-ref", "--short", "HEAD").decode().strip()
        except ValueError:
            branch = "HEAD"
        try:
            commit = _git(root, "rev-parse", "--verify", "HEAD").decode().strip()
        except ValueError:
            commit = ""
        try:
            remote = _git(root, "config", "--get", "remote.origin.url").decode().strip()
        except ValueError:
            remote = ""
        if "://" in remote:
            parsed = urlparse(remote)
            remote = f"https://{parsed.hostname or ''}{parsed.path}"
        else:
            remote = remote.rsplit("@", 1)[-1]
        rows.append([root, remote, branch, commit, _fingerprint(root)])
    return rows


def _candidate_paths(cwd: str, args: Mapping[str, object] | None) -> list[str]:
    args = args or {}
    values = [cwd]
    values.extend(
        value
        for key in ("cwd", "file_path", "path")
        if isinstance(value := args.get(key), str)
    )
    command = args.get("command")
    if isinstance(command, str):
        try:
            tokens = shlex.split(command)
        except ValueError:
            tokens = []
        for index, token in enumerate(tokens):
            if token.startswith("/") or (index and tokens[index - 1] in {"cd", "-C"}):
                values.append(token)
    paths = []
    for value in values[:32]:
        if (
            not value
            or len(value) > _MAX_PATHS
            or any(char in value for char in ("\0", "\n", "\r", "$", "`", "~"))
        ):
            continue
        if value.split("/")[1:2] in (["memories"], ["conversation_history"]):
            continue
        path = os.path.normpath(
            value if value.startswith("/") else str(Path(cwd) / value)
        )
        if path not in paths:
            paths.append(path)
    return paths


def _sandbox_command(paths: list[str]) -> str:
    source = (
        "import hashlib,json,os,subprocess,tempfile\nfrom pathlib import Path\n"
        "from urllib.parse import urlparse\n"
    )
    source += f"_LIMIT={_LIMIT}\n_MAX_REPOSITORIES={_MAX_REPOSITORIES}\n"
    source += f"_MAX_PATHS={_MAX_PATHS}\n_MAX_DIRECTORIES={_MAX_DIRECTORIES}\n"
    source += "\n".join(
        inspect.getsource(function)
        for function in (_git, _fingerprint, _discover, _remote_rows)
    )
    source += f"\nprint(json.dumps(_remote_rows({paths!r})))\n"
    return "python3 -c " + shlex.quote(source)


def _snapshots(
    output: str, *, exit_code: int | None, truncated: bool
) -> list[GitSnapshot]:
    if exit_code != 0 or truncated or len(output) > _LIMIT:
        msg = "Git evidence inspection failed or was truncated."
        raise ValueError(msg)
    rows = json.loads(output)
    if not isinstance(rows, list) or len(rows) > _MAX_REPOSITORIES:
        msg = "Malformed Git evidence."
        raise ValueError(msg)
    result = []
    for row in rows:
        if (
            not isinstance(row, list)
            or len(row) != _ROW_FIELDS
            or not all(isinstance(value, str) for value in row)
        ):
            msg = "Malformed Git evidence row."
            raise ValueError(msg)
        result.append(
            GitSnapshot(
                row[0], parse_repository_metadata(row[1]), row[2], row[3], row[4]
            )
        )
    return result


def _local_probe(
    backend: BackendProtocol, cwd: str, args: Mapping[str, object] | None
) -> list[GitSnapshot]:
    from deepagents.backends.filesystem import FilesystemBackend

    if not isinstance(backend, FilesystemBackend):
        msg = "Backend does not support local Git inspection."
        raise NotImplementedError(msg)
    paths = _candidate_paths(cwd, args)
    paths = [str(backend._resolve_path(path)) for path in paths]
    result = []
    for root in _discover(paths):
        if backend.virtual_mode and not Path(root).is_relative_to(backend.cwd):
            continue
        if find_git_root(root) is None:
            continue
        result.append(
            GitSnapshot(
                root,
                parse_repository_metadata(resolve_git_remote_url(root)),
                resolve_git_branch(root),
                resolve_git_commit_sha(root),
                _fingerprint(root),
            )
        )
    return result


def probe_git(
    backend: BackendProtocol, cwd: str, tool_args: Mapping[str, object] | None = None
) -> list[GitSnapshot]:
    """Inspect candidate checkouts on the backend; optional failures may propagate.

    Returns:
        Snapshots in discovery order, without file contents or remote credentials.
    """
    from deepagents.backends.protocol import (
        SandboxBackendProtocol,
        execute_accepts_timeout,
    )

    if not isinstance(backend, SandboxBackendProtocol):
        return _local_probe(backend, cwd, tool_args)
    command = _sandbox_command(_candidate_paths(cwd, tool_args))
    if not execute_accepts_timeout(type(backend)):
        msg = "Git evidence requires bounded backend execution."
        raise NotImplementedError(msg)
    result = backend.execute(command, timeout=10)
    return _snapshots(
        result.output, exit_code=result.exit_code, truncated=result.truncated
    )


async def aprobe_git(
    backend: BackendProtocol, cwd: str, tool_args: Mapping[str, object] | None = None
) -> list[GitSnapshot]:
    """Inspect backend checkouts without blocking the event loop.

    Returns:
        Snapshots in discovery order from the actual execution environment.
    """
    from deepagents.backends.protocol import (
        SandboxBackendProtocol,
        execute_accepts_timeout,
    )

    if not isinstance(backend, SandboxBackendProtocol):
        return await asyncio.to_thread(_local_probe, backend, cwd, tool_args)
    command = _sandbox_command(_candidate_paths(cwd, tool_args))
    if not execute_accepts_timeout(type(backend)):
        msg = "Git evidence requires bounded backend execution."
        raise NotImplementedError(msg)
    result = await backend.aexecute(command, timeout=10)
    return _snapshots(
        result.output, exit_code=result.exit_code, truncated=result.truncated
    )


def changed_snapshots(
    before: Sequence[GitSnapshot], after: Sequence[GitSnapshot]
) -> list[GitSnapshot]:
    """Compare successful observations, including newly created checkouts.

    Returns:
        Changed snapshots in discovery order, excluding unchanged preexisting dirt.
    """
    previous = {snapshot.root: snapshot for snapshot in before}
    return [
        snapshot
        for snapshot in after
        if (old := previous.get(snapshot.root)) is None
        or (old.branch, old.commit, old.fingerprint)
        != (snapshot.branch, snapshot.commit, snapshot.fingerprint)
    ]

libs/code/deepagents_code/git_trace.py:
"""Reconcile observed checkout work onto the current turn's traces."""

from __future__ import annotations

import asyncio
import logging
import operator
import threading
from collections import OrderedDict
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, override

from langchain.agents.middleware.types import (
    AgentMiddleware,
    AgentState,
    ContextT,
    TracePolicy,
    omit_payload,
)
from langgraph.config import get_config

from deepagents_code.git_evidence import (
    GitSnapshot,
    aprobe_git,
    changed_snapshots,
    probe_git,
)
from deepagents_code.turn_trace import TurnTrace, capture_turn

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable, Mapping

    from deepagents.backends.protocol import BackendProtocol
    from langchain.tools.tool_node import ToolCallRequest
    from langchain_core.messages import ToolMessage
    from langchain_core.runnables import RunnableConfig
    from langgraph.runtime import Runtime
    from langgraph.types import Command


logger = logging.getLogger(__name__)
_MAX_THREADS = 64


def _observes_checkout(request: ToolCallRequest) -> bool:
    name = request.tool_call["name"]
    if name in {"read_file", "ls", "glob", "grep"}:
        return False
    metadata = (request.tool.metadata or {}) if request.tool is not None else {}
    if (
        metadata.get("readOnlyHint") is True
        and metadata.get("destructiveHint") is not True
    ):
        return False
    if metadata.get("destructiveHint") is True or name in {
        "execute",
        "write_file",
        "edit_file",
        "apply_patch",
        "js",
        "task",
    }:
        return True
    return any(
        isinstance(request.tool_call["args"].get(key), str)
        for key in ("file_path", "path", "cwd", "command")
    )


@dataclass
class _Turn:
    trace: TurnTrace
    targets: dict[tuple[str, str], tuple[int, GitSnapshot]] = field(
        default_factory=dict
    )
    sequence: int = 0
    lock: threading.RLock = field(default_factory=threading.RLock)

    def record(
        self, before: list[GitSnapshot], after: list[GitSnapshot], order: int
    ) -> None:
        with self.lock:
            for snapshot in changed_snapshots(before, after):
                if snapshot.repository is not None:
                    key = (snapshot.repository.name, snapshot.branch)
                    self.targets.setdefault(key, (order, snapshot))

    def metadata(self) -> dict[str, object]:
        with self.lock:
            targets = [
                item[1]
                for item in sorted(self.targets.values(), key=operator.itemgetter(0))
            ]
        if not targets:
            return {}
        selected = targets[0]
        repository = selected.repository
        if repository is None:
            return {}
        metadata: dict[str, object] = {
            "ls_git_repo": repository.name,
            "ls_repo_provider": repository.provider,
            "open_swe_git_targets": [
                {"repo": target.repository.name, "branch": target.branch}
                for target in targets
                if target.repository is not None
            ],
        }
        if selected.branch and selected.branch != "HEAD":
            metadata["ls_git_branch"] = selected.branch
        return metadata


class GitTraceMiddleware(AgentMiddleware[AgentState, ContextT]):
    """Observe backend work and backfill only the initiating user turn."""

    trace_policy = TracePolicy(process_inputs=omit_payload)

    def __init__(self, backend: Callable[[], BackendProtocol], cwd: str) -> None:
        """Bind observations to the execution backend and its working directory."""
        self._backend = backend
        self._cwd = cwd
        self._turns: OrderedDict[str, tuple[str, _Turn]] = OrderedDict()
        self._lock = threading.RLock()

    def _turn(self, config: RunnableConfig) -> _Turn | None:
        try:
            trace = capture_turn(config)
            metadata = config.get("metadata", {})
            thread, turn = metadata.get("thread_id"), metadata.get("turn_id")
            if (
                trace is None
                or not isinstance(thread, str)
                or not isinstance(turn, str)
            ):
                return None
            with self._lock:
                previous = self._turns.get(thread)
                if previous is None or previous[0] != turn:
                    self._turns[thread] = (turn, _Turn(trace))
                self._turns.move_to_end(thread)
                while len(self._turns) > _MAX_THREADS:
                    self._turns.popitem(last=False)
                return self._turns[thread][1]
        except Exception:
            logger.debug("Could not capture git attribution turn", exc_info=True)
            return None

    def _probe(
        self, args: Mapping[str, object] | None = None
    ) -> list[GitSnapshot] | None:
        try:
            backend = self._backend()
            cwd = self._cwd or str(getattr(backend, "cwd", ""))
            return probe_git(backend, cwd, args) if cwd else None
        except Exception:
            logger.debug("Could not inspect git attribution evidence", exc_info=True)
            return None

    async def _aprobe(
        self, args: Mapping[str, object] | None = None
    ) -> list[GitSnapshot] | None:
        try:
            backend = self._backend()
            cwd = self._cwd or str(getattr(backend, "cwd", ""))
            if not cwd:
                return None
            return await asyncio.wait_for(aprobe_git(backend, cwd, args), timeout=10)
        except Exception:
            logger.debug("Could not inspect git attribution evidence", exc_info=True)
            return None

    @staticmethod
    def _update(turn: _Turn) -> None:
        try:
            turn.trace.update(
                turn.metadata(),
                remove=("ls_git_repo", "ls_git_branch", "ls_repo_provider"),
            )
        except Exception:
            logger.debug("Could not reconcile git attribution traces", exc_info=True)

    @staticmethod
    def _order(turn: _Turn) -> int:
        with turn.lock:
            turn.sequence += 1
            return turn.sequence

    @staticmethod
    def _record(
        turn: _Turn,
        before: list[GitSnapshot] | None,
        after: list[GitSnapshot] | None,
        order: int,
    ) -> None:
        if before is None or after is None:
            return
        try:
            turn.record(before, after, order)
        except Exception:
            logger.debug("Could not retain git attribution evidence", exc_info=True)

    @override
    def before_agent(self, state: AgentState, runtime: Runtime[ContextT]) -> None:
        """Register this invocation alongside any approval-resume siblings."""
        self._turn(get_config())

    @override
    async def abefore_agent(
        self, state: AgentState, runtime: Runtime[ContextT]
    ) -> None:
        """Register this invocation without changing graph state."""
        self.before_agent(state, runtime)

    @override
    def after_agent(self, state: AgentState, runtime: Runtime[ContextT]) -> None:
        """Merge final work attribution into this turn's earlier calls."""
        if turn := self._turn(get_config()):
            self._update(turn)

    @override
    async def aafter_agent(self, state: AgentState, runtime: Runtime[ContextT]) -> None:
        """Keep optional trace transport off the server event loop."""
        if turn := self._turn(get_config()):
            await asyncio.to_thread(self._update, turn)

    @override
    def wrap_tool_call(
        self,
        request: ToolCallRequest,
        handler: Callable[[ToolCallRequest], ToolMessage | Command[object]],
    ) -> ToolMessage | Command[object]:
        """Compare actual backend checkouts around tool execution.

        Returns:
            The unchanged tool result.
        """
        if not _observes_checkout(request):
            return handler(request)
        turn = self._turn(request.runtime.config)
        if turn is None:
            return handler(request)
        order = self._order(turn)
        args = request.tool_call["args"]
        before = self._probe(args)
        result = handler(request)
        self._record(turn, before, self._probe(args), order)
        return result

    @override
    async def awrap_tool_call(
        self,
        request: ToolCallRequest,
        handler: Callable[[ToolCallRequest], Awaitable[ToolMessage | Command[object]]],
    ) -> ToolMessage | Command[object]:
        """Observe asynchronous tools without changing their outputs.

        Returns:
            The unchanged tool result.
        """
        if not _observes_checkout(request):
            return await handler(request)
        turn = self._turn(request.runtime.config)
        if turn is None:
            return await handler(request)
        order = self._order(turn)
        args = request.tool_call["args"]
        before = await self._aprobe(args)
        result = await handler(request)
        self._record(turn, before, await self._aprobe(args), order)
        return result

"""Validated Hooks v2 configuration loading, merging, and hashing.

Precedence (highest first, earlier in reduction order):

1. Project: `{project_root}/.deepagents/hooks.json`
2. User: `~/.deepagents/hooks.json` (or `config_dir/hooks.json` in tests)
3. Plugin: `hooks.json` documents contributed by enabled plugins

Sources are concatenated per event. Precedence is reduction order, not execution
order: every matching handler runs, and the first one that stops processing
decides the event.

A minimal v2 config with one event and one command handler:

```json
{"hooks": {"Notification": [{"matcher": "agent_completed",
  "hooks": [{"type": "command", "command": "bash notify.sh"}]}]}}
```

Hook stdin payloads are the Claude-compatible envelope (`hook_event_name` +
`session_id` + event-specific fields), defined in
`deepagents_code.hooks.models.wire`.

Legacy list-shaped documents are migrated only for events whose lifecycle
semantics genuinely match Hooks v2.
"""

from __future__ import annotations

import hashlib
import json
import logging
import os
from abc import ABC, abstractmethod
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from types import MappingProxyType
from typing import TYPE_CHECKING, Final, override

from pydantic import ValidationError

from deepagents_code.hooks.migration import (
    is_legacy_hooks_document,
    migrate_legacy_hooks,
)
from deepagents_code.hooks.models.config import (
    CommandHandlerSpec,
    HooksConfig,
    MatcherGroup,
)
from deepagents_code.hooks.models.domain import HookDiagnostic, HookEvent
from deepagents_code.model_config import DEFAULT_CONFIG_DIR

if TYPE_CHECKING:
    from deepagents_code.json_types import JsonValue

logger = logging.getLogger(__name__)
_LEGACY_HOOKS_REMOVAL_DATE = "September 1, 2026"


@dataclass(frozen=True, slots=True)
class HooksSource(ABC):
    """Origin of the matcher groups contributed by one hooks document."""

    location: str

    @abstractmethod
    def resolve_variables(self, value: str, *, shell_syntax: bool = False) -> str:
        """Resolve the variable references this source defines.

        Args:
            value: One `argv` element, or a shell-form `command`.
            shell_syntax: Whether a shell interprets `value`, in which case a
                reference is rewritten for the shell instead of substituted.

        Returns:
            The resolved argument or command.
        """


@dataclass(frozen=True, slots=True)
class FileHooksSource(HooksSource):
    """A project or user hooks file, which defines no variables."""

    @override
    def resolve_variables(self, value: str, *, shell_syntax: bool = False) -> str:
        """Return `value` as authored.

        Returns:
            The unchanged argument or command.
        """
        return value


@dataclass(frozen=True, slots=True)
class PluginHooksSource(HooksSource):
    """Origin and environment for groups one enabled plugin contributed."""

    plugin_id: str
    env: Mapping[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        """Freeze the environment overlay so the snapshot cannot be mutated."""
        object.__setattr__(self, "env", MappingProxyType(dict(self.env)))

    @override
    def resolve_variables(self, value: str, *, shell_syntax: bool = False) -> str:
        """Substitute direct arguments, or adapt shell references for Windows.

        Returns:
            The resolved argument or command.
        """
        if shell_syntax and os.name != "nt":
            return value
        for key, replacement in self.env.items():
            value = value.replace(
                f"${{{key}}}", f"%{key}%" if shell_syntax else replacement
            )
        return value


SourcedGroup = tuple[HooksSource, MatcherGroup]


UNSOURCED: Final = FileHooksSource(location="")
"""Provenance for groups handled without it, adding no origin or env overlay."""


@dataclass(frozen=True, slots=True)
class LoadedHooksConfig:
    """Validated configuration plus load diagnostics and source paths."""

    config: HooksConfig
    diagnostics: tuple[HookDiagnostic, ...]
    sources: tuple[Path, ...]
    snapshot_id: str
    groups: Mapping[HookEvent, tuple[SourcedGroup, ...]]
    """Merged matcher groups with provenance, in the same order as `config`."""

    project_source_loaded: bool = False
    """Whether the project-scoped source was selected and successfully loaded.

    Set only when workspace trust allowed the project source and that file
    contributed configuration. Never inferred from path membership after
    canonical deduplication (symlinks / shared config dirs can alias paths).
    """

    project_source_fingerprint: str | None = None
    """SHA-256 fingerprint of the exact project source bytes that were loaded."""


def project_hooks_path(project_root: Path) -> Path:
    """Return the project-scoped hooks configuration path.

    Args:
        project_root: Project root directory.

    Returns:
        `{project_root}/.deepagents/hooks.json`.
    """
    return project_root / ".deepagents" / "hooks.json"


def user_hooks_path(config_dir: Path | None = None) -> Path:
    """Return the user-scoped hooks configuration path.

    Args:
        config_dir: Alternate user config directory (tests).

    Returns:
        `{config_dir}/hooks.json`, defaulting to `~/.deepagents/hooks.json`.
    """
    return (config_dir or DEFAULT_CONFIG_DIR) / "hooks.json"


def load_hooks_config(
    *,
    project_root: Path,
    workspace_trusted: bool,
    config_dir: Path | None = None,
    paths: Sequence[Path] | None = None,
    documents: Sequence[tuple[HooksSource, JsonValue]] = (),
    document_diagnostics: Sequence[HookDiagnostic] = (),
) -> LoadedHooksConfig:
    """Load, validate, merge, and hash Hooks v2 configuration.

    Args:
        project_root: Project root used for project precedence.
        workspace_trusted: Whether project-scoped hooks may be loaded.
        config_dir: Alternate user config directory.
        paths: Explicit trusted source paths in precedence order (highest first).
            When omitted, project hooks are included only for trusted workspaces,
            followed by user hooks.
        documents: Already-decoded plugin documents with their provenance, merged
            after every file source so they hold the least authority. Validated
            here, so a malformed one is reported rather than dropped.
        document_diagnostics: Diagnostics the caller collected while producing
            `documents`, carried into the load result.

    Returns:
        Frozen load result with canonical `snapshot_id` and explicit project
        source provenance.
    """
    diagnostics: list[HookDiagnostic] = list(document_diagnostics)
    merged: dict[HookEvent, list[SourcedGroup]] = {}
    loaded_paths: list[Path] = []
    project_source_loaded = False
    project_source_fingerprint: str | None = None

    def _merge(document: HooksConfig, source: HooksSource) -> None:
        for event, groups in document.hooks.items():
            merged.setdefault(event, []).extend((source, group) for group in groups)

    def _ingest(path: Path, *, as_project: bool) -> None:
        nonlocal project_source_fingerprint, project_source_loaded
        resolved = path.expanduser().resolve(strict=False)
        document, file_diagnostics, fingerprint = _read_hooks_document(resolved)
        diagnostics.extend(file_diagnostics)
        if document is None:
            return
        if as_project:
            project_source_loaded = True
            project_source_fingerprint = fingerprint
        loaded_paths.append(resolved)
        _merge(document, FileHooksSource(location=str(resolved)))

    if paths is not None:
        for path in dict.fromkeys(
            path.expanduser().resolve(strict=False) for path in paths
        ):
            _ingest(path, as_project=False)
    elif workspace_trusted:
        project_path = (
            project_hooks_path(project_root).expanduser().resolve(strict=False)
        )
        user_path = user_hooks_path(config_dir).expanduser().resolve(strict=False)
        _ingest(project_path, as_project=True)
        if user_path != project_path:
            _ingest(user_path, as_project=False)
    else:
        _ingest(user_hooks_path(config_dir), as_project=False)

    for source, raw_document in documents:
        document, validation_diagnostics = _validate_hooks_document(
            raw_document, Path(source.location)
        )
        diagnostics.extend(validation_diagnostics)
        if document is not None:
            _merge(document, source)

    groups = MappingProxyType(
        {event: tuple(sourced) for event, sourced in merged.items()}
    )
    config = HooksConfig(
        hooks={
            event: [group for _source, group in sourced_groups]
            for event, sourced_groups in groups.items()
        }
    )
    return LoadedHooksConfig(
        config=config,
        diagnostics=tuple(diagnostics),
        sources=tuple(loaded_paths),
        snapshot_id=compute_snapshot_id(config, groups=groups),
        groups=groups,
        project_source_loaded=project_source_loaded,
        project_source_fingerprint=project_source_fingerprint,
    )


def compute_snapshot_id(
    config: HooksConfig,
    *,
    groups: Mapping[HookEvent, Sequence[SourcedGroup]] | None = None,
) -> str:
    """Return the canonical SHA-256 snapshot id for `config`.

    Args:
        config: Validated Hooks v2 configuration.
        groups: Matching sourced groups, so provenance participates in the hash.

    Returns:
        Lowercase hex digest of the canonical JSON serialization.
    """
    return hashlib.sha256(canonical_hooks_bytes(config, groups=groups)).hexdigest()


def canonical_hooks_bytes(
    config: HooksConfig,
    *,
    groups: Mapping[HookEvent, Sequence[SourcedGroup]] | None = None,
) -> bytes:
    """Serialize configuration into a stable byte representation.

    Args:
        config: Validated Hooks v2 configuration.
        groups: Matching sourced groups. When supplied, each group additionally
            records its non-file origin and environment overlay, so enabling a
            plugin that contributes hooks changes the snapshot id. Groups from
            the project and user files serialize identically either way.

    Returns:
        UTF-8 JSON with sorted keys, event order fixed to `HookEvent`, and
        `None` fields omitted. Unsupported fields such as `async` are
        excluded so equivalent configs hash identically.
    """
    known = groups or {}
    payload = {
        "hooks": {
            event.value: [
                _canonical_group(group, source=source)
                for source, group in known.get(event)
                or [(UNSOURCED, group) for group in config.hooks[event]]
            ]
            for event in HookEvent
            if event in config.hooks
        }
    }
    return json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def _canonical_group(group: MatcherGroup, *, source: HooksSource) -> dict[str, object]:
    raw = group.model_dump(
        mode="json", by_alias=True, exclude_none=True, exclude_defaults=True
    )
    handlers: list[dict[str, object]] = []
    hooks_raw = raw.get("hooks")
    if isinstance(hooks_raw, list):
        for item in hooks_raw:
            if not isinstance(item, dict):
                continue
            handler = {str(key): value for key, value in item.items() if key != "async"}
            handlers.append(handler)
    result: dict[str, object] = {"hooks": handlers}
    matcher = raw.get("matcher")
    if matcher is not None:
        result["matcher"] = matcher
    if isinstance(source, PluginHooksSource):
        result["origin"] = source.plugin_id
        if source.env:
            result["env"] = dict(sorted(source.env.items()))
    return result


def read_hooks_json(
    path: Path,
) -> tuple[bool, JsonValue, tuple[HookDiagnostic, ...], str | None]:
    """Decode one hooks document and fingerprint the exact bytes read.

    Args:
        path: Document path.

    Returns:
        Whether decoding succeeded, the decoded document, diagnostics, and the
        exact-byte SHA-256 fingerprint. An absent file is not a diagnostic.
    """
    if not path.is_file():
        return False, None, (), None
    try:
        content = path.read_bytes()
        decoded: JsonValue = json.loads(content.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        message = f"Failed to read hooks config at {path}: {exc}"
        logger.warning(message)
        return (
            False,
            None,
            (
                HookDiagnostic(
                    code="config_read_failed",
                    severity="warning",
                    message=message,
                    field=str(path),
                ),
            ),
            None,
        )
    return True, decoded, (), hashlib.sha256(content).hexdigest()


def _read_hooks_document(
    path: Path,
) -> tuple[HooksConfig | None, tuple[HookDiagnostic, ...], str | None]:
    decoded, data, read_diagnostics, fingerprint = read_hooks_json(path)
    if not decoded:
        return None, read_diagnostics, None

    if is_legacy_hooks_document(data):
        hooks = data.get("hooks", []) if isinstance(data, dict) else []
        if not isinstance(hooks, list):
            diagnostics = (
                HookDiagnostic(
                    code="invalid_config",
                    severity="warning",
                    message=f"Legacy hooks list missing at {path}",
                    field=str(path),
                ),
            )
            return None, diagnostics, fingerprint
        legacy_entries: list[dict[str, object]] = [
            {str(key): value for key, value in item.items()}
            for item in hooks
            if isinstance(item, Mapping)
        ]
        migrated = migrate_legacy_hooks(legacy_entries)
        migration_message = (
            f"Migrated semantically equivalent legacy hooks from {path}; "
            "unsupported legacy events remain unmapped"
            if migrated.hooks
            else (
                f"Legacy hooks at {path} contained no events that are safe to "
                "migrate to Hooks v2"
            )
        )
        diagnostics = (
            HookDiagnostic(
                code="legacy_deprecated",
                severity="warning",
                message=(
                    f"Legacy hooks configuration at {path} is deprecated and will "
                    f"stop being supported on {_LEGACY_HOOKS_REMOVAL_DATE}"
                ),
                field=str(path),
            ),
            HookDiagnostic(
                code="legacy_migrated" if migrated.hooks else "legacy_unmapped",
                severity="warning",
                message=migration_message,
                field=str(path),
            ),
        )
        return migrated, diagnostics, fingerprint

    document, diagnostics = _validate_hooks_document(data, path)
    return document, diagnostics, fingerprint


def _validate_hooks_document(
    data: object,
    path: Path,
) -> tuple[HooksConfig | None, tuple[HookDiagnostic, ...]]:
    if not isinstance(data, Mapping):
        return None, (_invalid_config(path, "", "expected an object"),)
    raw_hooks = data.get("hooks")
    if not isinstance(raw_hooks, Mapping):
        return None, (_invalid_config(path, "hooks", "expected an object"),)

    hooks: dict[HookEvent, list[MatcherGroup]] = {}
    diagnostics: list[HookDiagnostic] = []
    for raw_event, raw_groups in raw_hooks.items():
        event_field = f"hooks.{raw_event}"
        if not isinstance(raw_event, str):
            diagnostics.append(_invalid_config(path, event_field, "unknown hook event"))
            continue
        try:
            event = HookEvent(raw_event)
        except ValueError:
            diagnostics.append(_invalid_config(path, event_field, "unknown hook event"))
            continue
        if not isinstance(raw_groups, list):
            diagnostics.append(
                _invalid_config(path, event_field, "expected a list of matcher groups")
            )
            continue

        groups: list[MatcherGroup] = []
        for group_index, raw_group in enumerate(raw_groups):
            group_field = f"{event_field}[{group_index}]"
            group, group_diagnostics = _validate_matcher_group(
                raw_group,
                path,
                group_field,
            )
            diagnostics.extend(group_diagnostics)
            if group is not None:
                groups.append(group)
        if groups or not raw_groups:
            hooks[event] = groups

    if raw_hooks and not hooks:
        return None, tuple(diagnostics)
    return HooksConfig(hooks=hooks), tuple(diagnostics)


def _validate_matcher_group(
    data: object,
    path: Path,
    field: str,
) -> tuple[MatcherGroup | None, tuple[HookDiagnostic, ...]]:
    if not isinstance(data, Mapping):
        return None, (_invalid_config(path, field, "expected an object"),)
    raw_handlers = data.get("hooks")
    if not isinstance(raw_handlers, list):
        return None, (
            _invalid_config(path, f"{field}.hooks", "expected a list of handlers"),
        )

    handlers: list[CommandHandlerSpec] = []
    diagnostics: list[HookDiagnostic] = []
    for handler_index, raw_handler in enumerate(raw_handlers):
        handler_field = f"{field}.hooks[{handler_index}]"
        try:
            handlers.append(CommandHandlerSpec.model_validate(raw_handler))
        except ValidationError as exc:
            diagnostics.append(_validation_error(path, handler_field, exc))

    if raw_handlers and not handlers:
        return None, tuple(diagnostics)

    group_data = dict(data)
    group_data["hooks"] = handlers
    try:
        return MatcherGroup.model_validate(group_data), tuple(diagnostics)
    except ValidationError as exc:
        diagnostics.append(_validation_error(path, field, exc))
        return None, tuple(diagnostics)


def _validation_error(
    path: Path,
    field: str,
    error: ValidationError,
) -> HookDiagnostic:
    details = "; ".join(
        str(item["msg"])
        for item in error.errors(include_url=False, include_input=False)
    )
    return _invalid_config(path, field, details)


def _invalid_config(path: Path, field: str, detail: str) -> HookDiagnostic:
    location = f"{path}:{field}" if field else str(path)
    message = f"Invalid hooks config at {location}: {detail}"
    logger.warning(message)
    return HookDiagnostic(
        code="invalid_config",
        severity="warning",
        message=message,
        field=location,
    )

libs/code/deepagents_code/hooks/migratio:
"""Legacy dotted-event migration helpers for Hooks v2 configuration.

Legacy documents are converted by the loader so lifecycle call sites dispatch
only canonical events and do not duplicate old dotted-event hooks.

`_LEGACY_EVENT_MAP` is the authoritative list of legacy events migrated into
Hooks v2. Events absent from it (e.g. `permission.request`, `tool.use`,
`tool.result`) are dropped from the migrated configuration only; they continue
to fire through the legacy dispatcher (`deepagents_code.hooks.legacy`) until
the legacy system is removed.
"""

from __future__ import annotations

import base64
import json
import os
import shlex
import subprocess  # noqa: S404  # Legacy hooks are trusted user-configured commands.
import sys
from binascii import Error as BinasciiError
from typing import TYPE_CHECKING

from deepagents_code.hooks.env import HOOK_SUBPROCESS_TIMEOUT
from deepagents_code.hooks.models.config import (
    CommandHandlerSpec,
    HooksConfig,
    MatcherGroup,
)
from deepagents_code.hooks.models.domain import HookEvent

if TYPE_CHECKING:
    from collections.abc import Mapping, Sequence

_LEGACY_EVENT_MAP: dict[str, tuple[HookEvent, str | None]] = {
    "session.start": (HookEvent.USER_PROMPT_SUBMIT, None),
    "user.prompt": (HookEvent.USER_PROMPT_SUBMIT, None),
    "task.complete": (HookEvent.NOTIFICATION, "agent_completed"),
    "session.end": (HookEvent.SESSION_END, None),
    "context.offload": (HookEvent.PRE_COMPACT, "manual"),
    "context.compact": (HookEvent.PRE_COMPACT, "manual"),
    "input.required": (HookEvent.NOTIFICATION, "agent_needs_input"),
}
# Outer runner grace so the nested adapter timeout can fire first on Windows,
# where killing the adapter process may not reap its descendants.
_ADAPTER_OUTER_TIMEOUT_SECONDS = HOOK_SUBPROCESS_TIMEOUT + 1.0
_ADAPTER_MODULE = "deepagents_code.hooks.migration"
_ADAPTER_ARGUMENT_COUNT = 2
_THREAD_ID_EVENTS = frozenset({"session.start", "task.complete", "session.end"})


def migrate_legacy_hooks(
    legacy_hooks: Sequence[Mapping[str, object]],
) -> HooksConfig:
    """Convert legacy dotted-event hook entries into Hooks v2 configuration.

    Each distinct legacy event name becomes its own matcher group so a single
    entry subscribed to both `session.start` and `user.prompt` still runs once
    per mapped name with the matching reconstructed stdin payload.

    Args:
        legacy_hooks: Entries from the legacy `hooks.json` list form.

    Returns:
        A validated Hooks v2 configuration containing only migratable events.
    """
    grouped: dict[HookEvent, list[MatcherGroup]] = {}
    for entry in legacy_hooks:
        command = entry.get("command")
        if not isinstance(command, list) or not command:
            continue
        if not all(isinstance(part, str) for part in command):
            continue
        argv = [part for part in command if isinstance(part, str)]
        if len(argv) != len(command):
            continue
        events = entry.get("events")
        event_names: list[str]
        if events is None or events == []:
            event_names = list(_LEGACY_EVENT_MAP)
        elif isinstance(events, list):
            event_names = list(
                dict.fromkeys(name for name in events if isinstance(name, str))
            )
        else:
            continue
        for event_name in event_names:
            mapped = _LEGACY_EVENT_MAP.get(event_name)
            if mapped is None:
                continue
            event, matcher = mapped
            adapter_argv = _adapter_argv(argv, event_name)
            grouped.setdefault(event, []).append(
                MatcherGroup(
                    matcher=matcher,
                    hooks=[
                        CommandHandlerSpec(
                            type="command",
                            command=_shell_command(adapter_argv, os_name=os.name),
                            argv=adapter_argv,
                            timeout=_ADAPTER_OUTER_TIMEOUT_SECONDS,
                        )
                    ],
                )
            )
    return HooksConfig(hooks=grouped)


def _adapter_argv(argv: list[str], legacy_event: str) -> list[str]:
    encoded_argv = base64.urlsafe_b64encode(
        json.dumps(argv, separators=(",", ":")).encode()
    ).decode()
    return [sys.executable, "-m", _ADAPTER_MODULE, legacy_event, encoded_argv]


def _shell_command(argv: Sequence[str], *, os_name: str) -> str:
    if os_name == "nt":
        return subprocess.list2cmdline(argv)
    return shlex.join(argv)


def _legacy_payload(legacy_event: str, payload: Mapping[str, object]) -> bytes:
    legacy_payload: dict[str, object] = {"event": legacy_event}
    if legacy_event in _THREAD_ID_EVENTS:
        thread_id = payload.get("session_id")
        if isinstance(thread_id, str):
            legacy_payload["thread_id"] = thread_id
    return json.dumps(legacy_payload, default=str).encode()


def _decode_argv(value: str) -> list[str] | None:
    try:
        decoded: object = json.loads(base64.urlsafe_b64decode(value))
    except BinasciiError, json.JSONDecodeError, UnicodeDecodeError, ValueError:
        return None
    if (
        not isinstance(decoded, list)
        or not decoded
        or not all(isinstance(part, str) for part in decoded)
    ):
        return None
    return [part for part in decoded if isinstance(part, str)]


def _run_adapter(args: Sequence[str]) -> int:
    # Nested hook exit status is ignored (side-effect-only). Argument, decode,
    # stdin, launch, and timeout failures return nonzero for runner diagnostics.
    if len(args) != _ADAPTER_ARGUMENT_COUNT:
        return 1
    legacy_event, encoded_argv = args
    argv = _decode_argv(encoded_argv)
    if argv is None:
        return 1
    try:
        payload: object = json.loads(sys.stdin.buffer.read())
    except json.JSONDecodeError, UnicodeDecodeError:
        return 1
    if not isinstance(payload, dict):
        return 1
    wire_payload = {str(key): value for key, value in payload.items()}
    try:
        subprocess.run(  # noqa: S603  # Runs the trusted legacy hook argv directly.
            argv,
            input=_legacy_payload(legacy_event, wire_payload),
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=HOOK_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return 1
    except OSError:
        return 1
    return 0


def is_legacy_hooks_document(data: object) -> bool:
    """Return whether `data` looks like the legacy list-shaped hooks document.

    Args:
        data: Parsed JSON root.

    Returns:
        `True` when `hooks` is a list of command entries rather than an event map.
    """
    if not isinstance(data, dict):
        return False
    hooks = data.get("hooks")
    if not isinstance(hooks, list):
        return False
    return all(isinstance(item, dict) for item in hooks)


if __name__ == "__main__":
    raise SystemExit(_run_adapter(sys.argv[1:]))

