"""Native dcode tool vocabulary mapped to compatible wire names."""

from __future__ import annotations

import re
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from collections.abc import Callable

    from deepagents_code.hooks.models.domain import ToolCallData
    from deepagents_code.json_types import JsonObject


def _select(args: JsonObject, *fields: str) -> JsonObject:
    return {field: args[field] for field in fields if field in args}


def _bash_input(args: JsonObject) -> JsonObject:
    result = _select(args, "command")
    if "timeout" in args:
        timeout = args["timeout"]
        result["timeout"] = (
            timeout * 1000
            if isinstance(timeout, int) and not isinstance(timeout, bool)
            else timeout
        )
    return result


def _write_input(args: JsonObject) -> JsonObject:
    return _select(args, "file_path", "content")


def _edit_input(args: JsonObject) -> JsonObject:
    return _select(args, "file_path", "old_string", "new_string", "replace_all")


def _read_input(args: JsonObject) -> JsonObject:
    result = _select(args, "file_path", "limit")
    if "offset" in args:
        offset = args["offset"]
        result["offset"] = (
            offset + 1
            if isinstance(offset, int) and not isinstance(offset, bool)
            else offset
        )
    return result


def _glob_input(args: JsonObject) -> JsonObject:
    return _select(args, "pattern", "path")


def _grep_input(args: JsonObject) -> JsonObject:
    result = _select(args, "path", "glob", "output_mode")
    if "pattern" in args:
        pattern = args["pattern"]
        result["pattern"] = re.escape(pattern) if isinstance(pattern, str) else pattern
    if "max_count" in args:
        result["head_limit"] = args["max_count"]
    return result


def _ls_input(args: JsonObject) -> JsonObject:
    return _select(args, "path")


_NATIVE_TO_WIRE: dict[str, tuple[str, Callable[[JsonObject], JsonObject]]] = {
    "execute": ("Bash", _bash_input),
    "write_file": ("Write", _write_input),
    "edit_file": ("Edit", _edit_input),
    "read_file": ("Read", _read_input),
    "glob": ("Glob", _glob_input),
    "grep": ("Grep", _grep_input),
    "ls": ("LS", _ls_input),
}

_MCP_WIRE_RE = re.compile(r"^mcp__.+__.+$")


def format_mcp_wire_name(server: str, tool: str) -> str:
    """Format a compatible MCP wire tool name.

    Args:
        server: MCP server name.
        tool: Bare MCP tool name.

    Returns:
        `mcp__{server}__{tool}`.
    """
    return f"mcp__{server}__{tool}"


def to_wire_tool_name(
    name: str,
    *,
    mcp_server: str | None = None,
) -> str:
    """Map a native tool name to the compatible wire tool name.

    Args:
        name: Native dcode or already-compatible tool name.
        mcp_server: Owning MCP server when known from tool metadata.

    Returns:
        The Claude-compatible tool name used for matchers and wire payloads.
    """
    if _MCP_WIRE_RE.fullmatch(name) is not None:
        return name
    if mcp_server is not None:
        prefix = f"{mcp_server}_"
        tool = name.removeprefix(prefix) if name.startswith(prefix) else name
        return format_mcp_wire_name(mcp_server, tool)
    adapter = _NATIVE_TO_WIRE.get(name)
    return adapter[0] if adapter is not None else name


def to_wire_tool_input(name: str, args: JsonObject) -> JsonObject:
    """Map native tool arguments to the compatible wire input object.

    Args:
        name: Native dcode tool name (before wire renaming).
        args: Native tool-call arguments.

    Returns:
        JSON object suitable for `tool_input` on the wire.
    """
    adapter = _NATIVE_TO_WIRE.get(name)
    return adapter[1](args) if adapter is not None else dict(args)


def to_wire_call(
    call: ToolCallData,
) -> tuple[str, JsonObject]:
    """Project a native tool call into compatible wire name and input.

    Args:
        call: Native tool-call data from a lifecycle owner.

    Returns:
        `(tool_name, tool_input)` for matchers and wire projection.
    """
    name = to_wire_tool_name(call.name, mcp_server=call.mcp_server)
    if call.mcp_server is not None or _MCP_WIRE_RE.fullmatch(call.name) is not None:
        return name, dict(call.args)
    return name, to_wire_tool_input(call.name, call.args)

libs/code/deepagents_code/model_api.py:
"""Launch metadata and workspace-bound model resolution in the server process."""

from __future__ import annotations

import asyncio
import logging
from typing import TYPE_CHECKING

from starlette.responses import JSONResponse

from deepagents_code.model_config import ModelConfigError
from deepagents_code.model_metadata import ModelMetadata
from deepagents_code.workspace import WorkspaceConflictError, require_thread_workspace

if TYPE_CHECKING:
    from starlette.requests import Request

logger = logging.getLogger(__name__)


async def startup_model_metadata(_request: Request) -> JSONResponse:
    """Read launch metadata without binding or validating a conversation thread.

    Args:
        _request: The startup metadata request.

    Returns:
        Cached launch model properties or an availability error.
    """
    from deepagents_code.server_graph import get_server_runtime

    try:
        runtime = await get_server_runtime()
        if runtime.model_metadata is not None:
            return JSONResponse(runtime.model_metadata.to_payload())
    except Exception, SystemExit:
        logger.exception("Server startup model metadata is unavailable")
    return JSONResponse(
        {"detail": "Startup model metadata is unavailable. Restart the server."},
        status_code=503,
    )


async def model_metadata(request: Request) -> JSONResponse:
    """Resolve metadata without committing a model switch or running inference.

    Returns:
        Model properties or a validation/availability error.
    """
    from deepagents_code.server_graph import (
        _resolve_bound_workspace_config,
        _workspace_runtime,
    )

    try:
        body = await request.json()
        if not isinstance(body, dict) or body.keys() - {
            "workspace",
            "model_spec",
            "extra_kwargs",
            "purpose",
        }:
            return JSONResponse(
                {"detail": "Invalid model metadata request."}, status_code=422
            )
        spec = body.get("model_spec")
        params = body.get("extra_kwargs")
        purpose = body.get("purpose", "main")
        if (
            not isinstance(purpose, str)
            or purpose not in {"main", "auxiliary"}
            or (purpose == "auxiliary" and (spec is None or params is not None))
        ):
            return JSONResponse(
                {"detail": "Invalid model resolution purpose or parameters."},
                status_code=422,
            )
        if (spec is not None and (not isinstance(spec, str) or not spec)) or (
            params is not None and not isinstance(params, dict)
        ):
            return JSONResponse(
                {"detail": "Invalid model specification or parameters."},
                status_code=422,
            )
        binding = await require_thread_workspace(
            request.path_params["thread_id"], body.get("workspace")
        )
        if spec is None and params is not None:
            return JSONResponse(
                {"detail": "Model parameters require a model specification."},
                status_code=422,
            )
        runtime = await _workspace_runtime(binding)
        if spec is None:
            metadata = runtime.model_metadata
            if metadata is None:
                return JSONResponse(
                    {"detail": "Model metadata is unavailable."}, status_code=503
                )
        else:
            if runtime.model_environment is None:
                return JSONResponse(
                    {"detail": "Model resolution environment is unavailable."},
                    status_code=503,
                )
            config = await _resolve_bound_workspace_config(binding)

            def resolve() -> ModelMetadata:
                from deepagents_code.config import (
                    create_model,
                    use_environment,
                )

                with use_environment(runtime.model_environment):
                    result = create_model(
                        spec,
                        extra_kwargs=params,
                        profile_overrides=(
                            config.profile_overrides if purpose == "main" else None
                        ),
                        cli_max_retries=config.cli_max_retries,
                    )
                profile = result.model.profile
                structured_output = (
                    profile.get("structured_output") if profile else None
                )
                return ModelMetadata(
                    result.model_name,
                    result.provider,
                    result.context_limit,
                    result.unsupported_modalities,
                    structured_output=structured_output,
                )

            metadata = await asyncio.to_thread(resolve)
        return JSONResponse(metadata.to_payload())
    except WorkspaceConflictError as exc:
        return JSONResponse({"detail": str(exc)}, status_code=409)
    except (ModelConfigError, TypeError, ValueError) as exc:
        return JSONResponse({"detail": str(exc)}, status_code=422)
    except Exception, SystemExit:
        logger.exception("Server model metadata resolution failed")
        return JSONResponse(
            {
                "detail": (
                    "The server could not resolve model metadata. "
                    "Check the server log and retry."
                )
            },
            status_code=503,
        )


async def model_catalog(request: Request) -> JSONResponse:
    """Discover selectable models in a thread's bound inference environment.

    Args:
        request: Catalog request, including workspace binding and model purpose.

    Returns:
        A catalog containing only model presentation and readiness metadata.
    """
    from deepagents_code.server_graph import (
        _resolve_bound_workspace_config,
        _workspace_runtime,
    )

    try:
        body = await request.json()
        if not isinstance(body, dict) or body.keys() - {
            "workspace",
            "purpose",
            "recommended_models",
            "current_spec",
        }:
            return JSONResponse(
                {"detail": "Invalid model catalog request."}, status_code=422
            )
        purpose = body.get("purpose", "main")
        recommendations = body.get("recommended_models", [])
        current_spec = body.get("current_spec")
        if (
            not isinstance(purpose, str)
            or purpose not in {"main", "auxiliary"}
            or not isinstance(recommendations, list)
            or not all(isinstance(spec, str) for spec in recommendations)
            or (current_spec is not None and not isinstance(current_spec, str))
        ):
            return JSONResponse(
                {"detail": "Invalid model catalog parameters."}, status_code=422
            )
        binding = await require_thread_workspace(
            request.path_params["thread_id"], body.get("workspace")
        )
        runtime = await _workspace_runtime(binding)
        config = await _resolve_bound_workspace_config(binding)
        if runtime.model_environment is None:
            return JSONResponse(
                {"detail": "Model environment is unavailable."}, status_code=503
            )

        def discover() -> dict[str, object]:
            from deepagents_code.config import use_environment
            from deepagents_code.model_catalog import load_model_catalog

            with use_environment(runtime.model_environment):
                catalog = load_model_catalog(
                    profile_overrides=config.profile_overrides
                    if purpose == "main"
                    else None,
                    recommended_models=recommendations,
                    current_spec=current_spec,
                )
            return catalog.model_dump(mode="json")

        return JSONResponse(await asyncio.to_thread(discover))
    except WorkspaceConflictError as exc:
        return JSONResponse({"detail": str(exc)}, status_code=409)
    except (ModelConfigError, TypeError, ValueError) as exc:
        return JSONResponse({"detail": str(exc)}, status_code=422)
    except Exception, SystemExit:
        logger.exception("Server model catalog discovery failed")
        return JSONResponse(
            {"detail": "Model catalog is unavailable. Check the server log and retry."},
            status_code=503,
        )

"""Model discovery data shared by the inference host and model pickers."""

from __future__ import annotations

import logging
from typing import TYPE_CHECKING

from pydantic import BaseModel, ConfigDict, Field, model_validator

from deepagents_code.model_config import (
    CODEX_PROVIDER,
    PROVIDER_API_KEY_ENV,
    ModelConfig,
    ModelProfileEntry,
    ProviderAuthSource,
    ProviderAuthState,
    ProviderAuthStatus,
    _get_builtin_providers,
    get_available_models,
    get_model_profiles,
    get_provider_auth_status,
)

if TYPE_CHECKING:
    from collections.abc import Sequence
    from typing import Self

logger = logging.getLogger(__name__)

# Only presentation fields cross the process boundary. Constructor kwargs and
# arbitrary config/profile extensions can contain credentials or executable data.
_PROFILE_FIELDS = frozenset(
    {
        "name",
        "status",
        "max_input_tokens",
        "max_output_tokens",
        "text_inputs",
        "image_inputs",
        "audio_inputs",
        "pdf_inputs",
        "video_inputs",
        "reasoning_output",
        "tool_calling",
        "structured_output",
    }
)


class CatalogProfile(BaseModel):
    """Displayable model capabilities with override provenance."""

    model_config = ConfigDict(extra="forbid", strict=True)
    profile: dict[str, str | int | bool | None]
    overridden_keys: list[str]


class CatalogProvider(BaseModel):
    """Provider presentation and readiness, without credential values."""

    model_config = ConfigDict(extra="forbid", strict=True)
    state: ProviderAuthState = Field(strict=False)
    source: ProviderAuthSource | None = Field(default=None, strict=False)
    env_var: str | None = None
    detail: str | None = None
    display_name: str | None = None
    short_name: str | None = None
    install_extra: str | None = None

    @model_validator(mode="after")
    def _validate_readiness(self) -> Self:
        """Return readiness validated before the picker renders it."""
        self.auth_status("provider")
        return self

    def auth_status(self, provider: str) -> ProviderAuthStatus:
        """Return the readiness indicator for a provider.

        Args:
            provider: Provider key associated with this catalog entry.
        """
        return ProviderAuthStatus(
            state=self.state,
            provider=provider,
            source=self.source,
            env_var=self.env_var,
            detail=self.detail,
        )


class ModelCatalog(BaseModel):
    """Validated catalog from the environment that constructs models."""

    model_config = ConfigDict(extra="forbid", strict=True)
    models: list[str]
    profiles: dict[str, CatalogProfile]
    providers: dict[str, CatalogProvider]
    allowed_models: list[str] | None = None
    managed_policy: bool = False
    current_spec: str | None = None

    def profile_entries(self) -> dict[str, ModelProfileEntry]:
        """Return profile entries understood by the model detail footer."""
        return {
            spec: ModelProfileEntry(
                profile=entry.profile,
                overridden_keys=frozenset(entry.overridden_keys),
            )
            for spec, entry in self.profiles.items()
        }

    def presentation_config(self) -> ModelConfig:
        """Return display and policy metadata without loading client config."""
        from deepagents_code.model_config import MANAGED_CONFIG_SOURCE, ProviderConfig

        providers: dict[str, ProviderConfig] = {}
        for provider, info in self.providers.items():
            entry: ProviderConfig = {}
            if info.display_name:
                entry["display_name"] = info.display_name
            if info.short_name:
                entry["short_name"] = info.short_name
            providers[provider] = entry
        return ModelConfig(
            providers=providers,
            allowed_models=(
                tuple(self.allowed_models) if self.allowed_models is not None else None
            ),
            allowed_models_source=(
                MANAGED_CONFIG_SOURCE if self.managed_policy else "server config"
            )
            if self.allowed_models is not None
            else None,
        )


def _profile_entry(entry: ModelProfileEntry) -> CatalogProfile:
    """Return only scalar profile fields that the picker displays."""
    profile = {
        key: value
        for key, value in entry["profile"].items()
        if key in _PROFILE_FIELDS and (value is None or type(value) in {str, int, bool})
    }
    return CatalogProfile(
        profile=profile,
        overridden_keys=sorted(entry["overridden_keys"] & profile.keys()),
    )


def _provider_entry(provider: str, config: ModelConfig) -> CatalogProvider:
    """Return provider readiness from the active inference environment."""
    from deepagents_code.config_manifest import (
        is_provider_package_installed,
        provider_install_extra,
    )

    status = get_provider_auth_status(provider)
    extra = provider_install_extra(provider)
    return CatalogProvider(
        state=status.state,
        source=status.source,
        env_var=status.env_var,
        detail=status.detail,
        display_name=config.get_provider_display_name(provider),
        short_name=config.get_provider_short_name(provider),
        install_extra=(
            extra if extra and not is_provider_package_installed(provider) else None
        ),
    )


def load_model_catalog(
    *,
    profile_overrides: dict[str, object] | None = None,
    recommended_models: Sequence[str] = (),
    current_spec: str | None = None,
) -> ModelCatalog:
    """Discover models in the caller's active environment without constructing them.

    Args:
        profile_overrides: Main-model profile overrides; omit for auxiliary roles.
        recommended_models: Additional known models to surface when enabled.
        current_spec: Active model to retain even if discovery does not list it.

    Returns:
        Displayable capabilities, policy, and provider readiness.
    """
    from deepagents_code.model_config import MANAGED_CONFIG_SOURCE

    config = ModelConfig.load()
    if current_spec:
        current_spec = config.canonical_model_spec(current_spec) or current_spec
    available = get_available_models()
    models = [
        f"{provider}:{model}"
        for provider, names in available.items()
        for model in names
    ]
    providers = {provider: _provider_entry(provider, config) for provider in available}
    for spec in dict.fromkeys(
        [*recommended_models, *([current_spec] if current_spec else [])]
    ):
        provider, separator, _name = spec.partition(":")
        if not separator or spec in models or not config.is_model_allowed(spec):
            continue
        if not config.is_provider_enabled(provider):
            continue
        try:
            if provider not in providers:
                providers[provider] = _provider_entry(provider, config)
            info = providers[provider]
            if provider in available or info.install_extra or spec == current_spec:
                models.append(spec)
        except Exception:
            logger.warning(
                "Skipping unavailable catalog provider %s", provider, exc_info=True
            )
    # Custom entries need setup prompts even when an integration is missing or
    # exposes no profiles. Keep readiness on the inference host, independent of
    # the discovered model rows.
    known_providers = (
        _get_builtin_providers().keys()
        | PROVIDER_API_KEY_ENV.keys()
        | config.providers.keys()
        | {CODEX_PROVIDER}
    )
    for provider in sorted(known_providers - providers.keys()):
        if not config.is_provider_enabled(provider):
            continue
        try:
            providers[provider] = _provider_entry(provider, config)
        except Exception:
            logger.warning(
                "Skipping unavailable catalog provider %s", provider, exc_info=True
            )
    profiles = get_model_profiles(cli_override=profile_overrides)
    return ModelCatalog(
        models=models,
        current_spec=current_spec,
        profiles={
            spec: _profile_entry(profiles[spec]) for spec in models if spec in profiles
        },
        providers=providers,
        allowed_models=list(config.allowed_models)
        if config.allowed_models is not None
        else None,
        managed_policy=config.allowed_models_source == MANAGED_CONFIG_SOURCE,
    )

"""Internal JSON normalization helpers."""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from deepagents_code.plugins.models import JsonObject, JsonValue


def json_value(value: object) -> JsonValue | None:
    """Normalize a decoded value to the supported JSON type.

    Returns:
        The normalized value, or `None` for an unsupported value.
    """
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, list):
        normalized: list[JsonValue] = []
        for item in value:
            converted = json_value(item)
            if converted is not None or item is None:
                normalized.append(converted)
        return normalized
    if isinstance(value, dict):
        normalized_object: JsonObject = {}
        for key, item in value.items():
            if not isinstance(key, str):
                continue
            converted = json_value(item)
            if converted is not None or item is None:
                normalized_object[key] = converted
        return normalized_object
    return None


def json_object(value: object) -> JsonObject:
    """Normalize a decoded value to a JSON object.

    Returns:
        The normalized object, or an empty object for a non-object value.
    """
    converted = json_value(value)
    return converted if isinstance(converted, dict) else {}

libs/code/deepagents_code/plugins/adapte:
"""Adapter from plugin MCP declarations to dcode MCP config dictionaries."""

from __future__ import annotations

import json
import logging
import re
from hashlib import sha256
from pathlib import Path
from typing import TYPE_CHECKING

from deepagents_code.plugins._json import json_object, json_value
from deepagents_code.plugins.substitution import plugin_environment, substitute_json

if TYPE_CHECKING:
    from deepagents_code.plugins.models import JsonObject, JsonValue, PluginInstance

logger = logging.getLogger(__name__)
# For example, `tools@example.com` becomes `tools_example_com_<hash>`.
_MCP_NAME_PART_RE = re.compile(r"[^A-Za-z0-9_-]+")
_MCP_NAME_PART_LENGTH = 48


def _safe_mcp_name_part(value: str) -> str:
    sanitized = _MCP_NAME_PART_RE.sub("_", value).strip("_")
    if sanitized == value and sanitized and len(sanitized) <= _MCP_NAME_PART_LENGTH:
        return sanitized
    digest = sha256(value.encode()).hexdigest()[:8]
    prefix = sanitized[:_MCP_NAME_PART_LENGTH] or "unnamed"
    return f"{prefix}_{digest}"


def scoped_mcp_server_name(plugin_id: str, server_name: str) -> str:
    """Namespace a plugin-declared MCP server's name under its plugin id.

    Plugin identifiers may contain characters rejected by dcode's MCP loader.
    Use `__` as the namespace separator so names stay unique and valid.

    Args:
        plugin_id: Full plugin id in `name@marketplace` form.
        server_name: Unscoped server name from the plugin config.

    Returns:
        Scoped server name safe for `_SERVER_NAME_RE`.
    """
    plugin_part = _safe_mcp_name_part(plugin_id)
    server_part = _safe_mcp_name_part(server_name)
    return f"plugin__{plugin_part}__{server_part}"


def _mcp_server_needs_login(server: object) -> bool:
    """Return whether an MCP server config typically requires interactive login."""
    if not isinstance(server, dict):
        return False
    server_type = server.get("type")
    if server_type in {"http", "sse"}:
        return True
    return isinstance(server.get("url"), str)


def plugin_mcp_server_entries(
    plugin: PluginInstance,
) -> tuple[tuple[str, str, bool], ...]:
    """List plugin MCP servers as `(label, scoped_name, needs_login)` tuples.

    `label` is the unscoped name from the plugin config (for UI). `scoped_name`
    is what dcode registers after namespacing.

    Args:
        plugin: Plugin whose MCP declarations should be listed.

    Returns:
        Deduplicated server entries in declaration order.
    """
    servers: dict[str, object] = {}
    for path in plugin.inventory.mcp_files:
        if path.suffix in {".mcpb", ".dxt"}:
            continue
        servers.update(_load_mcp_server_map(path))
    if plugin.manifest and plugin.manifest.inline_mcp:
        servers.update(_server_map(plugin.manifest.inline_mcp))
    entries: list[tuple[str, str, bool]] = []
    seen: set[str] = set()
    for name, server in servers.items():
        if not isinstance(name, str) or name in seen:
            continue
        seen.add(name)
        entries.append(
            (
                name,
                scoped_mcp_server_name(plugin.plugin_id, name),
                _mcp_server_needs_login(server),
            )
        )
    return tuple(entries)


def _server_map(raw: object) -> JsonObject:
    """Extract the server-name to config map from a decoded MCP document.

    Accepts Claude's `{"mcpServers": {...}}` wrapper, Codex's
    `{"mcp_servers": {...}}` wrapper, or a bare server map.

    Returns:
        The extracted server map, or an empty map for non-object input.
    """
    if not isinstance(raw, dict):
        return {}
    wrapped = raw.get("mcpServers")
    if isinstance(wrapped, dict):
        return json_object(wrapped)
    codex_wrapped = raw.get("mcp_servers")
    if isinstance(codex_wrapped, dict):
        return json_object(codex_wrapped)
    return json_object(raw)


def _load_mcp_server_map(path: Path) -> JsonObject:
    """Load an MCP config file and extract its server-name to config map.

    Returns:
        The extracted server map, or an empty map when the file cannot be read.
    """
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        logger.warning("Skipping plugin MCP config %s: %s", path, exc)
        return {}
    return _server_map(raw)


def _plugin_mcp_server_map(plugin: PluginInstance) -> JsonObject:
    """Load a plugin's declared MCP servers without creating runtime state.

    Returns:
        The unscoped server configuration keyed by declared server name.
    """
    servers: JsonObject = {}
    for path in plugin.inventory.mcp_files:
        if path.suffix in {".mcpb", ".dxt"}:
            logger.warning(
                "Skipping unsupported MCP bundle for plugin %s: %s",
                plugin.plugin_id,
                path,
            )
            continue
        servers.update(_load_mcp_server_map(path))
    if plugin.manifest and plugin.manifest.inline_mcp:
        servers.update(_server_map(plugin.manifest.inline_mcp))
    return servers


def plugin_mcp_server_names(plugin: PluginInstance) -> tuple[str, ...]:
    """Return scoped MCP server names without preparing plugin runtime state.

    Args:
        plugin: Plugin instance whose declarations should be inspected.

    Returns:
        Scoped MCP server names in declaration order.
    """
    return tuple(
        scoped_mcp_server_name(plugin.plugin_id, name)
        for name in _plugin_mcp_server_map(plugin)
        if isinstance(name, str)
    )


def _normalize_server(
    server: object, *, plugin: PluginInstance, project_dir: Path | None
) -> JsonValue:
    normalized_server = json_value(server)
    substituted = substitute_json(
        normalized_server,
        plugin_root=plugin.root,
        plugin_data=plugin.data_dir,
        project_dir=project_dir,
    )
    if isinstance(substituted, dict):
        cwd = substituted.get("cwd")
        if isinstance(cwd, str) and cwd and not Path(cwd).is_absolute():
            substituted = {**substituted, "cwd": str((plugin.root / cwd).resolve())}
        env = substituted.get("env")
        plugin_env = plugin_environment(
            plugin_root=plugin.root,
            plugin_data=plugin.data_dir,
            project_dir=project_dir,
        )
        if isinstance(env, dict):
            substituted = {**substituted, "env": {**plugin_env, **env}}
        else:
            substituted = {**substituted, "env": plugin_env}
    return json_value(substituted)


def discover_plugin_mcp_configs(
    *, project_dir: Path | None = None
) -> tuple[JsonObject, ...]:
    """Discover enabled plugins and compose their MCP config layers.

    Args:
        project_dir: Project directory for variable substitution.

    Returns:
        Plugin MCP config layers, or an empty tuple when discovery fails.
    """
    try:
        from deepagents_code.plugins import discover_plugins

        result = discover_plugins()
    except OSError, RuntimeError:
        logger.warning("Could not discover plugin MCP configs", exc_info=True)
        return ()
    for warning in result.warnings:
        logger.warning("Plugin discovery warning while loading MCP: %s", warning)
    return tuple(plugin_mcp_configs(result.plugins, project_dir=project_dir))


def plugin_mcp_configs(
    plugins: tuple[PluginInstance, ...], *, project_dir: Path | None = None
) -> list[JsonObject]:
    """Build MCP config layers for enabled plugins.

    Default `.mcp.json` files are loaded before manifest `mcpServers`, so manifest
    entries win on server-name conflicts.

    Args:
        plugins: Enabled plugin instances.
        project_dir: Project directory for `${CLAUDE_PROJECT_DIR}` substitution.

    Returns:
        MCP config layers ready for dcode's merge path.
    """
    configs: list[JsonObject] = []
    for plugin in plugins:
        # Create the writable data dir when MCP configs need it. Discovery itself
        # only computes the path so it stays safe for blockbuster-guarded callers.
        try:
            plugin.data_dir.mkdir(parents=True, exist_ok=True)
        except OSError:
            logger.warning(
                "Could not create plugin data dir for %s: %s",
                plugin.plugin_id,
                plugin.data_dir,
                exc_info=True,
            )
        servers = _plugin_mcp_server_map(plugin)
        scoped: JsonObject = {}
        for name, server in servers.items():
            if not isinstance(name, str):
                continue
            scoped_name = scoped_mcp_server_name(plugin.plugin_id, name)
            scoped[scoped_name] = _normalize_server(
                server, plugin=plugin, project_dir=project_dir
            )
        if scoped:
            configs.append({"mcpServers": scoped})
    return configs

libs/code/deepagents_code/plugins/comman:
"""CLI helpers for plugin management."""

from __future__ import annotations

import argparse
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from collections.abc import Callable

    from deepagents_code.plugins.models import PluginUpdate, PluginUpdateResult

from deepagents_code.plugins import (
    add_marketplace_source,
    install_plugin,
    list_available_plugins,
    reinstall_plugin,
    remove_marketplace,
    set_installed_plugin_enabled,
    uninstall_plugin,
    update_plugins,
)
from deepagents_code.plugins.marketplace import (
    MarketplaceError,
    redact_marketplace_source,
    redact_urls_in_text,
)
from deepagents_code.plugins.store import (
    install_path_exists,
    load_installed_plugins,
    load_marketplace_records,
)


def setup_plugin_parser(
    subparsers: Any,  # noqa: ANN401  # argparse subparsers uses dynamic typing
    *,
    make_help_action: Callable[[Callable[[], None]], type[argparse.Action]],
    add_output_args: Callable[[argparse.ArgumentParser], None] | None = None,
) -> argparse.ArgumentParser:
    """Set up the `plugin` CLI parser.

    Args:
        subparsers: Parent argparse subparsers object.
        make_help_action: Factory for parser-specific help actions.
        add_output_args: Optional callback that adds output-format flags.

    Returns:
        Plugin command parser.
    """

    def _help() -> None:
        from deepagents_code.ui import show_plugins_help

        show_plugins_help()

    parent = argparse.ArgumentParser(add_help=False)
    parent.add_argument("-h", "--help", action=make_help_action(_help))
    parser = subparsers.add_parser(
        "plugin",
        aliases=["plugins"],
        help="Manage plugins",
        add_help=False,
        parents=[parent],
    )
    if add_output_args is not None:
        add_output_args(parser)
    plugin_sub = parser.add_subparsers(dest="plugin_command")

    list_parser = plugin_sub.add_parser("list", aliases=["ls"], help="List plugins")
    if add_output_args is not None:
        add_output_args(list_parser)

    install_parser = plugin_sub.add_parser("install", help="Install a plugin")
    install_parser.add_argument("plugin_id")
    reinstall_parser = plugin_sub.add_parser(
        "reinstall", help="Restore an installed plugin's files"
    )
    reinstall_parser.add_argument("plugin_id")
    uninstall_parser = plugin_sub.add_parser("uninstall", help="Uninstall a plugin")
    uninstall_parser.add_argument("plugin_id")

    update_parser = plugin_sub.add_parser(
        "update", help="Update installed plugins from their marketplaces"
    )
    update_parser.add_argument("plugin_ids", nargs="*", metavar="plugin_id")
    update_parser.add_argument(
        "--check", action="store_true", help="Only report available updates"
    )
    if add_output_args is not None:
        add_output_args(update_parser)

    enable_parser = plugin_sub.add_parser("enable", help="Enable a plugin")
    enable_parser.add_argument("plugin_id")
    disable_parser = plugin_sub.add_parser("disable", help="Disable a plugin")
    disable_parser.add_argument("plugin_id")

    marketplace_parser = plugin_sub.add_parser(
        "marketplace", help="Manage plugin marketplaces"
    )
    marketplace_sub = marketplace_parser.add_subparsers(dest="marketplace_command")
    marketplace_list = marketplace_sub.add_parser(
        "list", aliases=["ls"], help="List marketplaces"
    )
    if add_output_args is not None:
        add_output_args(marketplace_list)
    marketplace_add = marketplace_sub.add_parser("add", help="Add a marketplace")
    marketplace_add.add_argument("source")
    marketplace_remove = marketplace_sub.add_parser(
        "remove", help="Remove a marketplace and uninstall its plugins"
    )
    marketplace_remove.add_argument("name")
    return parser


def _needs_repair_ids() -> frozenset[str]:
    """Return installed plugin ids whose registered install path is missing."""
    return frozenset(
        plugin_id
        for plugin_id, entry in load_installed_plugins().items()
        if not install_path_exists(entry.install_path)
    )


def _plugin_list_rows() -> list[dict[str, object]]:
    needs_repair = _needs_repair_ids()
    return [
        {
            "id": plugin_id,
            "description": description,
            "enabled": enabled,
            "needs_repair": plugin_id in needs_repair,
        }
        for plugin_id, description, enabled in list_available_plugins()
    ]


def _update_row(update: PluginUpdate) -> dict[str, object]:
    return {
        "id": update.plugin_id,
        "installed_version": update.installed_version,
        "available_version": update.available_version,
    }


def _update_lines(result: PluginUpdateResult) -> list[str]:
    lines = [
        f"Updated {u.plugin_id} {u.installed_version} -> {u.available_version}."
        for u in result.updated
    ]
    lines.extend(
        f"Update available: {u.plugin_id} {u.installed_version} -> "
        f"{u.available_version}"
        for u in result.available
    )
    if result.updated:
        lines.append("Run /reload to apply.")
    elif not result.available and not result.errors:
        lines.append("All plugins are up to date.")
    lines.extend(result.errors)
    return lines


def _execute_update(args: argparse.Namespace, output_format: str) -> str | None:
    try:
        result = update_plugins(args.plugin_ids, check_only=args.check)
    except (MarketplaceError, OSError, ValueError) as exc:
        text = f"Failed to update plugins: {redact_urls_in_text(str(exc))}"
        print(text)  # noqa: T201
        raise SystemExit(1) from exc
    if output_format == "json":
        from deepagents_code.output import write_json

        write_json(
            "plugin update",
            {
                "updated": [_update_row(u) for u in result.updated],
                "available": [_update_row(u) for u in result.available],
                "errors": list(result.errors),
            },
        )
        text = None
    else:
        text = "\n".join(_update_lines(result))
        print(text)  # noqa: T201
    if result.errors:
        raise SystemExit(1)
    return text


def _list_status(row: dict[str, object]) -> str:
    if row["needs_repair"]:
        return "needs repair"
    return "enabled" if row["enabled"] else "disabled"


def _reinstall(plugin_id: str) -> str:
    """Reinstall a plugin and print the outcome.

    Returns:
        The printed result text.

    Raises:
        SystemExit: With status 1 when the reinstall fails.
    """
    try:
        instance = reinstall_plugin(plugin_id)
    except (MarketplaceError, FileNotFoundError, OSError, ValueError) as exc:
        text = f"Failed to reinstall {plugin_id}: {redact_urls_in_text(str(exc))}"
        print(text)  # noqa: T201
        raise SystemExit(1) from exc
    text = f"Reinstalled plugin {instance.plugin_id}. Run /reload to activate."
    print(text)  # noqa: T201
    return text


def execute_plugin_command(args: argparse.Namespace) -> str | None:
    """Execute a plugin management command.

    Args:
        args: Parsed argparse namespace.

    Returns:
        Text output for slash-command callers, or `None` when output was written.

    Raises:
        SystemExit: With status 1 when a mutating command fails.
    """
    output_format = getattr(args, "output_format", "text")
    command = getattr(args, "plugin_command", None)
    if command is None:
        from deepagents_code.ui import show_plugins_help

        show_plugins_help()
        return None
    if command in {"list", "ls"}:
        rows = _plugin_list_rows()
        if output_format == "json":
            from deepagents_code.output import write_json

            write_json("plugin list", rows)
            return None
        if not rows:
            text = "No plugin marketplaces configured."
        else:
            lines = []
            for row in rows:
                status = _list_status(row)
                lines.append(f"{status} {row['id']} {row['description']}".rstrip())
            text = "\n".join(lines)
        print(text)  # noqa: T201
        return text
    if command == "install":
        try:
            instance = install_plugin(args.plugin_id)
        except (MarketplaceError, FileNotFoundError, OSError, ValueError) as exc:
            text = f"Failed to install {args.plugin_id}: {exc}"
            print(text)  # noqa: T201
            raise SystemExit(1) from exc
        details = ""
        if instance.version is not None:
            details = f" (version: {instance.version})"
        text = (
            f"Installed plugin {instance.plugin_id}{details}. Run /reload to activate."
        )
        print(text)  # noqa: T201
        return text
    if command == "update":
        return _execute_update(args, output_format)
    if command == "reinstall":
        return _reinstall(args.plugin_id)
    if command == "uninstall":
        uninstall_plugin(args.plugin_id)
        text = f"Uninstalled plugin {args.plugin_id}."
        print(text)  # noqa: T201
        return text
    if command in {"enable", "disable"}:
        enabled = command == "enable"
        try:
            set_installed_plugin_enabled(args.plugin_id, enabled=enabled)
        except (MarketplaceError, OSError, ValueError) as exc:
            text = f"Failed to {command} {args.plugin_id}: {exc}"
            print(text)  # noqa: T201
            raise SystemExit(1) from exc
        text = f"{command.title()}d plugin {args.plugin_id}."
        print(text)  # noqa: T201
        return text
    if command == "marketplace":
        marketplace_command = getattr(args, "marketplace_command", None)
        if marketplace_command in {"list", "ls"}:
            records = load_marketplace_records()
            rows = [
                {
                    "name": record.name,
                    "source_type": record.source_type,
                    "source": redact_marketplace_source(record.source),
                    "install_location": (
                        record.install_location
                        if record.source_type in {"directory", "file"}
                        else "<managed cache>"
                    ),
                }
                for record in records.values()
            ]
            if output_format == "json":
                from deepagents_code.output import write_json

                write_json("plugin marketplace list", rows)
                return None
            text = (
                "No plugin marketplaces configured."
                if not rows
                else "\n".join(f"{row['name']} {row['source']}" for row in rows)
            )
            print(text)  # noqa: T201
            return text
        if marketplace_command == "add":
            try:
                marketplace = add_marketplace_source(args.source)
            except (MarketplaceError, FileNotFoundError, OSError, ValueError) as exc:
                source = redact_marketplace_source(args.source)
                text = (
                    f"Failed to add marketplace {source}: "
                    f"{redact_urls_in_text(str(exc))}"
                )
                print(text)  # noqa: T201
                raise SystemExit(1) from exc
            text = (
                f"Added marketplace {marketplace.name} "
                f"({len(marketplace.plugins)} plugin(s))."
            )
            print(text)  # noqa: T201
            return text
        if marketplace_command == "remove":
            removed = remove_marketplace(args.name)
            text = (
                f"Removed marketplace {args.name} and its installed plugins."
                if removed
                else f"Marketplace {args.name} is not configured."
            )
            print(text)  # noqa: T201
            return text
    text = (
        "Usage: plugin "
        "{list,install,reinstall,update,uninstall,enable,disable,marketplace}"
    )
    print(text)  # noqa: T201
    return text

libs/code/deepagents_code/plugins/manife:
"""Plugin manifest parsing for plugins."""

from __future__ import annotations

import json
import logging
import re
from pathlib import Path, PureWindowsPath

from deepagents_code._env_vars import EXPERIMENTAL, is_env_truthy
from deepagents_code.plugins._json import json_object
from deepagents_code.plugins.models import (
    ComponentInventory,
    JsonObject,
    PluginManifest,
    UnsupportedComponent,
)

logger = logging.getLogger(__name__)

_MANIFEST_RELATIVE_PATHS = (
    Path("plugin.json"),
    Path(".claude-plugin") / "plugin.json",
    Path(".codex-plugin") / "plugin.json",
)
_PATH_COMPONENT_FIELDS = {"skills", "mcpServers", "hooks"}
_PYTHON_EXTENSIONS_FIELD = "pythonExtensions"
_UNSUPPORTED_COMPONENT_DIRS: tuple[UnsupportedComponent, ...] = (
    "agents",
    "commands",
)
_NAME_RE = re.compile(r"^[^\s]+$")


class PluginManifestError(ValueError):
    """Raised when a plugin manifest is malformed enough to skip the plugin."""


def find_manifest_path(root: Path) -> Path | None:
    """Return the first supported manifest path under `root`, if present.

    Args:
        root: Plugin root directory.

    Returns:
        Manifest path or `None`.
    """
    for rel in _MANIFEST_RELATIVE_PATHS:
        path = root / rel
        try:
            if path.is_file():
                return path
        except OSError:
            logger.warning("Could not inspect plugin manifest path %s", path)
    return None


def _validate_name(
    name: object, *, fallback: str | None = None, allow_at: bool = True
) -> str:
    """Validate a nonempty plugin name with no whitespace.

    Names such as `code-review` and `review@team` are valid; `code review` and
    the empty string are not.

    Returns:
        The validated name or fallback.

    Raises:
        PluginManifestError: If neither value is a valid name.
    """
    if (
        isinstance(name, str)
        and name
        and _NAME_RE.fullmatch(name)
        and (allow_at or "@" not in name)
    ):
        return name
    if fallback and _NAME_RE.fullmatch(fallback) and (allow_at or "@" not in fallback):
        return fallback
    msg = f"Invalid plugin name: {name!r}"
    raise PluginManifestError(msg)


def _is_windows_absolute(path: str) -> bool:
    return bool(PureWindowsPath(path).drive or PureWindowsPath(path).root)


def resolve_relative_path(
    declaration: str,
    plugin_root: Path,
    *,
    require_dot_prefix: bool = True,
) -> tuple[Path | None, str | None]:
    """Resolve one path declared relative to `plugin_root`.

    Plugin manifest component fields must start with `./`. Marketplace source
    paths must not, because the marketplace format also accepts a bare relative
    path such as `tools/my-plugin`; those callers pass
    `require_dot_prefix=False`. Both forms stay inside `plugin_root`.

    Returns:
        `(path, None)` when the declaration resolves, or `(None, reason)`
        naming why it was rejected.
    """
    if declaration.startswith("./"):
        relative = declaration[2:]
    elif require_dot_prefix:
        return None, "path must start with './' relative to plugin root"
    else:
        relative = declaration
    if not relative:
        return None, "path must not be empty"
    path = Path(relative)
    if any(part == ".." for part in path.parts):
        return None, "path must not contain '..'"
    if path.is_absolute() or _is_windows_absolute(relative):
        return None, "path must stay within the plugin root"
    try:
        root_resolved = plugin_root.resolve()
        resolved = (plugin_root / path).resolve()
    except (OSError, RuntimeError) as exc:
        return None, f"could not resolve {declaration!r}: {exc}"
    if not resolved.is_relative_to(root_resolved):
        return None, "path escapes plugin root"
    return resolved, None


def _resolve_component_path(
    declaration: str,
    plugin_root: Path,
    field_name: str,
    warnings: list[str],
    *,
    require_dot_prefix: bool = True,
) -> Path | None:
    """Resolve one plugin-relative path, warning when it is not usable.

    Returns:
        The resolved path, or `None` when the declaration is rejected.
    """
    resolved, reason = resolve_relative_path(
        declaration, plugin_root, require_dot_prefix=require_dot_prefix
    )
    if reason is not None:
        warnings.append(f"ignoring {field_name}: {reason}")
    return resolved


def _resolve_component_paths(
    declaration: object,
    plugin_root: Path,
    field_name: str,
    warnings: list[str],
) -> tuple[Path, ...]:
    """Resolve one or more plugin-relative component paths.

    For example, `"./skills"` and `["./skills", "./extra-skills"]` are
    accepted. Absolute paths and paths containing `..` are rejected.

    Returns:
        Validated paths contained by the plugin root.
    """
    raw_paths: list[str]
    if isinstance(declaration, str):
        raw_paths = [declaration]
    elif isinstance(declaration, list):
        raw_paths = [item for item in declaration if isinstance(item, str)]
        warnings.extend(
            f"ignoring {field_name}: expected path string, got {type(item).__name__}"
            for item in declaration
            if not isinstance(item, str)
        )
    else:
        warnings.append(
            f"ignoring {field_name}: expected path string or list of strings"
        )
        return ()
    paths: list[Path] = []
    for raw_path in raw_paths:
        resolved = _resolve_component_path(raw_path, plugin_root, field_name, warnings)
        if resolved is not None:
            paths.append(resolved)
    return tuple(paths)


def _inline_mcp(value: object) -> JsonObject:
    if isinstance(value, dict):
        return json_object(value)
    if isinstance(value, list):
        merged: JsonObject = {}
        for item in value:
            if isinstance(item, dict):
                merged.update(json_object(item))
        return merged
    return {}


def _inline_hooks(value: object) -> JsonObject:
    """Normalize inline hooks to `hooks.json` document form.

    Returns:
        A wrapped hooks document, or an empty object.
    """
    if not isinstance(value, dict):
        return {}
    normalized = json_object(value)
    if not normalized:
        return {}
    wrapped = normalized.get("hooks")
    if isinstance(wrapped, dict):
        return {"hooks": wrapped}
    return {"hooks": normalized}


def _python_extensions(
    settings: object,
    plugin_root: Path,
    warnings: list[str],
) -> tuple[Path, ...]:
    if not is_env_truthy(EXPERIMENTAL):
        return ()
    if not isinstance(settings, dict):
        return ()
    declaration = settings.get(_PYTHON_EXTENSIONS_FIELD)
    if declaration is None:
        return ()
    paths = _resolve_component_paths(
        declaration,
        plugin_root,
        _PYTHON_EXTENSIONS_FIELD,
        warnings,
    )
    entries: list[Path] = []
    for path in paths:
        try:
            is_file = path.is_file()
        except OSError, RuntimeError:
            logger.debug(
                "Could not inspect Python extension path %s", path, exc_info=True
            )
            warnings.append(
                f"ignoring {_PYTHON_EXTENSIONS_FIELD}: could not inspect declared path"
            )
            continue
        if path.suffix != ".py" or not is_file:
            warnings.append(
                f"ignoring {_PYTHON_EXTENSIONS_FIELD}: "
                f"{path} must be an existing Python file"
            )
            continue
        entries.append(path)
    return tuple(entries)


def load_manifest(
    root: Path, *, fallback_name: str | None = None
) -> tuple[PluginManifest | None, Path | None, tuple[str, ...]]:
    """Load an Agent Plugins, Claude, or Codex plugin manifest.

    Args:
        root: Plugin root directory.
        fallback_name: Name to use only when deriving a manifest-less plugin.

    Returns:
        `(manifest, manifest_path, warnings)`.

    Raises:
        PluginManifestError: If the manifest exists but is invalid.
    """
    manifest_path = find_manifest_path(root)
    if manifest_path is None:
        return None, None, ()
    try:
        decoded = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        msg = f"Invalid JSON syntax in {manifest_path}: {exc}"
        raise PluginManifestError(msg) from exc
    except OSError as exc:
        msg = f"Could not read plugin manifest {manifest_path}: {exc}"
        raise PluginManifestError(msg) from exc
    if not isinstance(decoded, dict):
        msg = f"Plugin manifest {manifest_path} must be a JSON object"
        raise PluginManifestError(msg)
    raw = json_object(decoded)

    warnings: list[str] = []
    name = _validate_name(raw.get("name"), fallback=fallback_name)
    component_paths: dict[str, tuple[Path, ...]] = {}
    for field_name in _PATH_COMPONENT_FIELDS:
        declaration = raw.get(field_name)
        if declaration is None:
            continue
        if field_name in {"mcpServers", "hooks"} and isinstance(declaration, dict):
            continue
        paths = _resolve_component_paths(declaration, root, field_name, warnings)
        if paths:
            component_paths[field_name] = paths

    version_value = raw.get("version")
    version = version_value if isinstance(version_value, str) else None
    display_name_value = raw.get("displayName")
    extension_settings = raw.get("extensions")
    if isinstance(extension_settings, dict):
        extension_settings = extension_settings.get("com.langchain.deepagents.code")
    python_extensions = _python_extensions(extension_settings, root, warnings)
    if python_extensions and not version:
        warnings.append(
            f"ignoring {_PYTHON_EXTENSIONS_FIELD}: "
            "Python extensions require a non-empty plugin version"
        )
        python_extensions = ()
    manifest = PluginManifest(
        name=name,
        version=version,
        component_paths=component_paths,
        inline_mcp=_inline_mcp(raw.get("mcpServers")),
        inline_hooks=_inline_hooks(raw.get("hooks")),
        python_extensions=python_extensions,
        display_name=(
            display_name_value if isinstance(display_name_value, str) else None
        ),
        auto_update=(
            isinstance(extension_settings, dict)
            and extension_settings.get("autoUpdate") is True
        ),
    )
    return manifest, manifest_path, tuple(warnings)


def _existing_component_path(path: Path, plugin_root: Path) -> tuple[Path, ...]:
    try:
        if not path.exists():
            return ()
        resolved = path.resolve()
        if not resolved.is_relative_to(plugin_root.resolve()):
            logger.warning("Ignoring plugin component outside plugin root: %s", path)
            return ()
    except OSError:
        logger.warning("Could not inspect plugin component path %s", path)
        return ()
    else:
        return (resolved,)


def _hooks_document_paths(path: Path, plugin_root: Path) -> tuple[Path, ...]:
    """Resolve a declared hooks file or directory.

    Returns:
        Existing hook document paths inside the plugin root.
    """
    try:
        target = path / "hooks.json" if path.is_dir() else path
    except OSError:
        logger.warning("Could not inspect plugin hooks path %s", path)
        return ()
    return _existing_component_path(target, plugin_root)


def _unsupported_component_dirs(
    plugin_root: Path,
) -> tuple[UnsupportedComponent, ...]:
    """Return present component dirs that deepagents-code does not load."""
    found: list[UnsupportedComponent] = []
    for name in _UNSUPPORTED_COMPONENT_DIRS:
        path = plugin_root / name
        try:
            if path.is_dir():
                found.append(name)
        except OSError:
            logger.warning("Could not inspect plugin component path %s", path)
    return tuple(found)


def build_inventory(
    plugin_root: Path,
    manifest: PluginManifest | None,
    manifest_warnings: tuple[str, ...] = (),
) -> ComponentInventory:
    """Build component inventory for a plugin.

    Args:
        plugin_root: Plugin root directory.
        manifest: Parsed manifest or `None`.
        manifest_warnings: Warnings emitted during manifest parsing.

    Returns:
        Component inventory.
    """
    plugin_root = plugin_root.resolve()
    warnings = list(manifest_warnings)
    metadata_paths = manifest.component_paths if manifest else {}

    default_skills = _existing_component_path(plugin_root / "skills", plugin_root)
    root_skill = (
        ()
        if default_skills or (manifest and "skills" in manifest.component_paths)
        else _existing_component_path(plugin_root / "SKILL.md", plugin_root)
    )
    skills = (*default_skills, *metadata_paths.get("skills", ()), *root_skill)

    mcp_files = (
        *_existing_component_path(plugin_root / ".mcp.json", plugin_root),
        *metadata_paths.get("mcpServers", ()),
    )

    hook_files = (
        *_hooks_document_paths(plugin_root / "hooks", plugin_root),
        *(
            document
            for path in metadata_paths.get("hooks", ())
            for document in _hooks_document_paths(path, plugin_root)
        ),
    )

    unsupported = _unsupported_component_dirs(plugin_root)

    return ComponentInventory(
        skills=tuple(dict.fromkeys(skills)),
        mcp_files=tuple(dict.fromkeys(mcp_files)),
        hook_files=tuple(dict.fromkeys(hook_files)),
        unsupported=unsupported,
        warnings=tuple(warnings),
    )

libs/code/deepagents_code/plugins/market:
"""Marketplace parsing for plugins."""

from __future__ import annotations

import json
import logging
import os
import re
import shutil
import subprocess  # noqa: S404  # Git is invoked with fixed argv and no shell.
import tempfile
import urllib.error
import urllib.request
from pathlib import Path
from typing import TYPE_CHECKING
from urllib.parse import parse_qsl, unquote, urlencode, urlparse, urlunparse

from deepagents_code.plugins._json import json_object
from deepagents_code.plugins.manifest import _validate_name, resolve_relative_path
from deepagents_code.plugins.models import (
    ExternalPluginRepositorySourceType,
    GithubPluginSource,
    GitSubdirectoryPluginSource,
    JsonObject,
    JsonValue,
    LocalMarketplaceSource,
    LocalPluginSource,
    MarketplacePluginEntry,
    MarketplaceSource,
    PluginMarketplace,
    PluginSource,
    RepositoryMarketplaceSource,
    UrlMarketplaceSource,
    UrlPluginSource,
)
from deepagents_code.plugins.store import (
    ensure_marketplace_cache_dir,
    opaque_cache_key,
)

if TYPE_CHECKING:
    from collections.abc import Callable, Sequence
    from http.client import HTTPMessage
    from typing import IO

logger = logging.getLogger(__name__)

_MARKETPLACE_RELATIVE_PATHS = (
    Path(".claude-plugin") / "marketplace.json",
    Path(".agents") / "plugins" / "marketplace.json",
    Path(".agents") / "plugins" / "api_marketplace.json",
)
# SCP-style Git source, optionally with a ref: `git@github.com:owner/repo.git#main`.
_SSH_GIT_RE = re.compile(r"^([A-Za-z0-9._-]+@[^:]+:.+?(?:\.git)?)(?:#(.+))?$")
# GitHub shorthand: `owner/repo`.
_GITHUB_REPO_RE = re.compile(r"^[^/\s]+/[^/\s]+$")
_GIT_TIMEOUT_SECONDS = 120
_GITHUB_REPO_PART_COUNT = 2
_SENSITIVE_QUERY_TERMS = (
    "credential",
    "key",
    "password",
    "secret",
    "signature",
    "token",
)
_SENSITIVE_PATH_KEY_RE = re.compile(
    r"^(?:access[-_.]?token|api[-_.]?key|credential|key|password|secret|signature|token)s?$",
    re.IGNORECASE,
)
_HTTP_URL_RE = re.compile(r"https?://\S+")


class MarketplaceError(ValueError):
    """Raised when a marketplace cannot be loaded."""


def _redact_url_credentials(value: str) -> str:
    """Redact HTTP credentials while preserving a useful URL for logs.

    For example, `https://user:pass@example.com/?token=x` becomes
    `https://***@example.com/?token=%2A%2A%2A`. Non-HTTP values pass through.
    A malformed HTTP URL is reduced to its scheme so error logging cannot leak it.

    Returns:
        The redacted URL, or a scheme-only placeholder when parsing fails.
    """
    try:
        parsed = urlparse(value)
    except ValueError:
        return "https://***" if value.startswith("https://") else "http://***"
    if parsed.scheme not in {"http", "https"}:
        return value
    netloc = parsed.netloc
    if "@" in netloc:
        try:
            host = parsed.hostname or ""
            if parsed.port is not None:
                host = f"{host}:{parsed.port}"
        except ValueError:
            return f"{parsed.scheme}://***"
        netloc = f"***@{host}"
    query = urlencode(
        [
            (
                key,
                "***"
                if any(term in key.lower() for term in _SENSITIVE_QUERY_TERMS)
                else item,
            )
            for key, item in parse_qsl(parsed.query, keep_blank_values=True)
        ]
    )
    path_parts = parsed.path.split("/")
    redact_next = False
    for index, part in enumerate(path_parts):
        if redact_next and part:
            path_parts[index] = "***"
            redact_next = False
        elif part:
            redact_next = _SENSITIVE_PATH_KEY_RE.fullmatch(unquote(part)) is not None
    path = "/".join(path_parts)
    return urlunparse(parsed._replace(netloc=netloc, path=path, query=query))


def redact_marketplace_source(value: str) -> str:
    """Return a marketplace source safe for display."""
    return _redact_url_credentials(value)


def redact_urls_in_text(value: str) -> str:
    """Redact credentials from every HTTP URL embedded in text.

    Returns:
        Text with URL credentials replaced.
    """
    return _HTTP_URL_RE.sub(
        lambda match: _redact_url_credentials(match.group(0)), value
    )


def parse_marketplace_source(raw: str) -> MarketplaceSource:
    """Parse a user-provided marketplace source.

    Args:
        raw: GitHub shorthand, Git URL, marketplace JSON URL, file, or directory.

    Returns:
        Parsed marketplace source.

    Raises:
        MarketplaceError: If the source string is empty or unsupported.
    """
    value = raw.strip()
    if not value:
        msg = "Please enter a marketplace source"
        raise MarketplaceError(msg)

    ssh_match = _SSH_GIT_RE.match(value)
    if ssh_match:
        return RepositoryMarketplaceSource(
            source_type="git", value=ssh_match.group(1), ref=ssh_match.group(2)
        )

    if value.startswith("http://"):
        msg = "Remote marketplace sources must use https"
        raise MarketplaceError(msg)
    if value.startswith("https://"):
        url, _, ref = value.partition("#")
        try:
            parsed = urlparse(url)
        except ValueError as exc:
            msg = "Invalid marketplace URL"
            raise MarketplaceError(msg) from exc
        path = parsed.path
        if path.endswith(".git") or "/_git/" in path:
            return RepositoryMarketplaceSource(
                source_type="git", value=url, ref=ref or None
            )
        if parsed.hostname in {"github.com", "www.github.com"}:
            parts = [part for part in path.split("/") if part]
            if len(parts) == _GITHUB_REPO_PART_COUNT:
                repo_path = "/".join(parts)
                git_url = urlunparse(parsed._replace(path=f"/{repo_path}.git"))
                return RepositoryMarketplaceSource(
                    source_type="git", value=git_url, ref=ref or None
                )
            if len(parts) > _GITHUB_REPO_PART_COUNT:
                msg = "GitHub marketplace URLs must contain exactly owner/repo"
                raise MarketplaceError(msg)
        return UrlMarketplaceSource(source_type="url", value=url)

    if value.startswith(("./", "../", "/", "~")):
        return _marketplace_source_from_path(value)

    # Bare relative paths such as `marketplace` (no ./ prefix) are accepted when
    # they exist on disk, before GitHub-shorthand parsing.
    candidate = Path(value).expanduser()
    if candidate.exists():
        return _marketplace_source_from_path(value)

    repo, sep, ref = value.replace("#", "@", 1).partition("@")
    if (
        "/" in value
        and ":" not in value
        and not value.startswith("@")
        and _GITHUB_REPO_RE.match(repo)
    ):
        return RepositoryMarketplaceSource(
            source_type="github", value=repo, ref=ref if sep else None
        )

    msg = "Invalid marketplace source format. Try: owner/repo, https://..., or ./path"
    raise MarketplaceError(msg)


def _marketplace_source_from_path(value: str) -> MarketplaceSource:
    path = Path(value).expanduser().resolve()
    if not path.exists():
        msg = f"Path does not exist: {path}"
        raise MarketplaceError(msg)
    if path.is_file():
        if path.suffix != ".json":
            msg = f"File path must point to a .json marketplace file: {path}"
            raise MarketplaceError(msg)
        return LocalMarketplaceSource(source_type="file", value=str(path))
    if path.is_dir():
        return LocalMarketplaceSource(source_type="directory", value=str(path))
    msg = f"Path is neither a file nor a directory: {path}"
    raise MarketplaceError(msg)


def _root_for_marketplace_file(path: Path) -> Path:
    for relative in _MARKETPLACE_RELATIVE_PATHS:
        if (
            len(path.parts) >= len(relative.parts)
            and path.parts[-len(relative.parts) :] == relative.parts
        ):
            return path.parents[len(relative.parts) - 1]
    return path.parent


def _load_marketplace_file(path: Path) -> PluginMarketplace:
    root = _root_for_marketplace_file(path.expanduser().resolve())
    return _load_marketplace_from_path(root, path.expanduser().resolve())


def _run_git(args: list[str]) -> None:
    git_path = shutil.which("git")
    if git_path is None:
        msg = "Git is required to add repository-backed plugin marketplaces"
        raise MarketplaceError(msg)
    # Inherit normal Git configuration, but disable credential prompts because
    # this subprocess has no interactive input.
    env = {
        **os.environ,
        "GIT_TERMINAL_PROMPT": "0",
        "GIT_ASKPASS": "",
    }
    try:
        result = subprocess.run(  # noqa: S603  # Fixed git executable, no shell.
            [git_path, *args],
            check=False,
            capture_output=True,
            env=env,
            text=True,
            # Git writes paths as UTF-8, while the locale default is the ANSI
            # code page on Windows (e.g. cp1252).
            encoding="utf-8",
            errors="replace",
            timeout=_GIT_TIMEOUT_SECONDS,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        msg = f"Failed to run git: {redact_urls_in_text(str(exc))}"
        raise MarketplaceError(msg) from exc
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "unknown git error"
        msg = f"Git command failed: {redact_urls_in_text(detail)}"
        raise MarketplaceError(msg)


def _clone_repository_to_cache(
    source: RepositoryMarketplaceSource,
    git_url: str,
    *,
    cache_key: str,
    validate: Callable[[Path], None] | None = None,
) -> Path:
    cache_path = ensure_marketplace_cache_dir() / (
        f"repository-{opaque_cache_key(cache_key)}"
    )
    temp_path = Path(
        tempfile.mkdtemp(prefix=f".{cache_path.name}.", dir=cache_path.parent)
    )
    args = ["clone", "--depth", "1", "--recurse-submodules", "--shallow-submodules"]
    if source.ref:
        args.extend(["--branch", source.ref])
    args.extend([git_url, str(temp_path)])
    try:
        _run_git(args)
        if validate is not None:
            validate(temp_path)
        backup_path = cache_path.with_name(f".{cache_path.name}.backup")
        if backup_path.exists():
            shutil.rmtree(backup_path, ignore_errors=True)
        if cache_path.exists():
            cache_path.replace(backup_path)
        try:
            temp_path.replace(cache_path)
        except OSError:
            if backup_path.exists() and not cache_path.exists():
                backup_path.replace(cache_path)
            raise
        if backup_path.exists():
            shutil.rmtree(backup_path, ignore_errors=True)
    except Exception:
        shutil.rmtree(temp_path, ignore_errors=True)
        raise
    return cache_path


def _materialize_marketplace_repository(
    source: RepositoryMarketplaceSource, git_url: str
) -> Path:
    return _clone_repository_to_cache(
        source,
        git_url,
        cache_key=f"marketplace-{source.source_type}-{source.value}",
        validate=_validate_marketplace_repository,
    )


def _validate_marketplace_repository(root: Path) -> None:
    load_marketplace(root)


def _materialize_plugin_repository(
    source: RepositoryMarketplaceSource,
    git_url: str,
    *,
    cache_key: str,
) -> Path:
    return _clone_repository_to_cache(source, git_url, cache_key=cache_key)


class _HttpsOnlyRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(
        self,
        req: urllib.request.Request,
        fp: IO[bytes],
        code: int,
        msg: str,
        headers: HTTPMessage,
        newurl: str,
    ) -> urllib.request.Request | None:
        if urlparse(newurl).scheme != "https":
            detail = _redact_url_credentials(newurl)
            error = f"Marketplace redirect must use https: {detail}"
            raise MarketplaceError(error)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def _download_marketplace(url: str) -> Path:
    parsed = urlparse(url)
    if parsed.scheme != "https":
        msg = f"Marketplace URL must use https: {_redact_url_credentials(url)}"
        raise MarketplaceError(msg)
    cache_path = (
        ensure_marketplace_cache_dir() / f"marketplace-url-{opaque_cache_key(url)}.json"
    )
    request = urllib.request.Request(  # noqa: S310  # Scheme is restricted above.
        url, headers={"User-Agent": "dcode-plugin-manager"}
    )
    opener = urllib.request.build_opener(_HttpsOnlyRedirectHandler())
    try:
        with opener.open(request, timeout=10) as response:
            final_url = response.geturl()
            if urlparse(final_url).scheme != "https":
                detail = _redact_url_credentials(final_url)
                msg = f"Marketplace response must use https: {detail}"
                raise MarketplaceError(msg)
            data = json.load(response)
    except (OSError, urllib.error.URLError, json.JSONDecodeError) as exc:
        msg = (
            "Failed to download marketplace from "
            f"{_redact_url_credentials(url)}: {redact_urls_in_text(str(exc))}"
        )
        raise MarketplaceError(msg) from exc
    if not isinstance(data, dict):
        msg = (
            f"Marketplace URL must return a JSON object: {_redact_url_credentials(url)}"
        )
        raise MarketplaceError(msg)
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    cache_path.write_text(
        json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return cache_path


def materialize_marketplace_source(
    source: MarketplaceSource,
) -> tuple[PluginMarketplace, Path]:
    """Load a marketplace source and return its local install location.

    Args:
        source: Parsed marketplace source.

    Returns:
        Parsed marketplace and its local install location.

    Raises:
        MarketplaceError: If loading, cloning, downloading, or parsing fails.
    """
    if source.source_type == "directory":
        root = Path(source.value).expanduser().resolve()
        return load_marketplace(root), root
    if source.source_type == "file":
        path = Path(source.value).expanduser().resolve()
        return _load_marketplace_file(path), path
    if source.source_type == "url":
        path = _download_marketplace(source.value)
        marketplace = _load_marketplace_file(path)
        _reject_url_marketplace_with_local_plugins(marketplace, source.value)
        return marketplace, path
    if source.source_type == "github":
        if not isinstance(source, RepositoryMarketplaceSource):
            msg = "GitHub marketplace source is missing repository metadata"
            raise MarketplaceError(msg)
        root = _materialize_marketplace_repository(
            source, f"https://github.com/{source.value}.git"
        )
        return load_marketplace(root), root
    if source.source_type == "git":
        if not isinstance(source, RepositoryMarketplaceSource):
            msg = "Git marketplace source is missing repository metadata"
            raise MarketplaceError(msg)
        root = _materialize_marketplace_repository(source, source.value)
        return load_marketplace(root), root
    msg = f"Unsupported marketplace source type: {source.source_type}"
    raise MarketplaceError(msg)


def _reject_url_marketplace_with_local_plugins(
    marketplace: PluginMarketplace, url: str
) -> None:
    """Reject URL marketplaces whose plugins need a sibling filesystem tree.

    Direct marketplace JSON URLs only cache the catalog file. Relative plugin
    sources such as `./plugins/foo` cannot be resolved from that cache alone.

    Raises:
        MarketplaceError: If any plugin entry uses a local relative source.
    """
    local_plugins = [
        plugin.name
        for plugin in marketplace.plugins
        if _source_path(plugin.source) is not None
    ]
    if not local_plugins:
        unsupported = [
            plugin.name
            for plugin in marketplace.plugins
            if _plugin_repository_source(plugin) is None
        ]
        if not unsupported:
            return
        names = ", ".join(sorted(unsupported))
        msg = (
            f"Marketplace URL {_redact_url_credentials(url)} contains plugins "
            f"with unsupported remote sources: [{names}]"
        )
        raise MarketplaceError(msg)
    names = ", ".join(sorted(local_plugins))
    msg = (
        f"Marketplace URL {_redact_url_credentials(url)} only downloads the "
        f"catalog JSON, but plugins [{names}] use local relative sources. "
        "Use a git repository or local directory for this marketplace."
    )
    raise MarketplaceError(msg)


def load_marketplace_location(path: Path) -> PluginMarketplace:
    """Load a marketplace from either a cached directory or JSON file.

    Args:
        path: Directory or marketplace JSON path.

    Returns:
        Parsed marketplace.
    """
    resolved = path.expanduser().resolve()
    if resolved.is_file():
        return _load_marketplace_file(resolved)
    return load_marketplace(resolved)


def find_marketplace_manifest(root: Path) -> Path | None:
    """Return a marketplace manifest path under `root`, if present."""
    for rel in _MARKETPLACE_RELATIVE_PATHS:
        path = root / rel
        try:
            if path.is_file():
                return path
        except OSError:
            logger.warning("Could not inspect marketplace manifest path %s", path)
    return None


def _source_path(source: PluginSource) -> str | None:
    return source.path if isinstance(source, LocalPluginSource) else None


def _external_plugin_repository_source_type(
    value: JsonValue,
) -> ExternalPluginRepositorySourceType | None:
    if value == "github":
        return "github"
    if value == "git-subdir":
        return "git-subdir"
    if value == "url":
        return "url"
    return None


def _plugin_repository_source(
    plugin: MarketplacePluginEntry,
) -> tuple[RepositoryMarketplaceSource, str, str | None] | None:
    """Parse an external plugin source into clone metadata.

    Supported objects use `github`, `url`, or `git-subdir`;
    git-subdir identifies a plugin within a repository through its optional `path`.

    Returns:
        `(source, clone_url, subpath)` or `None` for unsupported metadata.
    """
    if not isinstance(
        plugin.source,
        (GithubPluginSource, GitSubdirectoryPluginSource, UrlPluginSource),
    ):
        return None
    kind = plugin.source.source_type
    ref_value = plugin.source.ref
    subpath_value = plugin.source.path
    if kind == "github":
        if not isinstance(plugin.source, GithubPluginSource):
            return None
        repo = plugin.source.repo
        parsed = parse_marketplace_source(f"{repo}#{ref_value}" if ref_value else repo)
        if not isinstance(parsed, RepositoryMarketplaceSource):
            return None
        return parsed, f"https://github.com/{parsed.value}.git", subpath_value
    if kind not in {"git-subdir", "url"}:
        return None
    if not isinstance(plugin.source, (GitSubdirectoryPluginSource, UrlPluginSource)):
        return None
    raw_url = plugin.source.url
    parsed = parse_marketplace_source(
        f"{raw_url}#{ref_value}" if ref_value else raw_url
    )
    if parsed.source_type == "github":
        git_url = f"https://github.com/{parsed.value}.git"
    elif parsed.source_type == "git":
        git_url = parsed.value
    else:
        return None
    if not isinstance(parsed, RepositoryMarketplaceSource):
        return None
    return parsed, git_url, subpath_value


def _resolve_source_path(
    marketplace: PluginMarketplace,
    declaration: str,
    root: Path,
    field_name: str,
    rejections: list[str] | None,
) -> Path | None:
    """Resolve a marketplace source path, recording why it was rejected.

    Returns:
        The resolved path, or `None` when the declaration is rejected.
    """
    resolved, reason = resolve_relative_path(
        declaration, root, require_dot_prefix=False
    )
    if reason is not None:
        logger.warning(
            "Marketplace %s: ignoring %s: %s", marketplace.name, field_name, reason
        )
        if rejections is not None:
            rejections.append(f"{field_name}: {reason}")
    return resolved


def materialize_plugin_source(
    marketplace: PluginMarketplace,
    plugin: MarketplacePluginEntry,
    *,
    rejections: list[str] | None = None,
) -> Path | None:
    """Resolve or materialize a marketplace plugin entry to a plugin root.

    Args:
        marketplace: Marketplace containing the plugin.
        plugin: Plugin entry.
        rejections: Collects the reason for each source path this call
            rejected. An empty list after a `None` result means the source
            itself is unsupported rather than a path being unusable; see
            `unresolved_source_message`.

    Returns:
        Resolved plugin root, or `None` for unsupported or unusable sources.
    """
    raw = _source_path(plugin.source)
    if raw is not None:
        metadata_root = marketplace.metadata.get("pluginRoot")
        base = marketplace.root
        if isinstance(metadata_root, str):
            base_path = _resolve_source_path(
                marketplace,
                metadata_root,
                marketplace.root,
                "metadata.pluginRoot",
                rejections,
            )
            if base_path is not None:
                base = base_path
        return _resolve_source_path(
            marketplace, raw, base, f"plugins.{plugin.name}.source", rejections
        )

    repository = _plugin_repository_source(plugin)
    if repository is None:
        return None
    source, git_url, subpath = repository
    root = _materialize_plugin_repository(
        source,
        git_url,
        cache_key=(f"plugin-source-{marketplace.name}-{plugin.name}-{plugin.source!r}"),
    )
    if subpath is None:
        return root
    return _resolve_source_path(
        marketplace, subpath, root, f"plugins.{plugin.name}.source.path", rejections
    )


def unresolved_source_message(
    plugin_id: str, plugin: MarketplacePluginEntry, rejections: Sequence[str]
) -> str:
    """Explain why `materialize_plugin_source` produced no plugin root.

    A rejected path and an unsupported source type both yield `None`, and
    saying "unsupported source" for the first sends readers looking for a
    missing feature instead of at their `path`.

    Returns:
        A message naming the rejected paths, or the unsupported source.
    """
    if rejections:
        return (
            f"Plugin {plugin_id} has an unusable source path ({'; '.join(rejections)})"
        )
    return (
        f"Plugin {plugin_id} has unsupported source "
        f"{redact_urls_in_text(repr(plugin.source))}; "
        "use a local path, GitHub repository, or Git repository source"
    )


def _optional_source_string(
    source: JsonObject,
    field: str,
    *,
    plugin_name: object,
    warnings: list[str],
) -> tuple[str | None, bool]:
    value = source.get(field)
    if value is None:
        return None, True
    if isinstance(value, str):
        return value, True
    warnings.append(
        f"Skipping marketplace plugin {plugin_name!r}: source.{field} must be a string"
    )
    return None, False


def _parse_plugin_source(
    value: object, *, plugin_name: object, warnings: list[str]
) -> PluginSource | None:
    if isinstance(value, str):
        return LocalPluginSource(source_type="local", path=value)
    if not isinstance(value, dict):
        warnings.append(f"Skipping marketplace plugin {plugin_name!r}: missing source")
        return None
    source = json_object(value)
    kind = source.get("source")
    path, path_valid = _optional_source_string(
        source, "path", plugin_name=plugin_name, warnings=warnings
    )
    ref, ref_valid = _optional_source_string(
        source, "ref", plugin_name=plugin_name, warnings=warnings
    )
    if not path_valid or not ref_valid:
        return None
    if kind == "local":
        if path is None:
            warnings.append(
                f"Skipping marketplace plugin {plugin_name!r}: "
                "local source requires path"
            )
            return None
        return LocalPluginSource(source_type="local", path=path)
    source_type = _external_plugin_repository_source_type(kind)
    if source_type is None:
        warnings.append(
            f"Skipping marketplace plugin {plugin_name!r}: unsupported source {kind!r}"
        )
        return None
    repo, repo_valid = _optional_source_string(
        source, "repo", plugin_name=plugin_name, warnings=warnings
    )
    url, url_valid = _optional_source_string(
        source, "url", plugin_name=plugin_name, warnings=warnings
    )
    if not repo_valid or not url_valid:
        return None
    if source_type == "github" and repo is None:
        warnings.append(
            f"Skipping marketplace plugin {plugin_name!r}: github source requires repo"
        )
        return None
    if source_type in {"git-subdir", "url"} and url is None:
        warnings.append(
            f"Skipping marketplace plugin {plugin_name!r}: "
            f"{source_type} source requires url"
        )
        return None
    if source_type == "github":
        if repo is None:
            return None
        return GithubPluginSource(
            source_type="github",
            repo=repo,
            ref=ref,
            path=path,
        )
    if url is None:
        return None
    if source_type == "git-subdir":
        return GitSubdirectoryPluginSource(
            source_type="git-subdir",
            url=url,
            ref=ref,
            path=path,
        )
    return UrlPluginSource(
        source_type="url",
        url=url,
        ref=ref,
        path=path,
    )


def _parse_entry(
    entry: object, *, warnings: list[str]
) -> MarketplacePluginEntry | None:
    if not isinstance(entry, dict):
        warnings.append(
            "Skipping marketplace plugin entry: "
            f"expected object, got {type(entry).__name__}"
        )
        return None
    source = _parse_plugin_source(
        entry.get("source"), plugin_name=entry.get("name"), warnings=warnings
    )
    if source is None:
        return None
    try:
        name = _validate_name(entry.get("name"))
    except ValueError as exc:
        warnings.append(f"Skipping marketplace plugin with invalid name: {exc}")
        return None
    description_value = entry.get("description")
    author_value = entry.get("author")
    author = (
        json_object(author_value)
        if isinstance(author_value, dict)
        else author_value
        if isinstance(author_value, str)
        else None
    )
    display_name_value = entry.get("displayName")
    return MarketplacePluginEntry(
        name=name,
        source=source,
        description=description_value if isinstance(description_value, str) else None,
        author=author,
        display_name=(
            display_name_value if isinstance(display_name_value, str) else None
        ),
    )


def _load_marketplace_from_path(root: Path, manifest_path: Path) -> PluginMarketplace:
    try:
        raw = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        msg = f"Invalid JSON syntax in {manifest_path}: {exc}"
        raise MarketplaceError(msg) from exc
    except OSError as exc:
        msg = f"Could not read marketplace manifest {manifest_path}: {exc}"
        raise MarketplaceError(msg) from exc
    if not isinstance(raw, dict):
        msg = f"Marketplace manifest {manifest_path} must be a JSON object"
        raise MarketplaceError(msg)
    try:
        name = _validate_name(raw.get("name"), allow_at=False)
    except ValueError as exc:
        raise MarketplaceError(str(exc)) from exc
    plugins_raw = raw.get("plugins")
    if not isinstance(plugins_raw, list):
        msg = f"Marketplace {name} must contain a plugins array"
        raise MarketplaceError(msg)
    warnings: list[str] = []
    plugins = tuple(
        plugin
        for entry in plugins_raw
        if (plugin := _parse_entry(entry, warnings=warnings)) is not None
    )
    for warning in warnings:
        logger.warning("%s", warning)
    metadata = json_object(raw.get("metadata"))
    return PluginMarketplace(
        name=name,
        root=root,
        manifest_path=manifest_path,
        metadata=metadata,
        plugins=plugins,
        warnings=tuple(warnings),
    )


def load_marketplace(root: Path) -> PluginMarketplace:
    """Load a marketplace manifest from a root directory.

    Args:
        root: Marketplace root directory.

    Returns:
        Parsed marketplace.

    Raises:
        MarketplaceError: If no marketplace manifest exists or it is invalid.
    """
    root = root.expanduser().resolve()
    manifest_path = find_marketplace_manifest(root)
    if manifest_path is None:
        msg = f"No marketplace manifest found under {root}"
        raise MarketplaceError(msg)
    return _load_marketplace_from_path(root, manifest_path)

"""State storage for dcode plugin marketplaces, installs, and enablement."""

from __future__ import annotations

import json
import logging
import os
import shutil
import tempfile
from contextlib import contextmanager, suppress
from hashlib import sha256
from pathlib import Path
from typing import TYPE_CHECKING, Any, Never

from deepagents_code._constants import DEFAULT_PLUGIN_DIRNAME
from deepagents_code.plugins.models import (
    InstalledPluginEntry,
    MarketplaceRecord,
    MarketplaceSourceType,
    split_plugin_id,
)

if TYPE_CHECKING:
    from collections.abc import Callable, Iterator

logger = logging.getLogger(__name__)
_STORAGE_VERSION = 1
_INSTALLED_STORAGE_VERSION = 2
_UNVERSIONED_CACHE_KEY = "unversioned"
_CACHE_SLUG_LENGTH = 48
_CACHE_DIGEST_LENGTH = 32
SUPPORTED_MARKETPLACE_SOURCE_TYPES: frozenset[MarketplaceSourceType] = frozenset(
    {"directory", "file", "github", "git", "url"}
)


class PluginStateError(OSError):
    """Raised when existing plugin state cannot be safely modified."""


def plugin_storage_root() -> Path:
    """Return the plugin storage root directory."""
    from deepagents_code._env_vars import PLUGIN_CACHE_DIR
    from deepagents_code.model_config import DEFAULT_CONFIG_DIR

    raw = os.environ.get(PLUGIN_CACHE_DIR)
    if raw:
        return Path(raw).expanduser()
    return DEFAULT_CONFIG_DIR / DEFAULT_PLUGIN_DIRNAME


@contextmanager
def plugin_mutation_lock(*, timeout: float = -1) -> Iterator[None]:
    """Serialize plugin mutations across threads and dcode processes.

    The lock is reentrant within one thread so compound operations such as
    marketplace removal can call the normal uninstall path while holding it.

    Args:
        timeout: Seconds to wait for another mutation, or `-1` indefinitely.

    Yields:
        Control while plugin state and managed caches may be mutated.
    """
    from filelock import FileLock

    root = plugin_storage_root()
    root.mkdir(parents=True, exist_ok=True)
    lock = FileLock(str(root / ".mutation.lock"), is_singleton=True)
    with lock.acquire(timeout=timeout):
        yield


def plugin_data_dir(plugin_id: str) -> Path:
    """Return the data directory path for a plugin id without creating it.

    Args:
        plugin_id: Plugin id in `{name}@{marketplace}` form.

    Returns:
        Path under the plugin storage root's `data/` directory.
    """
    return plugin_storage_root() / "data" / sanitize_plugin_id(plugin_id)


def ensure_plugin_data_dir(plugin_id: str) -> Path:
    """Return the lazily-created data directory for a plugin id."""
    data_dir = plugin_data_dir(plugin_id)
    data_dir.mkdir(parents=True, exist_ok=True)
    return data_dir


def sanitize_plugin_id(value: str) -> str:
    """Return a bounded, collision-resistant filesystem key.

    Args:
        value: Identity string to encode.

    Returns:
        Filesystem-safe plugin id.
    """
    slug = "".join(
        ch if ch.isascii() and (ch.isalnum() or ch in {"_", "-"}) else "-"
        for ch in value
    )
    slug = slug.strip("-")[:_CACHE_SLUG_LENGTH] or "plugin"
    digest = sha256(value.encode()).hexdigest()[:_CACHE_DIGEST_LENGTH]
    return f"{slug}-{digest}"


def opaque_cache_key(value: str) -> str:
    """Return a cache key that cannot disclose source credentials."""
    return sha256(value.encode()).hexdigest()


def ensure_marketplace_cache_dir() -> Path:
    """Return the marketplace cache directory."""
    path = plugin_storage_root() / "marketplaces"
    path.mkdir(parents=True, exist_ok=True)
    return path


def ensure_plugin_install_cache_dir() -> Path:
    """Return the versioned plugin install cache root."""
    path = plugin_storage_root() / "cache"
    path.mkdir(parents=True, exist_ok=True)
    return path


def versioned_cache_path(plugin_id: str, version: str | None) -> Path:
    """Return the versioned cache path for a plugin id.

    Args:
        plugin_id: Plugin id in `{name}@{marketplace}` form.
        version: Plugin version string, or `None` when unversioned.

    Returns:
        Cache directory `cache/{marketplace}/{plugin}/{version}/`, relative to
        the plugin storage root.

    """
    plugin_name, marketplace = split_plugin_id(plugin_id)
    safe_version = sanitize_plugin_id(version or _UNVERSIONED_CACHE_KEY)
    return (
        ensure_plugin_install_cache_dir()
        / sanitize_plugin_id(marketplace)
        / sanitize_plugin_id(plugin_name)
        / safe_version
    )


def _state_dir() -> Path:
    from deepagents_code.model_config import DEFAULT_STATE_DIR

    return DEFAULT_STATE_DIR


def _marketplaces_path() -> Path:
    return _state_dir() / "plugin_marketplaces.json"


def _plugin_state_path() -> Path:
    return _state_dir() / "plugin_state.json"


def _installed_plugins_path() -> Path:
    return _state_dir() / "installed_plugins.json"


def _available_updates_path() -> Path:
    return _state_dir() / "plugin_updates.json"


def _invalid_state(
    path: Path, detail: str, *, strict: bool, cause: Exception | None = None
) -> dict[str, Any]:
    msg = f"Plugin state file {path} {detail}"
    if strict:
        raise PluginStateError(msg) from cause
    logger.warning("%s", msg)
    return {}


def _load_json(
    path: Path,
    *,
    max_version: int = _STORAGE_VERSION,
    strict: bool = False,
) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return _invalid_state(
            path, f"could not be read: {exc}", strict=strict, cause=exc
        )
    if not isinstance(data, dict):
        return _invalid_state(path, "is not a JSON object", strict=strict)
    version = data.get("version")
    if version is not None and (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version > max_version
    ):
        return _invalid_state(
            path, f"has unsupported version {version!r}", strict=strict
        )
    return data


def _raise_state_shape(path: Path, detail: str) -> Never:
    msg = f"Plugin state file {path} {detail}"
    raise PluginStateError(msg)


def _atomic_write_json(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, sort_keys=True)
            f.write("\n")
        Path(tmp_name).replace(path)
    except Exception:
        with suppress(OSError):
            Path(tmp_name).unlink()
        raise


def load_marketplace_records(*, strict: bool = False) -> dict[str, MarketplaceRecord]:
    """Load marketplace records, including defaults not explicitly removed.

    Returns:
        Marketplace records keyed by marketplace name.
    """
    data = _load_json(_marketplaces_path(), strict=strict)
    raw_records = data.get("marketplaces", {})
    if not isinstance(raw_records, dict):
        if strict:
            _raise_state_shape(_marketplaces_path(), "has invalid marketplaces data")
        return {}
    name = "langchain-plugins"
    source = "langchain-ai/langchain-plugins"
    location = (
        plugin_storage_root()
        / "marketplaces"
        / (f"repository-{opaque_cache_key(f'marketplace-github-{source}')}")
    )
    records: dict[str, MarketplaceRecord] = {}
    if name not in raw_records:
        records[name] = MarketplaceRecord(
            name=name,
            source_type="github",
            source=source,
            install_location=str(location),
        )
    for name, record in raw_records.items():
        if not isinstance(name, str) or not isinstance(record, dict):
            continue
        source_type = record.get("source_type")
        source = record.get("source")
        if (
            source_type not in SUPPORTED_MARKETPLACE_SOURCE_TYPES
            or not isinstance(source, str)
            or not isinstance(record.get("install_location", source), str)
        ):
            logger.debug("Skipping unsupported marketplace record %r", name)
            continue
        ref = record.get("ref")
        records[name] = MarketplaceRecord(
            name=name,
            source_type=source_type,
            source=source,
            install_location=record.get("install_location", source),
            ref=ref if isinstance(ref, str) else None,
        )
    return records


def save_marketplace_record(record: MarketplaceRecord) -> None:
    """Persist a marketplace record."""
    data = _load_json(_marketplaces_path(), strict=True)
    marketplaces = data.get("marketplaces")
    if marketplaces is None:
        marketplaces = {}
    elif not isinstance(marketplaces, dict):
        _raise_state_shape(_marketplaces_path(), "has invalid marketplaces data")
    marketplaces[record.name] = {
        "install_location": record.install_location,
        "source_type": record.source_type,
        "source": record.source,
    }
    if record.ref:
        marketplaces[record.name]["ref"] = record.ref
    _atomic_write_json(
        _marketplaces_path(),
        {"version": _STORAGE_VERSION, "marketplaces": marketplaces},
    )


def remove_marketplace_record(name: str) -> bool:
    """Remove a marketplace record.

    Returns:
        `True` when a record was removed.
    """
    data = _load_json(_marketplaces_path(), strict=True)
    marketplaces = data.get("marketplaces")
    if marketplaces is None:
        marketplaces = {}
    if not isinstance(marketplaces, dict):
        _raise_state_shape(_marketplaces_path(), "has invalid marketplaces data")
    if name not in load_marketplace_records(strict=True):
        return False
    marketplaces.pop(name, None)
    if name == "langchain-plugins":
        marketplaces[name] = None
    _atomic_write_json(
        _marketplaces_path(),
        {"version": _STORAGE_VERSION, "marketplaces": marketplaces},
    )
    return True


def load_enabled_plugin_ids(*, strict: bool = False) -> frozenset[str]:
    """Load enabled plugin ids.

    Returns:
        Enabled plugin ids.
    """
    data = _load_json(_plugin_state_path(), strict=strict)
    enabled = data.get("enabledPlugins", {})
    if not isinstance(enabled, dict):
        if strict:
            _raise_state_shape(_plugin_state_path(), "has invalid enabledPlugins data")
        return frozenset()
    if strict and any(
        not isinstance(key, str) or not isinstance(value, bool)
        for key, value in enabled.items()
    ):
        _raise_state_shape(_plugin_state_path(), "has malformed enabledPlugins entries")
    return frozenset(
        key for key, value in enabled.items() if isinstance(key, str) and value is True
    )


def _write_plugin_state(*, enabled_plugin_ids: set[str]) -> None:
    _atomic_write_json(
        _plugin_state_path(),
        {
            "version": _STORAGE_VERSION,
            "enabledPlugins": dict.fromkeys(sorted(enabled_plugin_ids), True),
        },
    )


def set_plugin_enabled(plugin_id: str, enabled: bool) -> None:
    """Persist a plugin enablement value."""
    enabled_plugin_ids = set(load_enabled_plugin_ids(strict=True))
    if enabled:
        enabled_plugin_ids.add(plugin_id)
    else:
        enabled_plugin_ids.discard(plugin_id)
    _write_plugin_state(enabled_plugin_ids=enabled_plugin_ids)


def load_available_plugin_updates() -> dict[str, str]:
    """Load the plugin versions the last update check found but did not install.

    Returns:
        Available version keyed by plugin id; empty when unreadable.
    """
    available = _load_json(_available_updates_path()).get("available", {})
    if not isinstance(available, dict):
        return {}
    return {
        key: value
        for key, value in available.items()
        if isinstance(key, str) and isinstance(value, str)
    }


def save_available_plugin_updates(available: dict[str, str]) -> None:
    """Persist the plugin versions found by an update check."""
    _atomic_write_json(
        _available_updates_path(),
        {"version": _STORAGE_VERSION, "available": dict(sorted(available.items()))},
    )


def _parse_installed_plugin_json_entry(
    persisted_entry: object,
) -> InstalledPluginEntry | None:
    if not isinstance(persisted_entry, dict):
        return None
    install_path = persisted_entry.get("installPath") or persisted_entry.get(
        "install_path"
    )
    version = persisted_entry.get("version")
    if (
        not isinstance(install_path, str)
        or not install_path
        or (version is not None and (not isinstance(version, str) or not version))
    ):
        return None
    return InstalledPluginEntry(
        install_path=install_path,
        version=version if isinstance(version, str) else None,
    )


def load_installed_plugins(*, strict: bool = False) -> dict[str, InstalledPluginEntry]:
    """Load installed plugin records.

    Returns:
        Map of plugin id to its install entry.
    """
    data = _load_json(
        _installed_plugins_path(),
        max_version=_INSTALLED_STORAGE_VERSION,
        strict=strict,
    )
    raw_plugins = data.get("plugins", {})
    if not isinstance(raw_plugins, dict):
        if strict:
            _raise_state_shape(_installed_plugins_path(), "has invalid plugins data")
        return {}
    result: dict[str, InstalledPluginEntry] = {}
    for plugin_id, entries in raw_plugins.items():
        if not isinstance(plugin_id, str) or not isinstance(entries, list):
            if strict:
                _raise_state_shape(
                    _installed_plugins_path(), "has malformed plugin entries"
                )
            continue
        parsed = next(
            (
                entry
                for item in entries
                if (entry := _parse_installed_plugin_json_entry(item))
            ),
            None,
        )
        if parsed is not None:
            result[plugin_id] = parsed
        elif strict:
            _raise_state_shape(
                _installed_plugins_path(), f"has malformed entry for {plugin_id!r}"
            )
    return result


def _entry_to_json(entry: InstalledPluginEntry) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "installPath": entry.install_path,
    }
    if entry.version is not None:
        payload["version"] = entry.version
    return payload


def _write_installed_plugins(
    plugins: dict[str, InstalledPluginEntry],
) -> None:
    _atomic_write_json(
        _installed_plugins_path(),
        {
            "version": _INSTALLED_STORAGE_VERSION,
            "plugins": {
                plugin_id: [_entry_to_json(entry)]
                for plugin_id, entry in sorted(plugins.items())
            },
        },
    )


def add_installed_plugin(
    plugin_id: str,
    *,
    install_path: str,
    version: str | None,
) -> InstalledPluginEntry:
    """Add or replace the record for `plugin_id` in `installed_plugins.json`.

    Args:
        plugin_id: Plugin id in `{name}@{marketplace}` form.
        install_path: Absolute path to the cached plugin root.
        version: Version declared by the plugin manifest, if any.

    Returns:
        The written install entry.

    """
    plugins = dict(load_installed_plugins(strict=True))
    entry = InstalledPluginEntry(
        install_path=install_path,
        version=version,
    )
    plugins[plugin_id] = entry
    _write_installed_plugins(plugins)
    return entry


def get_primary_install_entry(plugin_id: str) -> InstalledPluginEntry | None:
    """Return the install entry for a plugin id."""
    return load_installed_plugins().get(plugin_id)


def install_path_exists(install_path: str) -> bool:
    """Return whether a registered install path is an existing directory."""
    try:
        return Path(install_path).is_dir()
    except OSError, RuntimeError:
        return False


def remove_installed_plugin(
    plugin_id: str,
) -> InstalledPluginEntry | None:
    """Remove the install record for a plugin.

    Args:
        plugin_id: Plugin id.

    Returns:
        Removed install entry, if present.
    """
    plugins = dict(load_installed_plugins(strict=True))
    removed = plugins.pop(plugin_id, None)
    _write_installed_plugins(plugins)
    return removed


def cache_and_register_plugin(
    plugin_id: str,
    source_dir: Path,
    *,
    version: str | None,
    validate: Callable[[Path], None] | None = None,
    refresh: bool = False,
) -> Path:
    """Copy a plugin into the versioned cache and register the install.

    Args:
        plugin_id: Plugin id in `{name}@{marketplace}` form.
        source_dir: Source plugin root to copy from.
        version: Version declared by the plugin manifest, if any.
        validate: Optional validation to run before registering the cache.
        refresh: Replace an existing versioned cache instead of reusing it,
            so a damaged copy is restored from source.

    Returns:
        Absolute path to the cached plugin root.

    Raises:
        FileNotFoundError: If `source_dir` is not an existing directory.
        OSError: If the cache cannot be copied or atomically replaced.
    """
    source = source_dir.resolve()
    if not source.is_dir():
        msg = f"Plugin source directory not found: {source}"
        raise FileNotFoundError(msg)

    cache_path = versioned_cache_path(plugin_id, version)
    if not refresh and cache_path.exists() and version is not None:
        try:
            if any(cache_path.iterdir()):
                if validate is not None:
                    validate(cache_path)
                add_installed_plugin(
                    plugin_id,
                    install_path=str(cache_path),
                    version=version,
                )
                return cache_path
        except OSError:
            pass

    cache_path.parent.mkdir(parents=True, exist_ok=True)
    temp_dir = cache_path.parent / f".{cache_path.name}.tmp-{os.getpid()}"
    backup_dir = cache_path.parent / f".{cache_path.name}.backup-{os.getpid()}"
    if temp_dir.exists():
        shutil.rmtree(temp_dir, ignore_errors=True)
    if backup_dir.exists():
        shutil.rmtree(backup_dir, ignore_errors=True)
    try:
        shutil.copytree(source, temp_dir, symlinks=True, dirs_exist_ok=False)
        git_dir = temp_dir / ".git"
        if git_dir.exists():
            shutil.rmtree(git_dir, ignore_errors=True)
        if validate is not None:
            validate(temp_dir)
        if cache_path.exists():
            cache_path.replace(backup_dir)
        try:
            temp_dir.replace(cache_path)
        except OSError:
            if backup_dir.exists() and not cache_path.exists():
                backup_dir.replace(cache_path)
            raise
        shutil.rmtree(backup_dir, ignore_errors=True)
    except Exception:
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise

    add_installed_plugin(
        plugin_id,
        install_path=str(cache_path.resolve()),
        version=version,
    )
    return cache_path.resolve()


def uninstall_plugin(
    plugin_id: str,
) -> None:
    """Disable a plugin, remove install records, and delete orphaned cache dirs.

    Args:
        plugin_id: Plugin id in `{name}@{marketplace}` form.
    """
    load_installed_plugins(strict=True)
    load_enabled_plugin_ids(strict=True)
    removed = remove_installed_plugin(plugin_id)

    set_plugin_enabled(plugin_id, False)

    if removed is not None:
        path = Path(removed.install_path)
        if path.is_dir():
            shutil.rmtree(path, ignore_errors=True)

libs/code/deepagents_code/provider_tool_:
"""Provider-native discovery for MCP tools on supported models."""

from __future__ import annotations

import logging
import re
from typing import TYPE_CHECKING
from urllib.parse import urlparse

from langchain.agents.middleware import ProviderToolSearchMiddleware
from langchain.agents.middleware.types import (
    AgentMiddleware,
    ModelRequest,
    ModelResponse,
    TracePolicy,
    omit_payload,
)
from langchain_core.messages import AIMessage, AnyMessage
from langchain_core.tools import BaseTool

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable, Sequence

logger = logging.getLogger(__name__)


def _supported_endpoint(endpoint: object, provider: str) -> bool:
    """Return whether the endpoint exposes the provider's native request format."""
    if not endpoint:
        return True
    from deepagents_code.model_config import is_langsmith_gateway_host

    parsed = urlparse(str(endpoint))
    if parsed.hostname == f"api.{provider}.com":
        return True
    paths = {"/v1", f"/{provider}/v1"}
    if provider == "anthropic":
        paths.add("/anthropic")
    return (
        parsed.scheme == "https"
        and is_langsmith_gateway_host(parsed.hostname)
        and parsed.path.rstrip("/") in paths
    )


def _supported_provider(request: ModelRequest) -> str | None:
    """Return a supported provider on direct or LangSmith native-format routes."""
    model = request.model
    profile = model.profile or {}
    capability = profile.get("provider_tool_search")
    if capability is False:
        return None
    name = getattr(model, "model_name", None) or getattr(model, "model", "")
    if not isinstance(name, str):
        return None
    from langchain_anthropic import ChatAnthropic
    from langchain_openai import ChatOpenAI

    # Upstream profiles lack a native tool-search capability, and the middleware
    # validates providers only. Keep model gates until upstream exposes one;
    # profile.provider_tool_search overrides automatic detection in the meantime.
    if type(model) is ChatOpenAI:
        endpoint = getattr(model, "openai_api_base", None)
        if capability is not True and not _supported_endpoint(endpoint, "openai"):
            return None
        if (
            model.use_responses_api is False
            or request.model_settings.get("use_responses_api") is False
        ):
            return None
        if name.startswith("openai/"):
            name = name.removeprefix("openai/")
        if capability is True or name in {
            "gpt-5.4",
            "gpt-5.5",
            "gpt-6-astra",
            "gpt-6-sol",
            "gpt-6-luna",
            "gpt-6.1-sol",
        }:
            return "openai"
    if type(model) is ChatAnthropic:
        endpoint = getattr(model, "anthropic_api_url", None)
        if capability is not True and not _supported_endpoint(endpoint, "anthropic"):
            return None
        if name.startswith("anthropic/"):
            name = name.removeprefix("anthropic/")
        if capability is True or re.fullmatch(
            r"claude-(?:sonnet-4[.-][56]|opus-4[.-][5-8]|haiku-4[.-]5|"
            r"(?:sonnet|opus|haiku)-5(?:[.-]5)?|(?:fable|mythos)-5(?:[.-]1)?)"
            r"(?:-\d{8})?",
            name,
        ):
            return "anthropic"
    return None


def _is_search_block(block: dict, provider: str | None) -> bool:
    kind = block.get("type")
    name = str(block.get("name", ""))
    if kind == "non_standard" and isinstance(block.get("value"), dict):
        return _is_search_block(block["value"], provider)
    if provider != "openai" and (
        kind in {"tool_search_call", "tool_search_output"}
        or (
            kind in {"server_tool_call", "server_tool_result"} and name == "tool_search"
        )
    ):
        return True
    return provider != "anthropic" and (
        kind == "tool_search_tool_result"
        or (
            kind in {"server_tool_use", "server_tool_call", "server_tool_result"}
            and name.startswith("tool_search_tool_")
        )
    )


def _portable_history(
    messages: list[AnyMessage], provider: str | None
) -> list[AnyMessage]:
    """Return history with only compatible native search blocks."""
    result = []
    for message in messages:
        if not isinstance(message, AIMessage) or not isinstance(message.content, list):
            result.append(message)
            continue
        content = [
            block
            for block in message.content
            if not isinstance(block, dict) or not _is_search_block(block, provider)
        ]
        extras = dict(message.additional_kwargs)
        outputs = extras.get("tool_outputs")
        if isinstance(outputs, list):
            extras["tool_outputs"] = [
                block
                for block in outputs
                if not isinstance(block, dict) or not _is_search_block(block, provider)
            ]
        result.append(
            message.model_copy(update={"content": content, "additional_kwargs": extras})
            if content != message.content or extras != message.additional_kwargs
            else message
        )
    return result


class MCPProviderToolSearchMiddleware(AgentMiddleware):
    """Defer only currently exposed MCP tools on verified native endpoints."""

    trace_policy = TracePolicy(process_inputs=omit_payload)

    def __init__(self, tools: Sequence[BaseTool]) -> None:
        """Retain eligible identities without modifying executor registrations."""
        self._tools = {id(tool) for tool in tools}
        self._warned: set[tuple[str, str]] = set()

    def _prepare(self, request: ModelRequest) -> ModelRequest:
        provider = _supported_provider(request)
        eligible = [
            tool
            for tool in request.tools
            if isinstance(tool, BaseTool) and id(tool) in self._tools
        ]
        request = request.override(
            messages=_portable_history(request.messages, provider)
        )
        if not eligible:
            return request
        if provider is None:
            key = (
                type(request.model).__name__,
                str(getattr(request.model, "model_name", "")),
            )
            if key not in self._warned:
                logger.warning(
                    "Native MCP tool search is unavailable for %s; using eager tools. "
                    "Use supported models with OpenAI Responses or Anthropic Messages "
                    "on a direct endpoint or LangSmith gateway.",
                    key,
                )
                self._warned.add(key)
            return request
        native: ProviderToolSearchMiddleware = ProviderToolSearchMiddleware(
            searchable_tools=list(eligible)
        )
        return native._prepare_request(request)

    def wrap_model_call(
        self, request: ModelRequest, handler: Callable[[ModelRequest], ModelResponse]
    ) -> ModelResponse:
        """Return the response without changing executor registrations."""
        return handler(self._prepare(request))

    async def awrap_model_call(
        self,
        request: ModelRequest,
        handler: Callable[[ModelRequest], Awaitable[ModelResponse]],
    ) -> ModelResponse:
        """Return the async response after runtime model selection."""
        return await handler(self._prepare(request))

libs/code/deepagents_code/reasoning_effo:
"""Reasoning effort support for `/effort`.

Supported levels and defaults come from LangChain model profiles. Provider
integrations translate the standard `reasoning_effort` constructor parameter
into their native request shapes.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping
from typing import Any

from deepagents_code.model_config import (
    CODEX_PROVIDER,
    ModelConfig,
    ModelSpec,
    get_model_profiles,
)

logger = logging.getLogger(__name__)

_LEGACY_ANTHROPIC_THINKING = {"type": "adaptive", "display": "summarized"}


def _model_profile(
    model_spec: str | None, *, cli_override: dict[str, Any] | None = None
) -> Mapping[str, Any] | None:
    """Return the reasoning-capable profile for `model_spec`.

    Args:
        model_spec: `provider:model` spec for the active model.
        cli_override: Extra profile fields from `--profile-override`, if any.

    Returns:
        The merged model profile when `reasoning_output` is `True`, otherwise
        `None`.
    """
    if not model_spec:
        return None
    entry = get_model_profiles(cli_override=cli_override).get(model_spec)
    profile = cli_override if entry is None else entry.get("profile")
    if profile is None:
        return None
    if not isinstance(profile, Mapping):
        logger.warning(
            "Ignoring model profile for %s with unexpected type %s",
            model_spec,
            type(profile).__name__,
        )
        return None
    reasoning_output = profile.get("reasoning_output")
    if reasoning_output is not None and not isinstance(reasoning_output, bool):
        logger.warning(
            "Ignoring reasoning_output for %s with unexpected type %s",
            model_spec,
            type(reasoning_output).__name__,
        )
        return None
    if reasoning_output is not True:
        return None
    return profile


def supported_efforts_for_model(
    model_spec: str | None, *, cli_override: dict[str, Any] | None = None
) -> tuple[str, ...]:
    """Return the ordered reasoning effort levels supported by `model_spec`.

    Args:
        model_spec: `provider:model` spec for the active model.
        cli_override: Extra profile fields from `--profile-override`, if any.

    Returns:
        Supported effort labels, or an empty tuple when effort is not
        configurable or the profile is malformed.
    """
    profile = _model_profile(model_spec, cli_override=cli_override)
    if profile is None or "reasoning_effort_levels" not in profile:
        return ()
    levels = profile["reasoning_effort_levels"]
    if not isinstance(levels, list):
        logger.warning(
            "Ignoring reasoning_effort_levels for %s with unexpected type %s",
            model_spec,
            type(levels).__name__,
        )
        return ()
    for level in levels:
        if not isinstance(level, str):
            logger.warning(
                "Ignoring reasoning_effort_levels for %s containing type %s",
                model_spec,
                type(level).__name__,
            )
            return ()
    return tuple(levels)


def available_efforts_for_model(
    model_spec: str | None,
    model_params: Mapping[str, Any] | None,
    *,
    cli_override: dict[str, Any] | None = None,
) -> tuple[str, ...]:
    """Return profile efforts compatible with the effective thinking mode.

    Args:
        model_spec: Active `provider:model` specification.
        model_params: Runtime overrides layered over configured model params.
        cli_override: Extra profile fields from `--profile-override`.

    Returns:
        Effort labels allowed by both the profile and thinking mode.
    """
    levels = supported_efforts_for_model(model_spec, cli_override=cli_override)
    parsed = ModelSpec.try_parse(model_spec) if model_spec else None
    if parsed is not None and parsed.provider == "anthropic":
        params = ModelConfig.load().get_effective_kwargs(
            parsed.provider, model_name=parsed.model, overrides=model_params
        )
        thinking = params.get("thinking")
        if isinstance(thinking, Mapping) and thinking.get("type") == "between_tools":
            return tuple(
                level for level in levels if level in {"low", "medium", "high"}
            )
    return tuple(levels)


def default_effort_for_model(
    model_spec: str | None, *, cli_override: dict[str, Any] | None = None
) -> str | None:
    """Return the profile's reasoning effort default independently of its levels.

    Args:
        model_spec: `provider:model` spec for the active model.
        cli_override: Extra profile fields from `--profile-override`, if any.

    Returns:
        The default effort label, or `None` when absent or malformed.
    """
    profile = _model_profile(model_spec, cli_override=cli_override)
    if profile is None or "reasoning_effort_default" not in profile:
        return None
    default = profile["reasoning_effort_default"]
    if not isinstance(default, str):
        logger.warning(
            "Ignoring reasoning_effort_default for %s with unexpected type %s",
            model_spec,
            type(default).__name__,
        )
        return None
    return default


def is_effort_supported_for_model(
    model_spec: str, effort: str, *, cli_override: dict[str, Any] | None = None
) -> bool:
    """Return whether `effort` is a supported level for `model_spec`.

    Args:
        model_spec: `provider:model` spec for the active model.
        effort: Effort label to check.
        cli_override: Extra profile fields from `--profile-override`, if any.

    Returns:
        `True` when the active profile advertises `effort`.
    """
    return effort in supported_efforts_for_model(model_spec, cli_override=cli_override)


def _str_or_none(value: object, *, key: str) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    logger.warning("Ignoring non-str %s of type %s", key, type(value).__name__)
    return None


def _effort_value(model_params: Mapping[str, Any], key: str) -> tuple[bool, str | None]:
    if key not in model_params or model_params[key] is None:
        return False, None
    return True, _str_or_none(model_params[key], key=key)


def _nested_effort_value(
    model_params: Mapping[str, Any], container: str, key: str
) -> tuple[bool, str | None]:
    nested = model_params.get(container)
    if not isinstance(nested, Mapping) or key not in nested or nested[key] is None:
        return False, None
    return True, _str_or_none(nested[key], key=f"{container}.{key}")


def _first_effort_value(
    model_params: Mapping[str, Any], *paths: tuple[str, ...]
) -> str | None:
    for path in paths:
        result = (
            _effort_value(model_params, path[0])
            if len(path) == 1
            else _nested_effort_value(model_params, path[0], path[1])
        )
        present, value = result
        if present:
            return value
    return None


def _effort_paths(provider: str) -> tuple[tuple[str, ...], ...]:
    if provider in {"openai", CODEX_PROVIDER}:
        return (("reasoning", "effort"), ("reasoning_effort",))
    if provider == "anthropic":
        return (
            ("effort",),
            ("reasoning_effort",),
            ("output_config", "effort"),
        )
    if provider == "google_genai":
        return (
            ("thinking_level",),
            ("reasoning_effort",),
            ("thinking_config", "thinking_level"),
        )
    if provider == "fireworks":
        return (("reasoning_effort",), ("model_kwargs", "reasoning_effort"))
    if provider == "xai":
        return (("reasoning_effort",), ("extra_body", "reasoning_effort"))
    return (("reasoning_effort",),)


def _path_is_present(model_params: Mapping[str, Any], path: tuple[str, ...]) -> bool:
    if len(path) == 1:
        return path[0] in model_params
    nested = model_params.get(path[0])
    return isinstance(nested, Mapping) and path[1] in nested


def has_explicit_effort_model_params(
    model_spec: str | None, model_params: dict[str, Any] | None
) -> bool:
    """Return whether canonical or native effort parameters are present.

    Args:
        model_spec: `provider:model` spec for the active model.
        model_params: Per-session model constructor parameters.

    Returns:
        `True` when an explicit effort setting should block persisted restoration.
    """
    if not model_spec or not model_params:
        return False
    parsed = ModelSpec.try_parse(model_spec)
    provider = parsed.provider if parsed is not None else ""
    return any(_path_is_present(model_params, path) for path in _effort_paths(provider))


def current_effort_from_model_params(
    model_spec: str | None, model_params: dict[str, Any] | None
) -> str | None:
    """Read canonical or native effort settings using integration precedence.

    This compatibility reader does not modify the supplied parameters. It only
    reports settings that may come from `--model-params`, `/model`, or a resumed
    thread.

    Args:
        model_spec: `provider:model` spec for the active model.
        model_params: Per-session model constructor parameters.

    Returns:
        The effective configured effort, or `None` when none is recognized.
    """
    if not model_spec or not model_params:
        return None
    parsed = ModelSpec.try_parse(model_spec)
    provider = parsed.provider if parsed is not None else ""

    paths = _effort_paths(provider)
    if provider in {"openai", CODEX_PROVIDER}:
        reasoning = model_params.get("reasoning")
        if isinstance(reasoning, Mapping) and "effort" in reasoning:
            return _str_or_none(reasoning["effort"], key="reasoning.effort")
    elif provider == "anthropic" and "effort" in model_params:
        effort = model_params["effort"]
        if effort is not None:
            return _str_or_none(effort, key="effort")
        return _first_effort_value(model_params, ("output_config", "effort"))
    elif provider == "google_genai" and "thinking_level" in model_params:
        effort = model_params["thinking_level"]
        if effort is not None:
            return _str_or_none(effort, key="thinking_level")
        return _first_effort_value(model_params, ("thinking_config", "thinking_level"))
    elif provider == "fireworks" and all(
        _path_is_present(model_params, path) for path in paths
    ):
        logger.warning("Ignoring conflicting Fireworks reasoning effort parameters")
        return None
    return _first_effort_value(model_params, *paths)


def _remove_nested_key(params: dict[str, Any], container: str, key: str) -> None:
    nested = params.get(container)
    if not isinstance(nested, Mapping):
        return
    remaining = dict(nested)
    remaining.pop(key, None)
    if remaining:
        params[container] = remaining
    else:
        params.pop(container, None)


def without_effort_model_params(
    model_spec: str, existing: dict[str, Any] | None
) -> dict[str, Any] | None:
    """Remove canonical and native effort settings without changing siblings.

    Args:
        model_spec: `provider:model` spec for the active model.
        existing: Current per-session model constructor parameters.

    Returns:
        Cleaned parameters, or `None` when no parameters remain.
    """
    if not existing:
        return None
    cleaned = dict(existing)
    cleaned.pop("reasoning_effort", None)

    parsed = ModelSpec.try_parse(model_spec)
    provider = parsed.provider if parsed is not None else ""
    if provider in {"openai", CODEX_PROVIDER}:
        _remove_nested_key(cleaned, "reasoning", "effort")
    elif provider == "anthropic":
        cleaned.pop("effort", None)
        _remove_nested_key(cleaned, "output_config", "effort")
        if cleaned.get("thinking") == _LEGACY_ANTHROPIC_THINKING:
            cleaned.pop("thinking")
    elif provider == "google_genai":
        cleaned.pop("thinking_level", None)
        _remove_nested_key(cleaned, "thinking_config", "thinking_level")
    elif provider == "fireworks":
        _remove_nested_key(cleaned, "model_kwargs", "reasoning_effort")
    elif provider == "xai":
        _remove_nested_key(cleaned, "extra_body", "reasoning_effort")
    return cleaned or None


def with_effort_model_params(
    model_spec: str, existing: dict[str, Any] | None, effort: str
) -> dict[str, Any]:
    """Replace existing effort settings with the standard flat parameter.

    Args:
        model_spec: `provider:model` spec for the active model.
        existing: Current per-session model constructor parameters.
        effort: Profile-advertised effort label to apply.

    Returns:
        New model parameters containing `reasoning_effort` and all unrelated
        existing settings.
    """
    updated = without_effort_model_params(model_spec, existing) or {}
    updated["reasoning_effort"] = effort
    return updated

libs/code/deepagents_code/tui/modals/cos:
"""Detailed token and estimated-cost breakdown modal."""

from __future__ import annotations

import logging
from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import VerticalScroll
from textual.screen import ModalScreen
from textual.widgets import Markdown, Static

from deepagents_code.clipboard import copy_text_to_clipboard
from deepagents_code.config import get_glyphs
from deepagents_code.tui.modals._cost_breakdown import (
    format_cost_breakdown_table as format_cost_breakdown_table,
)
from deepagents_code.unicode_security import sanitize_control_chars

if TYPE_CHECKING:
    from collections.abc import Callable

    from textual.app import App, ComposeResult

logger = logging.getLogger(__name__)


def open_cost_breakdown(app: App, provider: Callable[[], str]) -> None:
    """Open the live breakdown without stacking duplicate modals."""
    if any(isinstance(screen, CostBreakdownScreen) for screen in app.screen_stack):
        return
    breakdown = provider()
    if not breakdown:
        app.notify("No cost details to show for this session yet.", markup=False)
        return
    app.push_screen(CostBreakdownScreen(breakdown, provider))


class CostBreakdownScreen(ModalScreen[None]):
    """Modal showing the copyable entire-thread token and cost breakdown."""

    can_focus = True
    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("escape", "close", "Close", show=False),
        Binding("c", "copy", "Copy", show=False),
    ]
    CSS = """
    CostBreakdownScreen { align: center middle; }
    CostBreakdownScreen > VerticalScroll {
        width: 86; max-width: 92%; height: auto; max-height: 85%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    CostBreakdownScreen .cost-breakdown-title {
        height: auto; text-style: bold; color: $primary;
        text-align: center; margin-bottom: 1;
    }
    CostBreakdownScreen .cost-breakdown-body {
        height: auto; color: $text; padding: 0;
    }
    CostBreakdownScreen .cost-breakdown-help {
        height: auto; color: $text-muted; text-style: italic;
        text-align: center; margin-top: 1;
    }
    """

    def __init__(self, breakdown: str, provider: Callable[[], str]) -> None:
        """Initialize with a Markdown breakdown and its live provider."""
        super().__init__()
        self._provider = provider
        self._breakdown = sanitize_control_chars(
            breakdown, keep_newlines=True, collapse_whitespace=False
        )

    def compose(self) -> ComposeResult:
        """Compose the breakdown and keyboard help.

        Yields:
            Widgets that make up the modal.
        """
        with VerticalScroll():
            yield Static("Cost & Token Breakdown", classes="cost-breakdown-title")
            yield Markdown(self._breakdown, classes="cost-breakdown-body")
            separator = f" {get_glyphs().separator} "
            yield Static(
                separator.join(("c copy", "Esc close")),
                classes="cost-breakdown-help",
                markup=False,
            )

    def on_mount(self) -> None:
        """Focus the modal and refresh its breakdown while open."""
        self.focus()
        self.set_interval(0.5, self._refresh_breakdown)

    def _refresh_breakdown(self) -> None:
        """Update the displayed and copyable breakdown when costs change."""
        try:
            breakdown = self._provider()
        except Exception:
            logger.debug("Cost breakdown refresh failed", exc_info=True)
            return
        if not breakdown:
            return
        breakdown = sanitize_control_chars(
            breakdown, keep_newlines=True, collapse_whitespace=False
        )
        if breakdown != self._breakdown:
            self._breakdown = breakdown
            self.query_one(".cost-breakdown-body", Markdown).update(breakdown)

    def action_copy(self) -> None:
        """Copy the complete breakdown to the clipboard."""
        success, error = copy_text_to_clipboard(self.app, self._breakdown)
        if success:
            self.app.notify(
                "Token and cost breakdown copied",
                severity="information",
                timeout=2,
                markup=False,
            )
            return
        suffix = f": {error}" if error else ""
        self.app.notify(
            f"Failed to copy{suffix}", severity="warning", timeout=3, markup=False
        )

    def action_close(self) -> None:
        """Dismiss the breakdown modal."""
        self.dismiss(None)

