"""Confirmation modal for switching models with a large context."""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.screen import ModalScreen
from textual.widgets import Static

from deepagents_code._session_stats import format_token_count
from deepagents_code.config import get_glyphs

if TYPE_CHECKING:
    from textual.app import ComposeResult


class ModelSwitchWarningScreen(ModalScreen[bool]):
    """Confirm a model switch that preserves a large conversation context."""

    can_focus = True

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("enter", "confirm", "Switch", show=False, priority=True),
        Binding("escape", "cancel", "Cancel", show=False, priority=True),
    ]

    CSS = """
    ModelSwitchWarningScreen {
        align: center middle;
    }

    ModelSwitchWarningScreen > Vertical {
        width: 76;
        max-width: 90%;
        height: auto;
        background: $surface;
        border: solid $warning;
        padding: 1 2;
    }

    ModelSwitchWarningScreen .model-switch-warning-title {
        text-style: bold;
        color: $warning;
        text-align: center;
        margin-bottom: 1;
    }

    ModelSwitchWarningScreen .model-switch-warning-body {
        height: auto;
        color: $text;
        margin-bottom: 1;
    }

    ModelSwitchWarningScreen .model-switch-warning-help {
        height: auto;
        color: $text-muted;
        text-style: italic;
        text-align: center;
    }
    """

    def __init__(
        self,
        *,
        current_model: str,
        target_model: str,
        context_tokens: int,
        threshold: int,
        approximate: bool,
    ) -> None:
        """Initialize the model-switch warning."""
        super().__init__()
        self._current_model = current_model
        self._target_model = target_model
        self._context_tokens = context_tokens
        self._threshold = threshold
        self._approximate = approximate

    def compose(self) -> ComposeResult:
        """Compose warning copy and keyboard help.

        Yields:
            The modal's static content.
        """
        qualifier = "approximately " if self._approximate else ""
        body = (
            f"This thread currently uses {qualifier}"
            f"{format_token_count(self._context_tokens)} context tokens, above your "
            f"{format_token_count(self._threshold)} warning threshold.\n\n"
            f"Switching from {self._current_model} to {self._target_model} keeps "
            "the conversation, but may discard prompt-cache savings and the new "
            "model may have a different context limit. Run /offload first if you "
            "want to reduce the context."
        )
        glyphs = get_glyphs()
        with Vertical():
            yield Static(
                "Switch models with a large context?",
                classes="model-switch-warning-title",
                markup=False,
            )
            yield Static(
                body,
                classes="model-switch-warning-body",
                markup=False,
            )
            yield Static(
                f"Enter: switch model {glyphs.bullet} Esc: cancel",
                classes="model-switch-warning-help",
                markup=False,
            )

    def on_mount(self) -> None:
        """Focus the modal so its bindings receive keyboard input."""
        self.focus()

    def action_confirm(self) -> None:
        """Authorize the model switch."""
        self.dismiss(True)

    def action_cancel(self) -> None:
        """Leave the current model active."""
        self.dismiss(False)

libs/code/deepagents_code/tui/modals/plu:
"""Pure plugin manager content builders."""

from typing import TYPE_CHECKING, Literal

from textual.content import Content
from textual.widgets.option_list import Option

from deepagents_code.config import get_glyphs

if TYPE_CHECKING:
    from deepagents_code.tui.modals.plugin_manager.models import (
        _MarketplaceRow,
        _PluginRow,
    )


def _plugin_options(
    rows: tuple[_PluginRow, ...],
    *,
    action: Literal["detail", "installed"],
    status: str | None,
) -> list[Option]:
    options: list[Option] = []
    for index, row in enumerate(rows):
        if index > 0:
            options.append(Option(" ", id=f"spacer:{index}", disabled=True))
        options.append(
            Option(_plugin_prompt(row, status=status), id=f"{action}:{row.plugin_id}")
        )
    return options


def _load_state_label(row: _PluginRow) -> str | None:
    glyphs = get_glyphs()
    if row.load_state == "needs_repair":
        return "needs repair"
    if row.load_state == "error":
        return "error"
    if row.load_state == "pending_reload":
        return "pending /reload"
    if row.load_state == "enabled":
        return f"{glyphs.checkmark} enabled"
    return None


def _plugin_prompt(row: _PluginRow, *, status: str | None) -> Content:
    glyphs = get_glyphs()
    _, _, marketplace = row.plugin_id.partition("@")
    meta_parts = [Content.styled("Plugin", "dim"), Content.styled(marketplace, "dim")]
    load_label = _load_state_label(row)
    if load_label:
        if row.load_state == "enabled":
            meta_parts.append(Content.styled(load_label, "bold"))
        elif row.load_state == "error":
            meta_parts.append(Content.styled(load_label, "bold $error"))
        elif row.load_state == "needs_repair":
            meta_parts.append(Content.styled(load_label, "bold $warning"))
        else:
            meta_parts.append(Content.styled(load_label, "dim"))
    if row.available_version:
        meta_parts.append(Content.styled("update available", "bold $warning"))
    if row.skill_count:
        skill_label = "skill" if row.skill_count == 1 else "skills"
        meta_parts.append(Content.styled(f"{row.skill_count} {skill_label}", "dim"))
    if row.load_state == "enabled":
        if row.mcp_connected is True:
            meta_parts.append(Content.styled(f"{glyphs.checkmark} connected", "dim"))
        elif row.mcp_connected is False:
            meta_parts.append(Content.styled("run /reload to connect", "bold $warning"))
    elif (
        row.load_state == "pending_reload"
        and row.session_loaded
        and row.mcp_connected is True
    ):
        meta_parts.append(Content.styled(f"{glyphs.checkmark} connected", "dim"))
    if status:
        meta_parts.append(Content.styled(status, "dim"))
    separator = Content.styled(f" {glyphs.separator} ", "dim")
    return Content.assemble(
        row.label,
        separator,
        separator.join(meta_parts),
        "\n  ",
        Content.styled(row.description or "No description provided.", "dim"),
    )


def _install_details_options(
    *, uninspected: bool = False, inspecting: bool = False
) -> list[Option]:
    options = (
        [
            Option(
                "Inspect contents (downloads source)",
                id="action:inspect",
            )
        ]
        if uninspected and not inspecting
        else []
    )
    return [
        *options,
        Option("Install", id="action:install", disabled=inspecting),
        Option("Back to plugin list", id="details-back"),
    ]


def _installed_details_options(row: _PluginRow, *, divider_width: int) -> list[Option]:
    glyphs = get_glyphs()
    repair = (
        [Option(Content.styled("Reinstall plugin", "bold"), id="action:reinstall")]
        if row.needs_repair
        else []
    )
    update = (
        [Option(f"Update to {row.available_version}", id="action:update")]
        if row.available_version
        else []
    )
    return [
        *repair,
        *update,
        Option(
            "Disable plugin" if row.enabled else "Enable plugin",
            id="action:toggle-enabled",
        ),
        Option(Content.styled("Uninstall", "bold"), id="action:uninstall"),
        Option(
            Content.styled(glyphs.box_horizontal * divider_width, "dim"),
            id="details-divider",
            disabled=True,
        ),
        Option("Back to plugin list", id="details-back"),
    ]


def _component_summary_lines(row: _PluginRow) -> list[str]:
    lines: list[str] = []
    if row.skill_names:
        lines.append(f"Skills: {', '.join(row.skill_names)}")
    elif row.skill_count:
        lines.append(f"Skills: {row.skill_count}")
    if row.mcp_server_names:
        lines.append(f"MCP: {', '.join(row.mcp_server_names)}")
    if row.hook_events:
        lines.append(f"Hooks: {', '.join(row.hook_events)}")
    if row.unsupported_components:
        names = ", ".join(f"{name}/" for name in row.unsupported_components)
        lines.append(f"Unsupported (not loaded): {names}")
    return lines


def _unsupported_summary(components: tuple[str, ...]) -> str:
    return f"Found unsupported: {', '.join(f'{name}/' for name in components)}."


def _will_install_lines(row: _PluginRow) -> list[str]:
    lines = _component_summary_lines(row)
    if row.has_supported_components or row.skill_count:
        return lines
    if row.unsupported_components:
        return [
            "No supported components (skills/MCP/hooks).",
            _unsupported_summary(row.unsupported_components),
        ]
    if row.skill_count is None:
        return ["Contents not inspected. Choose Inspect contents to preview."]
    return [
        "No supported components (skills/MCP/hooks).",
        "agents/ and commands/ are not loaded by deepagents-code.",
    ]


def _installed_component_lines(row: _PluginRow) -> list[str]:
    if row.needs_repair:
        return ["Unavailable until the plugin is reinstalled."]
    lines = _component_summary_lines(row)
    if lines:
        if not row.has_supported_components and row.unsupported_components:
            return [
                "No supported components (skills/MCP/hooks).",
                _unsupported_summary(row.unsupported_components),
            ]
        return lines
    return ["No components found."]


def _status_lines(row: _PluginRow) -> list[Content]:
    glyphs = get_glyphs()
    if row.load_state == "needs_repair":
        return [
            Content.styled(
                "Status: Needs repair — installed files are missing, so this "
                "plugin's tools are unavailable.",
                "$warning",
            ),
            Content.styled(
                "Reinstall to restore its files, or disable it.",
                "dim",
            ),
        ]
    if row.load_state == "error":
        detail = row.load_error or "Plugin failed to load."
        return [
            Content.styled(f"Status: Error — {detail}", "dim"),
            Content.styled("Fix the error, then run /reload.", "dim"),
        ]
    if row.load_state == "disabled":
        return [
            Content.styled("Status: Disabled", "dim"),
            Content.styled("Enable the plugin, then run /reload to load it.", "dim"),
        ]
    if row.load_state == "pending_reload":
        if row.enabled:
            return [
                Content.styled(
                    f"Status: Installed {glyphs.separator} pending /reload", "dim"
                ),
                Content.styled(
                    "Run /reload to load this plugin into the current session.", "dim"
                ),
            ]
        return [
            Content.styled(
                f"Status: Disabled {glyphs.separator} pending /reload", "dim"
            ),
            Content.styled(
                "Run /reload to unload this plugin from the current session.", "dim"
            ),
        ]
    lines = [Content.styled(f"Status: {glyphs.checkmark} Enabled", "$success")]
    if row.mcp_connected is False:
        lines.append(
            Content.styled(
                "Run /reload to rebuild the agent with this plugin's MCP tools.",
                "dim",
            )
        )
    return lines


def _plugin_details_content(row: _PluginRow, *, inspecting: bool = False) -> Content:
    _, _, marketplace = row.plugin_id.partition("@")
    parts: list[Content | str] = [
        Content.styled("Plugin details", "bold"),
        "\n\n",
        Content.styled(row.label, "bold"),
        "\n",
        Content.styled(f"from {marketplace}", "dim"),
    ]
    if row.version:
        parts.extend(["\n", Content.styled(f"Version: {row.version}", "dim")])
    if row.description:
        parts.extend(["\n\n", row.description])
    if row.author:
        parts.extend(["\n\n", Content.styled(f"By: {row.author}", "dim")])
    parts.extend(["\n\n", Content.styled("Will install:", "bold")])
    lines = (
        ["Downloading and inspecting contents..."]
        if inspecting
        else _will_install_lines(row)
    )
    for line in lines:
        parts.extend(["\n  ", Content.styled(line, "dim")])
    parts.extend(
        [
            "\n\n",
            Content.styled(
                "Make sure you trust a plugin before installing, updating, "
                "or using it.",
                "dim",
            ),
        ]
    )
    return Content.assemble(*parts)


def _installed_plugin_details_content(row: _PluginRow) -> Content:
    _, _, marketplace = row.plugin_id.partition("@")
    parts: list[Content | str] = [
        Content.styled(f"{row.label} @ {marketplace}", "bold")
    ]
    if row.version:
        parts.extend(["\n", Content.styled(f"Version: {row.version}", "dim")])
    if row.available_version:
        parts.extend(
            [
                "\n",
                Content.styled(
                    f"Update available: {row.available_version}", "bold $warning"
                ),
            ]
        )
    if row.description:
        parts.extend(["\n\n", row.description])
    if row.author:
        parts.extend(["\n\n", Content.styled(f"Author: {row.author}", "dim")])
    parts.extend(["\n\n"])
    for index, line in enumerate(_status_lines(row)):
        if index:
            parts.append("\n")
        parts.append(line)
    parts.extend(["\n\n", Content.styled("Installed components:", "bold")])
    for line in _installed_component_lines(row):
        parts.extend(["\n  ", Content.styled(line, "dim")])
    return Content.assemble(*parts)


def _marketplace_label(row: _MarketplaceRow) -> Content:
    glyphs = get_glyphs()
    prefix = f"{row.name} {glyphs.bullet} {row.source} {glyphs.bullet} "
    if row.has_error:
        return Content.assemble(
            prefix,
            Content.styled(f"{glyphs.error} Error", "$error"),
        )
    return Content.assemble(prefix, f"{row.plugin_count} available")


def _marketplace_details_options() -> list[Option]:
    return [
        Option(
            Content.styled("Remove marketplace", "bold"), id="action:remove-marketplace"
        ),
        Option("Back to marketplace list", id="details-back"),
    ]


def _confirm_marketplace_removal_options(row: _MarketplaceRow) -> list[Option]:
    label = "installed plugin" if row.installed_count == 1 else "installed plugins"
    return [
        Option(
            Content.styled(
                f"Remove marketplace and {row.installed_count} {label}", "bold"
            ),
            id="action:confirm-remove-marketplace",
        ),
        Option("Cancel", id="details-back"),
    ]


def _marketplace_details_content(row: _MarketplaceRow) -> Content:
    available = "Unavailable" if row.has_error else f"{row.plugin_count} available"
    return Content.assemble(
        Content.styled(row.name, "bold"),
        "\n",
        Content.styled(f"Source: {row.source}", "dim"),
        "\n",
        Content.styled(f"Plugins: {available}", "dim"),
        "\n",
        Content.styled(f"Installed: {row.installed_count}", "dim"),
    )


def _marketplace_removal_content(row: _MarketplaceRow) -> Content:
    suffix = "s" if row.installed_count != 1 else ""
    if row.installed_count:
        detail = (
            f"This removes the marketplace and uninstalls {row.installed_count} "
            f"plugin{suffix} from it."
        )
    else:
        detail = "This removes the marketplace from your installed list."
    return Content.assemble(
        Content.styled(f"Remove marketplace {row.name}?", "bold"),
        "\n\n",
        Content.styled(detail, "dim"),
    )

libs/code/deepagents_code/tui/modals/res:
"""Action modal shown when policy blocks a launch-time thread resume."""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar, Literal

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.content import Content
from textual.screen import ModalScreen
from textual.widgets import Static

from deepagents_code.config import get_glyphs
from deepagents_code.unicode_security import sanitize_control_chars

if TYPE_CHECKING:
    from textual.app import ComposeResult
    from textual.events import Click


ResumeBlockedChoice = Literal["new", "exit"]
"""Outcome of the blocked-resume action modal."""


class _ChoiceOption(Static):
    """One selectable action row."""

    def __init__(self, choice: ResumeBlockedChoice, label: str) -> None:
        super().__init__(markup=False, classes="resume-blocked-choice")
        self.choice = choice
        self._label = label
        self._selected = False

    def set_selected(self, selected: bool) -> None:
        """Update cursor styling for this row."""
        self._selected = selected
        self.set_class(selected, "-selected")
        self.update(self._render())

    def _render(self) -> Content:
        """Render the row with the active terminal's cursor glyph.

        Returns:
            The plain-text action row.
        """
        cursor = get_glyphs().cursor if self._selected else " "
        return Content(f"{cursor} {self._label}")

    def on_click(self, event: Click) -> None:  # noqa: PLR6301
        """Keep action activation keyboard-only."""
        event.stop()


class ResumeBlockedScreen(ModalScreen[ResumeBlockedChoice]):
    """Ask whether to start a new session or exit after a blocked resume."""

    can_focus = True

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("escape", "exit_app", "Exit", show=False, priority=True),
        Binding("up", "move_up", "Up", show=False, priority=True),
        Binding("k", "move_up", "Up", show=False, priority=True),
        Binding("down", "move_down", "Down", show=False, priority=True),
        Binding("j", "move_down", "Down", show=False, priority=True),
        Binding("tab", "move_down", "Next", show=False, priority=True),
        Binding("shift+tab", "move_up", "Previous", show=False, priority=True),
        Binding("enter", "activate", "Select", show=False, priority=True),
    ]

    CSS = """
    ResumeBlockedScreen {
        align: center middle;
    }

    ResumeBlockedScreen > Vertical {
        width: 72;
        max-width: 90%;
        height: auto;
        background: $surface;
        border: solid $warning;
        padding: 1 2;
    }

    ResumeBlockedScreen .resume-blocked-title {
        text-style: bold;
        color: $warning;
        text-align: center;
        margin-bottom: 1;
    }

    ResumeBlockedScreen .resume-blocked-body {
        height: auto;
        color: $text;
        margin-bottom: 1;
    }

    ResumeBlockedScreen .resume-blocked-choice {
        height: auto;
        padding: 0 1;
        color: $text;
    }

    ResumeBlockedScreen .resume-blocked-choice.-selected {
        background: $surface-lighten-1;
    }

    ResumeBlockedScreen .resume-blocked-help {
        height: auto;
        color: $text-muted;
        text-style: italic;
        text-align: center;
        margin-top: 1;
    }
    """

    def __init__(self, reason: str) -> None:
        """Initialize the prompt with the policy-safe resume failure reason."""
        super().__init__()
        self._reason = sanitize_control_chars(reason)
        self._options: list[_ChoiceOption] = []
        self._selected = 0

    def compose(self) -> ComposeResult:
        """Compose the blocked-resume prompt.

        Yields:
            Title, explanation, and keyboard help.
        """
        glyphs = get_glyphs()
        with Vertical():
            yield Static(
                "Thread can't be resumed",
                classes="resume-blocked-title",
                markup=False,
            )
            yield Static(
                f"{self._reason}\n\nChoose what to do next.",
                classes="resume-blocked-body",
                markup=False,
            )
            for choice, label in (
                ("new", "Start a new session"),
                ("exit", "Exit"),
            ):
                option = _ChoiceOption(choice, label)
                self._options.append(option)
                yield option
            yield Static(
                f"{glyphs.arrow_up}/{glyphs.arrow_down}: navigate "
                f"{glyphs.separator} Enter: select {glyphs.separator} Esc: exit",
                classes="resume-blocked-help",
                markup=False,
            )

    def on_mount(self) -> None:
        """Focus the modal and select the fresh-session action."""
        self.focus()
        self._options[0].set_selected(selected=True)

    def _move(self, offset: int) -> None:
        """Move the selection by the requested offset."""
        self._options[self._selected].set_selected(selected=False)
        self._selected = (self._selected + offset) % len(self._options)
        self._options[self._selected].set_selected(selected=True)

    def action_move_up(self) -> None:
        """Move the selection to the previous action."""
        self._move(-1)

    def action_move_down(self) -> None:
        """Move the selection to the next action."""
        self._move(1)

    def action_activate(self) -> None:
        """Resolve with the selected action."""
        self.dismiss(self._options[self._selected].choice)

    def action_exit_app(self) -> None:
        """Stop the launch."""
        self.dismiss("exit")

    def action_cancel(self) -> None:
        """Treat app-level cancellation as an exit choice."""
        self.action_exit_app()

"""Prompt for compacting a large resumed thread."""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.screen import ModalScreen
