"""Confirmation prompt for resuming a thread owned by another agent."""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar, Literal

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.screen import ModalScreen
from textual.widgets import Static

from deepagents_code.config import get_glyphs

if TYPE_CHECKING:
    from textual.app import ComposeResult


ThreadAgentSwitchChoice = Literal["switch", "cancel"]
"""Outcome of the cross-agent thread resume prompt."""


class ThreadAgentSwitchPromptScreen(ModalScreen[ThreadAgentSwitchChoice]):
    """Ask before changing agents to resume a thread."""

    can_focus = True
    can_focus_children = False

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("enter", "switch", "Switch", show=False, priority=True),
        Binding("escape", "cancel", "Cancel", show=False, priority=True),
        Binding(
            "ctrl+c",
            "quit_or_interrupt",
            "Quit/Interrupt",
            show=False,
            priority=True,
        ),
        Binding("ctrl+d", "quit_app", "Quit", show=False, priority=True),
    ]

    CSS = """
    ThreadAgentSwitchPromptScreen {
        align: center middle;
    }

    ThreadAgentSwitchPromptScreen > Vertical {
        width: 72;
        max-width: 90%;
        height: auto;
        background: $surface;
        border: solid $warning;
        padding: 1 2;
    }

    ThreadAgentSwitchPromptScreen .thread-agent-switch-title {
        text-style: bold;
        color: $warning;
        text-align: center;
        margin-bottom: 1;
    }

    ThreadAgentSwitchPromptScreen .thread-agent-switch-body {
        height: auto;
        color: $text;
        margin-bottom: 1;
    }

    ThreadAgentSwitchPromptScreen .thread-agent-switch-help {
        /* `auto`, not `1`: the help line is 38 cells, so it wraps once the
           dialog is narrower than ~48 columns, and a fixed single row clips
           the wrapped remainder -- which is the `Esc: cancel` half. The
           cancel affordance must not disappear in narrow terminals. */
        height: auto;
        color: $text-muted;
        text-style: italic;
        text-align: center;
    }
    """

    def __init__(
        self,
        *,
        thread_id: str,
        current_agent: str,
        thread_agent: str,
    ) -> None:
        """Initialize the prompt.

        Args:
            thread_id: Thread the user asked to resume.
            current_agent: Agent active in the current session.
            thread_agent: Agent that owns the requested thread.
        """
        super().__init__()
        self._resume_thread_id = thread_id
        self._current_agent = current_agent
        self._thread_agent = thread_agent

    def _body_text(self) -> str:
        """Explain the agent transition and its persistence scope.

        Returns:
            Plain-text prompt body.
        """
        return (
            f"Thread {self._resume_thread_id} belongs to agent "
            f"{self._thread_agent}, but {self._current_agent} is active.\n\n"
            f"Switch to {self._thread_agent} and resume this thread? The local "
            "agent server will restart. Your saved default agent will not change."
        )

    def compose(self) -> ComposeResult:
        """Compose the confirmation dialog.

        Yields:
            Title, explanation, and keyboard help.
        """
        with Vertical():
            yield Static(
                "Switch agents to resume?",
                classes="thread-agent-switch-title",
                markup=False,
            )
            yield Static(
                self._body_text(),
                classes="thread-agent-switch-body",
                markup=False,
            )
            yield Static(
                f"Enter: switch and resume {get_glyphs().separator} Esc: cancel",
                classes="thread-agent-switch-help",
                markup=False,
            )

    def on_mount(self) -> None:
        """Focus the modal so its bindings receive keyboard input."""
        self.focus()

    def action_switch(self) -> None:
        """Confirm the agent switch and resume."""
        self.dismiss("switch")

    def action_cancel(self) -> None:
        """Keep the current agent and thread."""
        self.dismiss("cancel")

libs/code/deepagents_code/tui/widgets/up:
"""Dedicated modal for the update-available notification.

Shown automatically at startup when a newer version of
`deepagents-code` is available on PyPI. Surfaces the same actions the
notification center would offer for the update entry but with a
focused, single-purpose presentation instead of the generic
notification list.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.content import Content
from textual.message import Message
from textual.screen import ModalScreen
from textual.widgets import Static

if TYPE_CHECKING:
    from textual.app import ComposeResult
    from textual.events import Click

    from deepagents_code.notifications import NotificationAction, PendingNotification

from deepagents_code import theme
from deepagents_code._version import CHANGELOG_URL
from deepagents_code.config import get_glyphs, is_ascii_mode
from deepagents_code.notifications import ActionId
from deepagents_code.tui.key_hints import modal_navigation_hint
from deepagents_code.tui.widgets._links import open_url_async


class ChangelogClicked(Message):
    """Posted when the changelog row is clicked with the mouse."""


class _ActionOption(Static):
    """Clickable single-line action row."""

    def __init__(self, action: NotificationAction, widget_id: str) -> None:
        """Initialize the action row widget.

        Args:
            action: The action this row represents.
            widget_id: DOM id assigned to the widget.
        """
        super().__init__(id=widget_id, classes="ua-action")
        self._action = action
        self._is_selected = False
        self.update(self._render())

    @property
    def action(self) -> NotificationAction:
        """Underlying action."""
        return self._action

    def set_selected(self, selected: bool) -> None:
        """Toggle selection styling.

        Args:
            selected: Whether this row is currently under the cursor.
        """
        if self._is_selected == selected:
            return
        self._is_selected = selected
        self.set_class(selected, "-selected")
        self.update(self._render())

    def _render(self) -> Content:
        glyphs = get_glyphs()
        cursor = glyphs.cursor if self._is_selected else " "
        text = f"{cursor} {self._action.label}"
        if self._action.primary:
            return Content.styled(text, "bold")
        return Content(text)

    def on_click(self, event: Click) -> None:  # noqa: PLR6301  # Textual event handler
        """Swallow the click without activating.

        Clicks on action rows are intentionally disabled to prevent
        accidentally triggering `Install now`, `Skip this version`, or
        similar destructive/irreversible actions. Activation is
        keyboard-only (enter). The changelog row, which only opens a
        URL, still accepts clicks.
        """
        event.stop()


class _ChangelogOption(Static):
    """Secondary row that opens the changelog URL in a browser.

    Visually grouped with the action rows so Tab/Shift+Tab navigation
    covers it uniformly, but activating it does not dismiss the modal
    — it is a "view more info" action, not one of the three
    mutually-exclusive update dispositions.
    """

    def __init__(self) -> None:
        """Initialize the changelog row."""
        super().__init__(id="ua-changelog", classes="ua-action ua-changelog")
        self._is_selected = False
        self.update(self._render())

    def set_selected(self, selected: bool) -> None:
        """Toggle selection styling.

        Args:
            selected: Whether this row is currently under the cursor.
        """
        if self._is_selected == selected:
            return
        self._is_selected = selected
        self.set_class(selected, "-selected")
        self.update(self._render())

    def _render(self) -> Content:
        glyphs = get_glyphs()
        cursor = glyphs.cursor if self._is_selected else " "
        return Content(f"{cursor} View changelog")

    def on_click(self, event: Click) -> None:
        """Dispatch a click as a `ChangelogClicked` message."""
        event.stop()
        self.post_message(ChangelogClicked())


class UpdateAvailableScreen(ModalScreen[ActionId | None]):
    """Modal dedicated to the update-available notification.

    Renders the entry's title and body, a "View changelog" row, and
    one row per configured action. Dismisses with the selected
    `ActionId`, or `None` on Esc. Activating the changelog row opens
    the URL in a browser and leaves the modal open.
    """

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("escape", "cancel", "Close", show=False),
        Binding("up", "move_up", "Up", show=False, priority=True),
        Binding("k", "move_up", "Up", show=False, priority=True),
        Binding("down", "move_down", "Down", show=False, priority=True),
        Binding("j", "move_down", "Down", show=False, priority=True),
        Binding("tab", "move_down", "Next", show=False, priority=True),
        Binding("shift+tab", "move_up", "Previous", show=False, priority=True),
        Binding("enter", "activate", "Select", show=False, priority=True),
    ]

    CSS = """
    UpdateAvailableScreen {
        align: center middle;
    }

    UpdateAvailableScreen > Vertical {
        width: 68;
        max-width: 90%;
        height: auto;
        max-height: 80%;
        background: $surface;
        border: solid $success;
        padding: 1 2;
    }

    UpdateAvailableScreen .ua-title {
        text-style: bold;
        color: $text-success;
        text-align: center;
        margin-bottom: 1;
    }

    UpdateAvailableScreen .ua-body {
        color: $text-muted;
        margin-bottom: 1;
    }

    UpdateAvailableScreen .ua-action {
        height: auto;
        padding: 0 1;
        color: $text;
    }

    UpdateAvailableScreen .ua-action.-selected {
        background: $surface-lighten-1;
    }

    UpdateAvailableScreen .ua-changelog {
        color: $text-muted;
        margin-bottom: 1;
    }

    UpdateAvailableScreen .ua-help {
        dock: bottom;
        height: auto;
        color: $text-muted;
        text-style: italic;
        margin-top: 1;
        text-align: center;
    }
    """

    def __init__(self, entry: PendingNotification) -> None:
        """Initialize the screen.

        Args:
            entry: Registered notification to render. Its actions
                drive the action rows; dismissing via an action
                returns the chosen `ActionId` to the caller.
        """
        super().__init__()
        self._entry = entry
        self._options: list[_ActionOption | _ChangelogOption] = []
        self._selected = 0

    def compose(self) -> ComposeResult:
        """Compose the modal layout.

        Yields:
            Title, optional body, the changelog row, one
            `_ActionOption` per action, and a help footer.
        """
        glyphs = get_glyphs()
        with Vertical():
            yield Static(self._entry.title, classes="ua-title", markup=False)
            if self._entry.body:
                yield Static(self._entry.body, classes="ua-body", markup=False)
            changelog = _ChangelogOption()
            self._options.append(changelog)
            yield changelog
            for idx, action in enumerate(self._entry.actions):
                option = _ActionOption(action, f"ua-row-{idx}")
                self._options.append(option)
                yield option
            help_text = (
                f"{modal_navigation_hint(glyphs)} "
                f"{glyphs.bullet} Enter select "
                f"{glyphs.bullet} Esc close"
            )
            yield Static(help_text, classes="ua-help")

    def on_mount(self) -> None:
        """Apply ASCII borders and highlight the primary action by default."""
        if is_ascii_mode():
            container = self.query_one(Vertical)
            colors = theme.get_theme_colors(self)
            container.styles.border = ("ascii", colors.success)
        # The changelog row sits at index 0; offset the primary action
        # by 1 so the initial cursor still lands on "Install now".
        primary_idx = next(
            (i + 1 for i, a in enumerate(self._entry.actions) if a.primary),
            1 if self._entry.actions else 0,
        )
        self._set_selected(primary_idx)

    def _set_selected(self, new_index: int) -> None:
        """Move the selection cursor to *new_index*.

        Raises:
            IndexError: When *new_index* is outside `0..len(self._options)`.
        """
        if not self._options:
            return
        if not 0 <= new_index < len(self._options):
            msg = f"selection {new_index} out of range 0..{len(self._options)}"
            raise IndexError(msg)
        if new_index != self._selected:
            self._options[self._selected].set_selected(selected=False)
        self._selected = new_index
        self._options[new_index].set_selected(selected=True)

    def action_move_up(self) -> None:
        """Move the cursor up one row (wraps at the top)."""
        if not self._options:
            return
        self._set_selected((self._selected - 1) % len(self._options))

    def action_move_down(self) -> None:
        """Move the cursor down one row (wraps at the bottom)."""
        if not self._options:
            return
        self._set_selected((self._selected + 1) % len(self._options))

    def action_activate(self) -> None:
        """Fire the highlighted option.

        Activating an action row dismisses the modal with its
        `ActionId`. Activating the changelog row opens the URL and
        leaves the modal open so the user can still pick an action.
        """
        if not self._options:
            self.dismiss(None)
            return
        option = self._options[self._selected]
        if isinstance(option, _ChangelogOption):
            self._open_changelog()
            return
        self.dismiss(option.action.action_id)

    def action_cancel(self) -> None:
        """Close without firing any action."""
        self.dismiss(None)

    def on_changelog_clicked(self, message: ChangelogClicked) -> None:
        """Handle a mouse click on the changelog row."""
        message.stop()
        self._open_changelog()

    def _open_changelog(self) -> None:
        """Open `CHANGELOG_URL` in a browser without closing the modal."""
        self.run_worker(
            open_url_async(CHANGELOG_URL, app=self.app),
            exclusive=False,
            group="update-available-changelog",
        )

"""Confirmation modals for `/update` dependency-refresh flows in the TUI.

When `deepagents-code` itself is already on the latest release, `/update` can
still re-resolve its dependencies to the newest versions allowed by the pinned
ranges (e.g. a new `langchain-openai`). The already-current path dry-runs the
resolution first, then asks for explicit confirmation only when dependencies can
move. `/update --deps` skips that prompt, but asks before taking an available
app update ahead of the dependency refresh for the current app version.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import Vertical
from textual.screen import ModalScreen
from textual.widgets import Static

if TYPE_CHECKING:
    from textual.app import ComposeResult


class _DependencyConfirmScreen(ModalScreen[bool]):
    """Shared base for the `/update` dependency-refresh confirmation modals.

    Subclasses supply only their bindings and the title/body/help text; the base
    owns the layout, styling, and the `True`/`False` dismissal contract. The
    `DEFAULT_CSS` type selector matches subclasses because Textual resolves type
    selectors against every class name in the MRO.
    """

    DEFAULT_CSS = """
    _DependencyConfirmScreen {
        align: center middle;
    }

    _DependencyConfirmScreen > Vertical {
        width: 66;
        max-width: 90%;
        height: auto;
        background: $surface;
        border: solid $primary;
        padding: 1 2;
    }

    _DependencyConfirmScreen .dependency-confirm-title {
        text-style: bold;
        color: $primary;
        text-align: center;
        margin-bottom: 1;
    }

    _DependencyConfirmScreen .dependency-confirm-body {
        height: auto;
        color: $text;
        margin-bottom: 1;
    }

    _DependencyConfirmScreen .dependency-confirm-help {
        height: 1;
        color: $text-muted;
        text-style: italic;
        text-align: center;
    }
    """

    def __init__(self, *, title: str, body: str, help_text: str) -> None:
        """Store the dialog copy for `compose`.

        Args:
            title: Bold heading shown at the top of the dialog.
            body: Explanatory paragraph beneath the title.
            help_text: Muted key-hint row at the bottom.
        """
        super().__init__()
        self._title = title
        self._body = body
        self._help = help_text

    def compose(self) -> ComposeResult:
        """Compose the confirmation dialog.

        Yields:
            Title, body, and help-row widgets parented inside a `Vertical`.
        """
        with Vertical():
            yield Static(
                self._title,
                classes="dependency-confirm-title",
                markup=False,
            )
            yield Static(
                self._body,
                classes="dependency-confirm-body",
                markup=False,
            )
            yield Static(
                self._help,
                classes="dependency-confirm-help",
                markup=False,
            )

    def action_confirm(self) -> None:
        """Dismiss with `True`."""
        self.dismiss(True)

    def action_cancel(self) -> None:
        """Dismiss with `False`.

        The method name must stay `cancel`: the app owns a priority `escape`
        binding that, for an active `ModalScreen`, dispatches to `action_cancel`
        if present and otherwise falls through to `dismiss(None)`. Renaming this
        would silently regress Esc to a `None` dismiss instead of an explicit
        cancel.
        """
        self.dismiss(False)


class UpdateBeforeDependenciesConfirmScreen(_DependencyConfirmScreen):
    """Confirmation overlay before `/update --deps` upgrades dcode itself.

    Dismisses with `True` when the user chooses the app update first and `False`
    when they prefer to refresh dependencies for the current app version.
    """

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("enter", "confirm", "Update", show=False, priority=True),
        Binding("escape", "cancel", "Refresh deps", show=False, priority=True),
    ]

    def __init__(self, *, current: str, latest: str) -> None:
        """Create the app-update confirmation dialog.

        Args:
            current: Currently running `deepagents-code` version.
            latest: Latest available `deepagents-code` version.
        """
        super().__init__(
            title="Update dcode first?",
            body=(
                f"A newer deepagents-code version is available ({current} -> "
                f"{latest}). Update dcode now, or refresh dependencies for the "
                "current version you already have."
            ),
            help_text="Enter to update dcode, Esc to refresh current dependencies",
        )


class RefreshDependenciesConfirmScreen(_DependencyConfirmScreen):
    """Confirmation overlay for a dependency refresh.

    Dismisses with `True` when the user confirms and `False` when the user
    cancels. Esc is treated as cancel so the user is never forced into a refresh
    they did not explicitly choose.
    """

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("enter", "confirm", "Refresh", show=False, priority=True),
        Binding("escape", "cancel", "Cancel", show=False, priority=True),
    ]

    def __init__(self, *, planned_changes: str | None = None) -> None:
        """Create the dependency-refresh confirmation dialog.

        Args:
            planned_changes: Optional dry-run summary of dependency updates.
        """
        body = (
            "deepagents-code is already up to date, but compatible dependency "
            "updates are available. Refresh to apply these changes:\n\n"
            f"{planned_changes}"
            if planned_changes
            else (
                "deepagents-code is already up to date, but its dependencies "
                "can be re-resolved to the newest compatible versions. This may "
                "pull in newer minor releases of packages like langchain-openai."
            )
        )
        super().__init__(
            title="Refresh dependencies?",
            body=body,
            help_text="Enter to refresh, Esc to cancel",
        )

"""Progress modal for app self-update installs."""

from __future__ import annotations

from collections import deque
from typing import TYPE_CHECKING, ClassVar

from textual.binding import Binding, BindingType
from textual.containers import Horizontal, Vertical
from textual.screen import ModalScreen
from textual.widgets import Log, Static

if TYPE_CHECKING:
    from pathlib import Path

    from textual.app import ComposeResult
    from textual.timer import Timer

from deepagents_code import theme
from deepagents_code.config import get_glyphs, is_ascii_mode
from deepagents_code.tui.widgets.loading import Spinner


class UpdateProgressScreen(ModalScreen[None]):
    """Modal that shows self-update progress and a bounded log tail."""

    BINDINGS: ClassVar[list[BindingType]] = [
        Binding("d", "toggle_details", "Details", show=False),
        Binding("c", "copy_log_path", "Copy log path", show=False),
        Binding("q", "quit_app", "Quit", show=False),
        Binding("escape", "cancel", "Close", show=False),
    ]

    CSS = """
    UpdateProgressScreen {
        align: center middle;
    }

    UpdateProgressScreen > Vertical {
        width: 78;
        max-width: 92%;
        height: auto;
        max-height: 85%;
        background: $surface;
        border: solid $primary;
        padding: 1 2;
    }

    UpdateProgressScreen .up-title {
        text-style: bold;
        color: $primary;
        text-align: center;
        margin-bottom: 1;
    }

    UpdateProgressScreen .up-status {
        color: $text;
    }

    UpdateProgressScreen .up-status-row {
        height: auto;
        margin-bottom: 1;
    }

    UpdateProgressScreen .up-spinner {
        width: auto;
        color: $primary;
        margin-right: 1;
    }

    UpdateProgressScreen .up-details,
    UpdateProgressScreen .up-log,
    UpdateProgressScreen Log.up-tail,
    UpdateProgressScreen .up-help {
        color: $text-muted;
    }

    UpdateProgressScreen .up-details {
        margin-top: 1;
        margin-bottom: 1;
    }

    UpdateProgressScreen Log.up-tail {
        height: 10;
        min-height: 10;
        max-height: 10;
        background: $surface-lighten-1;
        border: solid $surface-lighten-1;
        overflow-x: hidden;
    }

    UpdateProgressScreen .up-log {
        margin-top: 1;
        margin-bottom: 1;
    }

    UpdateProgressScreen .up-help {
        height: 1;
        text-style: italic;
        margin-top: 1;
        text-align: center;
    }
    """

    def __init__(
        self,
        *,
        latest: str,
        command: str,
        log_path: Path,
        tail_limit: int = 30,
    ) -> None:
        """Initialize the progress modal.

        Args:
            latest: Version being installed.
            command: Upgrade command being run.
            log_path: Persisted log file path.
            tail_limit: Maximum output lines to keep in memory.
        """
        super().__init__()
        self._latest = latest
        self._command = command
        self._log_path = log_path
        self._tail_limit = tail_limit
        self._tail: deque[str] = deque(maxlen=tail_limit)
        self._details_visible = False
        self._done = False
        self._status = f"Installing v{latest}..."
        self._done_glyph: str | None = None
        self._status_widget: Static | None = None
        self._spinner = Spinner()
        self._spinner_widget: Static | None = None
        self._spinner_timer: Timer | None = None
        self._command_widget: Static | None = None
        self._log_path_widget: Static | None = None
        self._tail_widget: Log | None = None
        self._help_widget: Static | None = None
        self._copy_text: str | None = None
        self._copy_label = "log path"

    def compose(self) -> ComposeResult:
        """Compose the modal.

        Yields:
            Static widgets for status, command, output tail, log path, and help.
        """
        with Vertical():
            yield Static("Updating dcode", classes="up-title")
            with Horizontal(classes="up-status-row"):
                self._spinner_widget = Static(
                    self._spinner.current_frame(),
                    classes="up-spinner",
                    markup=False,
                )
                yield self._spinner_widget
                self._status_widget = Static(
                    self._status, classes="up-status", markup=False
                )
                yield self._status_widget
            self._command_widget = Static(
                f"Running command: {self._command}",
                classes="up-details",
                markup=False,
            )
            self._command_widget.display = False
            yield self._command_widget
            self._tail_widget = Log(
                highlight=False,
                max_lines=self._tail_limit,
                auto_scroll=True,
                classes="up-tail",
            )
            self._tail_widget.display = False
            yield self._tail_widget
            self._log_path_widget = Static(
                f"Log: {self._log_path}",
                classes="up-log",
                markup=False,
            )
            self._log_path_widget.display = False
            yield self._log_path_widget
            self._help_widget = Static(self._help_text(), classes="up-help")
            yield self._help_widget

    def on_mount(self) -> None:
        """Apply ASCII border when configured."""
        if is_ascii_mode():
            container = self.query_one(Vertical)
            colors = theme.get_theme_colors(self)
            container.styles.border = ("ascii", colors.primary)
        self._spinner_timer = self.set_interval(0.1, self._update_spinner)

    def append_line(self, line: str) -> None:
        """Append a command output line to the in-memory tail."""
        self._tail.append(line)
        if self._tail_widget is not None:
            self._tail_widget.write_line(line)

    def mark_success(self) -> None:
        """Render the completed-success state."""
        self._done = True
        self._done_glyph = get_glyphs().checkmark
        self._status = (
            f"Update complete. Quit and relaunch dcode to use v{self._latest}."
        )
        self._stop_spinner_timer()
        self._refresh_status()

    def mark_failure(self, command: str) -> None:
        """Render the completed-failure state.

        Args:
            command: Manual command users can run to retry.
        """
        self._done = True
        self._done_glyph = get_glyphs().error
        self._status = f"Update failed. Try manually: {command}"
        self._details_visible = True
        self._stop_spinner_timer()
        self._refresh_status()
        self._apply_details_visibility()

    def mark_warning(
        self,
        warning: str,
        *,
        copy_text: str | None = None,
        copy_label: str = "fix command",
    ) -> None:
        """Render a completed state that needs user action.

        Args:
            warning: Durable warning text to show in the modal status.
            copy_text: Optional text copied by the `c` key in warning state.
            copy_label: User-facing name for the copied text.
        """
        self._done = True
        self._done_glyph = get_glyphs().warning
        self._status = warning
        self._copy_text = copy_text
        self._copy_label = copy_label
        self._details_visible = True
        self._stop_spinner_timer()
        self._refresh_status()
        self._apply_details_visibility()

    def action_toggle_details(self) -> None:
        """Show or hide the live log tail."""
        self._details_visible = not self._details_visible
        self._apply_details_visibility()

    def action_cancel(self) -> None:
        """Close the modal only after the update command has finished."""
        if self._done:
            self.dismiss(None)

    def action_quit_app(self) -> None:
        """Quit the app once the update command has finished."""
        if self._done:
            self.app.exit()

    def action_copy_log_path(self) -> None:
        """Copy warning action text or the persisted log path."""
        copy_text = self._copy_text
        copy_label = self._copy_label
        if copy_text is None:
            if not self._details_visible:
                return
            copy_text = str(self._log_path)
            copy_label = "log path"
        if not copy_text:
            return
        self.app.copy_to_clipboard(copy_text)
        self.app.notify(
            f"Copied {copy_label}.",
            severity="information",
            timeout=3,
            markup=False,
        )

    def _refresh_status(self) -> None:
        if self._status_widget is not None:
            self._status_widget.update(self._status)
        if self._spinner_widget is not None:
            if self._done:
                self._spinner_widget.update(self._done_glyph or get_glyphs().checkmark)
                self._spinner_widget.display = True
            else:
                self._spinner_widget.display = True
        if self._help_widget is not None:
            self._help_widget.update(self._help_text())

    def _apply_details_visibility(self) -> None:
        if self._tail_widget is None:
            return
        if self._command_widget is not None:
            self._command_widget.display = self._details_visible
        if self._log_path_widget is not None:
            self._log_path_widget.display = self._details_visible
        self._tail_widget.display = self._details_visible
        if self._help_widget is not None:
            self._help_widget.update(self._help_text())

    def _stop_spinner_timer(self) -> None:
        if self._spinner_timer is not None:
            self._spinner_timer.stop()
            self._spinner_timer = None

    def _help_text(self) -> str:
        glyphs = get_glyphs()
        details = "Hide details" if self._details_visible else "Show details"
        close = "Esc close" if self._done else "Esc close when complete"
        parts = [f"d {details}", close]
        if self._copy_text is not None:
            parts.insert(1, f"c copy {self._copy_label}")
        elif self._details_visible:
            parts.insert(1, "c copy log path")
        if self._done:
            parts.append("q quit")
        return f" {glyphs.bullet} ".join(parts)

    def _update_spinner(self) -> None:
        """Advance the glyph spinner while the update is running."""
        if self._done or self._spinner_widget is None:
            return
        self._spinner_widget.update(self._spinner.next_frame())

