)
def test_snapshot_matches_notification_and_skips_tool_mismatch(
    tmp_path: Path, kind: DcodeNotificationKind, matcher: str
) -> None:
    snapshot = HooksSnapshot.from_config(
        _config(
            {
                "Notification": [
                    {
                        "matcher": matcher,
                        "hooks": [{"type": "command", "command": "notify"}],
                    }
                ],
                "PermissionRequest": [
                    {
                        "matcher": "Write",
                        "hooks": [{"type": "command", "command": "write"}],
                    }
                ],
            }
        )
    )
    notification = _invocation(
        tmp_path,
        NotificationEvent(
